CREATE OR REPLACE PACKAGE BODY ADC_PKG_LOAD_USAGE AS

/* GENERALIZZAZIONE AQ FRAMEWORK */
PROCEDURE ENQUEUE_USAGE_INIT(INPUT_ID_SESSION NUMBER,  V_VIRTUAL_QUEUE VARCHAR2, MESSAGE OUT VARCHAR2,ESITO OUT VARCHAR2) IS
  INIT_PROCEDURE    VARCHAR2(200);
  PROCEDURE_CALL    VARCHAR2(1000);
  LOGRESULT         NUMBER;
  INNER_MESSAGGIO   VARCHAR2(200);
  INNER_ESITO       VARCHAR2(200);
  INNER_INPUT_ID_SESSION        VARCHAR2(200);
  INNER_V_VIRTUAL_QUEUE        VARCHAR2(200);
BEGIN
  BEGIN
    SELECT PARAMETER_VALUE INTO INIT_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='INIT_PROCEDURE' AND ROWNUM = 1;
  EXCEPTION WHEN NO_DATA_FOUND THEN
    SELECT PARAMETER_VALUE INTO INIT_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='INIT_PROCEDURE' AND ROWNUM = 1;
  END;

  UPDATE /* ADC_PKG_LOAD_USAGE_U28 */  ADC_TX_JOBID_SESSION SET VIRTUAL_QUEUE = V_VIRTUAL_QUEUE WHERE SESSION_ID=INPUT_ID_SESSION AND VIRTUAL_QUEUE IS NULL;

  IF(INIT_PROCEDURE IS NOT NULL) THEN
     INNER_INPUT_ID_SESSION := INPUT_ID_SESSION;
     INNER_V_VIRTUAL_QUEUE  := V_VIRTUAL_QUEUE;

     PROCEDURE_CALL := 'BEGIN ' ||
                              INIT_PROCEDURE || '(
                              INPUT_ID_SESSION             =>  :INNER_INPUT_ID_SESSION,
                              V_VIRTUAL_QUEUE              =>  :INNER_V_VIRTUAL_QUEUE,
                              MESSAGE                      =>  :INNER_MESSAGGIO,
                              ESITO                        =>  :INNER_ESITO
                              );
                          END;
                          ';
      --INPUT_ID_SESSION NUMBER,  V_VIRTUAL_QUEUE VARCHAR2, MESSAGE OUT VARCHAR2,ESITO OUT VARCHAR2
  END IF;
  BEGIN
    EXECUTE IMMEDIATE PROCEDURE_CALL USING INNER_INPUT_ID_SESSION,INNER_V_VIRTUAL_QUEUE, OUT INNER_MESSAGGIO, OUT INNER_ESITO;
  EXCEPTION WHEN OTHERS THEN
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK -  ERRORE NELL'' INIZIALIZZAZIONE DELLA CODA VIRTUALE ' || V_VIRTUAL_QUEUE || ': ' || SQLERRM || ' - ' || dbms_utility.format_error_backtrace  , ADC_PKG_COMMON.ERROR_LEVEL,'');
  END;

  ESITO:=   INNER_ESITO;
  MESSAGE:= INNER_MESSAGGIO;
END;

/* PROCEDURE E FUNZIONI PRIVATE  ---------------------------------------------------------------------*/

/* {#54} VERIFICA L'ESISTENZA DI UN UNO USAGE IDENTICO A QUELLO CHE SI STA PER INSERIRE
PER EVITARE L'AGGIUNTA DI DUPLICATI */
PROCEDURE CERCA_USAGE_DUPLICATO(rigaUsage ADC_WRK_USAGE%ROWTYPE, chiaveUsageLista CHIAVEUSAGE_TABLE,TID VARCHAR2, IS_DEBUG_ENABLED BOOLEAN, V_ID_USAGE OUT ADC_WRK_USAGE.ID%TYPE) IS

      TEMP_ID_USAGE ADC_WRK_USAGE.ID%TYPE;
      LOGRESULT                   NUMBER;
      L_START                     NUMBER;
      L_END                       NUMBER;
      IN_CONDITION                CLOB;
      MY_TEMP_ID_USAGE            CLOB;
      J                           NUMBER;
      V_IDPROCESSOINTERNO         VARCHAR2(255);
      V_IDALTROPROCESSO           VARCHAR2(255);
      V_CHIAVI_CONDITION          VARCHAR2(32000);
      SKIP_CHIAVI_CHECK           BOOLEAN;
      CONT                       PLS_INTEGER;

      TYPE USAGE_ARRAY IS TABLE OF ADC_WRK_USAGE.ID%TYPE INDEX BY PLS_INTEGER;

      USAGES                      USAGE_ARRAY;

      --diagnostic variables
      DIAGNOSTIC_CODE VARCHAR2(512):='CUD4002';
      DIAGNOSTIC_LN VARCHAR2(512):=ADC_PKG_LOAD_USAGE.DIAGNOSTIC_LOGGER_NAME;
      DIAGNOSTIC_INFO_LEVEL VARCHAR2(512):=ADC_PKG_COMMON.INFO_LEVEL;
      DIAGNOSTIC_RESULT NUMBER;

  BEGIN

    L_START := DBMS_UTILITY.GET_TIME ;  -- Start Time
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CERCA_USAGE_DUPLICATO - BEGIN'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
    DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
    J := CHIAVEUSAGELISTA.FIRST; --SE NON ESISTE ALMENO idProcessoInterno O idAltroProcesso NELLA RICHIESTA LA LISTA E' VUOTA

    IF(J IS NOT NULL) THEN

      V_IDPROCESSOINTERNO := CHIAVEUSAGELISTA(J).IDPROCESSOINTERNO;
      V_IDALTROPROCESSO   := CHIAVEUSAGELISTA(J).IDALTROPROCESSO;

      SKIP_CHIAVI_CHECK := FALSE;

      IF(V_IDPROCESSOINTERNO IS NULL) THEN
        V_CHIAVI_CONDITION := 'ID_PROCESSO_INTERNO IS NULL ';
      ELSE
        V_CHIAVI_CONDITION := 'ID_PROCESSO_INTERNO = ''' || V_IDPROCESSOINTERNO || ''' ';
      END IF;

       IF(V_IDALTROPROCESSO IS NULL) THEN
          V_CHIAVI_CONDITION :=  V_CHIAVI_CONDITION || 'AND ID_ALTRO_PROCESSO IS NULL ';
       ELSE
          V_CHIAVI_CONDITION :=  V_CHIAVI_CONDITION || 'AND ID_ALTRO_PROCESSO = ''' || V_IDALTROPROCESSO   || ''' ';
       END IF;
    ELSE
      SKIP_CHIAVI_CHECK  := TRUE;
      V_CHIAVI_CONDITION := 'TO SKIP';
    END IF;

    IN_CONDITION := NULL;

    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RICERCA CON -' ||
            RIGAUSAGE.DATA_ORA_EVENTO || ' | ' ||
            RIGAUSAGE.FASE_CICLO_VITA|| ' | ' ||
            RIGAUSAGE.SOTTO_FASE_CICLO_VITA|| ' | ' ||
            RIGAUSAGE.SISTEMA_SORGENTE|| ' | ' ||
            RIGAUSAGE.ID_TRACCIATURA || ' | ' ||
            V_IDPROCESSOINTERNO|| ' | ' ||
            V_IDALTROPROCESSO, ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
    CONT :=0;
    FOR USAGE_ITEM IN (SELECT /* ADC_PKG_LOAD_USAGE_S19 */
      ID
    FROM
      ADC_WRK_USAGE
    WHERE
      DATA_ORA_EVENTO       = RIGAUSAGE.DATA_ORA_EVENTO       AND
      FASE_CICLO_VITA       = RIGAUSAGE.FASE_CICLO_VITA       AND
      SOTTO_FASE_CICLO_VITA = RIGAUSAGE.SOTTO_FASE_CICLO_VITA AND
      SISTEMA_SORGENTE      = RIGAUSAGE.SISTEMA_SORGENTE      AND
      (
        (ID_TRACCIATURA  IS NULL AND RIGAUSAGE.ID_TRACCIATURA IS NULL) OR
        (ID_TRACCIATURA  IS NOT NULL AND RIGAUSAGE.ID_TRACCIATURA = ID_TRACCIATURA)
      )AND
      (
        (ID_TRACC_CORR  IS NULL AND RIGAUSAGE.ID_TRACC_CORR IS NULL) OR
        (ID_TRACC_CORR  IS NOT NULL AND RIGAUSAGE.ID_TRACC_CORR = ID_TRACC_CORR)
      )AND
      ROWNUM < 1000
      --AND ID_TRACC_CORR         = rigaUsage.ID_TRACC_CORR;
      )
      LOOP
          IF(IN_CONDITION IS NOT NULL) THEN
            IN_CONDITION := IN_CONDITION || ',';
            --DBMS_LOB.append(IN_CONDITION,IN_CONDITION || ',');
          END IF;

          --MY_TEMP_ID_USAGE :=  IN_CONDITION || USAGE_ITEM.ID;
          --DBMS_LOB.append(IN_CONDITION, MY_TEMP_ID_USAGE);

          IN_CONDITION := IN_CONDITION || USAGE_ITEM.ID ;
          --TEMP_ID_USAGE :=  USAGE_ITEM.ID;
          CONT := CONT + 1;

          USAGES(CONT) := USAGE_ITEM.ID;

      END LOOP;

      IF(IN_CONDITION IS NOT NULL) THEN
        /*LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'SELECT ID_USAGE
                              FROM
                                ADC_WRK_CHIAVI
                              WHERE
                                ID_USAGE            IN (' || IN_CONDITION || ') AND
                                ID_PROCESSO_INTERNO = ''' || CHIAVEUSAGELISTA(J).IDPROCESSOINTERNO || ''' AND
                                ID_ALTRO_PROCESSO   = ''' || CHIAVEUSAGELISTA(J).IDALTROPROCESSO || ''' AND
                                ROWNUM =1', ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);*/
        IF(NOT(SKIP_CHIAVI_CHECK)) THEN
              EXECUTE IMMEDIATE   'SELECT /* ADC_PKG_LOAD_USAGE_S01 */ ID_USAGE
                                  FROM
                                    ADC_WRK_CHIAVI
                                  WHERE
                                    ID_USAGE            IN (' || IN_CONDITION || ') AND
                                    ' ||V_CHIAVI_CONDITION ||' AND
                                    ROWNUM = 1' INTO V_ID_USAGE;

        ELSE
          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME,  'SKIP VERIFICA PER CHIAVI' ,ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
          --V_ID_USAGE := TEMP_ID_USAGE;
          V_ID_USAGE :=  NULL;
          J := USAGES.FIRST;
          WHILE J IS NOT NULL LOOP
            BEGIN
              SELECT /* ADC_PKG_LOAD_USAGE_S02 */ ID_USAGE INTO TEMP_ID_USAGE FROM ADC_WRK_CHIAVI WHERE ID_USAGE = USAGES(J);
            EXCEPTION WHEN NO_DATA_FOUND THEN
              V_ID_USAGE:=USAGES(J);
              EXIT;
            END;
            J := USAGES.NEXT(J);
          END LOOP;
        END IF;

        L_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CERCA_USAGE_DUPLICATO - TROVATO USAGE: '||  V_ID_USAGE || ' (elapsed:'|| (L_END - L_START)/100 ||' s)', ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
      ELSE
        V_ID_USAGE :=  NULL;
        L_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CERCA_USAGE_DUPLICATO - NESSUN USAGE TROVATO: (elapsed:'|| (l_end - l_start)/100 ||' s)', ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
      END IF;
      DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
  EXCEPTION WHEN NO_DATA_FOUND THEN
    V_ID_USAGE :=  NULL;
    L_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
    DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CERCA_USAGE_DUPLICATO - NESSUN USAGE TROVATO: (elapsed:'|| (l_end - l_start)/100 ||' s)', ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
END;



/*  PROCEDURA PER LA CORRELAZIONE DELLE ANAGRAFICHE.
    OMOLOGA DELLA PKG_USAGE_CORRELAZIONE.ClienteCorrelazioneStart CON L'AGGIUNTA DEI CONTATORI
    SPOSTARE NEL PKG_CORRELAZIONE?


    - WARNING GLI UPDATE IN CONCORRENZA PROVOCANO DEADLOCK !!!!!!!!!!!!!!!!!!!!!!!!!!!!!

*/
PROCEDURE CORRELAZIONEANAGRAFICHE(IS_DEBUG_ENABLED  BOOLEAN,IDANAGRAFICA NUMBER, rigaAnagrafica ADC_USAGE_ANAGRAFICA%ROWTYPE, TID VARCHAR2) IS

  UPDATEDROW NUMBER;

  l_start       NUMBER;
  l_end         NUMBER;
  l_diff        NUMBER;
  LOGRESULT     NUMBER;

  ID_BASE               NUMBER;
  ID_BUSINESS           NUMBER;
  ID_VARIAZIONI_SISTEMA    NUMBER;
  ID_VARIAZIONI_FISCALI    NUMBER;

  BEGIN
    l_start := dbms_utility.get_time ;  -- Start Time

    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CORRELAZIONEANAGRAFICHE - IDUsage (' ||  rigaAnagrafica.ID_USAGE || ') BEGIN'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);
    UPDATEDROW := 0;

    BEGIN
        SELECT /* ADC_PKG_LOAD_USAGE_S03 */ R.ID INTO ID_BASE FROM ADC_ANAGRAFICA_BASE R
            WHERE ( R.CF_CORRENTE=rigaAnagrafica.CODICE_FISCALE OR R.CF_VARIATO=rigaAnagrafica.CODICE_FISCALE ) AND ROWNUM = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN
        ID_BASE := NULL;
    END;

    /* ID_ANAGRAFICA BY ANAGRAFICA_BASE */
    IF(ID_BASE IS NOT NULL) THEN

          UPDATE /* ADC_PKG_LOAD_USAGE_U29 */ ADC_USAGE_ANAGRAFICA U SET
          U.ID_ANAGRAFICA_BASE = ID_BASE
           WHERE
             --U.CODICE_FISCALE IS NOT NULL AND U.ID_ANAGRAFICA_BASE IS NULL AND
             U.ID = IDANAGRAFICA;

          UPDATEDROW:= UPDATEDROW + SQL%ROWCOUNT;
          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'PRIMA UPDATE: UPDATEDROW :' || UPDATEDROW || ')'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);

    ELSE

        BEGIN
            SELECT /* ADC_PKG_LOAD_USAGE_S04 */ R.ID_ANAGRAFICA_BASE INTO ID_BUSINESS  FROM ADC_CLIENTE_BUSINESS R
            WHERE ( R.PIVA_CORRENTE=rigaAnagrafica.PIVA OR R.PIVA_VARIATA=rigaAnagrafica.PIVA ) AND ROWNUM = 1;

        EXCEPTION WHEN NO_DATA_FOUND THEN
            ID_BUSINESS := NULL;
        END;
         /* ID_ANAGRAFICA BY ADC_CLIENTE_BUSINESS */
        IF(ID_BUSINESS IS NOT NULL) THEN

              UPDATE /* ADC_PKG_LOAD_USAGE_U30 */ ADC_USAGE_ANAGRAFICA U SET
                  U.ID_ANAGRAFICA_BASE = ID_BUSINESS
              WHERE
                 U.PIVA IS NOT NULL AND U.ID_ANAGRAFICA_BASE IS NULL AND
                 U.ID_USAGE = rigaAnagrafica.ID_USAGE;

              UPDATEDROW:= UPDATEDROW + SQL%ROWCOUNT;
              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'SECONDA UPDATE: UPDATEDROW -' || UPDATEDROW || ')'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);
          ELSE
              BEGIN
                  SELECT /* ADC_PKG_LOAD_USAGE_S05 */ R.ID_ANAGRAFICA_BASE INTO ID_VARIAZIONI_SISTEMA
                  FROM ADC_VARIAZIONI_SISTEMA R
                  WHERE R.CODICE_CLIENTE_SORGENTE=rigaAnagrafica.CODICE_CLIENTE_NON_FISCALE
                      AND R.ID_SISTEMA_SORGENTE = RIGAANAGRAFICA.SISTEMA_CODICE_NON_FISCALE
                      AND ROWNUM = 1;

              EXCEPTION WHEN NO_DATA_FOUND THEN
                  ID_VARIAZIONI_SISTEMA := NULL;
              END;

              /* ID_ANAGRAFICA BY ADC_VARIAZIONI_SISTEMA */
              IF(ID_VARIAZIONI_SISTEMA IS NOT NULL) THEN

                  UPDATE /* ADC_PKG_LOAD_USAGE_U31 */ ADC_USAGE_ANAGRAFICA U SET
                      U.ID_ANAGRAFICA_BASE= ID_VARIAZIONI_SISTEMA
                  WHERE
                      U.CODICE_CLIENTE_NON_FISCALE IS NOT NULL AND U.SISTEMA_CODICE_NON_FISCALE IS NOT NULL AND U.ID_ANAGRAFICA_BASE IS NULL AND
                      U.ID_USAGE = rigaAnagrafica.ID_USAGE;

                  UPDATEDROW:= UPDATEDROW + SQL%ROWCOUNT;
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'TERZA UPDATE: UPDATEDROW -' || UPDATEDROW || ')'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);

               ELSE
                    BEGIN
                        SELECT /* ADC_PKG_LOAD_USAGE_S06 */  R.ID_ANAGRAFICA_BASE INTO ID_VARIAZIONI_FISCALI FROM ADC_VARIAZIONI_FISCALI R
                        WHERE (R.CF_CORRENTE=rigaAnagrafica.CODICE_FISCALE OR R.PIVA_CORRENTE=rigaAnagrafica.PIVA) AND ROWNUM = 1;
                    EXCEPTION WHEN NO_DATA_FOUND THEN
                         ID_VARIAZIONI_FISCALI := NULL;
                    END;

                    /* ID_ANAGRAFICA BY ADC_VARIAZIONI_FISCALI */
                    IF(ID_VARIAZIONI_FISCALI IS NOT NULL) THEN

                        UPDATE /* ADC_PKG_LOAD_USAGE_U32 */ ADC_USAGE_ANAGRAFICA U SET
                            U.ID_ANAGRAFICA_BASE=ID_VARIAZIONI_FISCALI
                        WHERE
                          (U.PIVA IS NOT NULL OR U.CODICE_FISCALE IS NOT NULL) AND U.ID_ANAGRAFICA_BASE IS NULL AND
                          U.ID_USAGE = rigaAnagrafica.ID_USAGE;

                        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'QUARTA UPDATE'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);
                    END IF;
             END IF;
         END IF;
     END IF;

    l_end := dbms_utility.get_time ;  -- Start Time
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CORRELAZIONEANAGRAFICHE - IDUsage (' ||  rigaAnagrafica.ID_USAGE || ') END (elapsed:'|| (l_end - l_start)/100 ||' s)'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);
END;



PROCEDURE GETIDAGRAFICABASE(IS_DEBUG_ENABLED  BOOLEAN,RIGAANAGRAFICA  ADC_USAGE_ANAGRAFICA%ROWTYPE, TID VARCHAR2, ID_ANAGRAFICA_BASE OUT NUMBER, V_cf_corrente OUT VARCHAR2, NOME_CLI OUT VARCHAR2, COGNOME_CLI OUT VARCHAR2) IS

  l_start       NUMBER;
  l_end         NUMBER;
  l_diff        NUMBER;
  LOGRESULT     NUMBER;

  V_TIPO_CLIENTE_FONTE VARCHAR2(255) := NULL;
  V_ID_ANAGRAFICA_BASE NUMBER;

  /*ID_ANAGRAFICA_BASE        NUMBER;
  ID_BUSINESS               NUMBER;
  ID_VARIAZIONI_SISTEMA     NUMBER;
  ID_VARIAZIONI_FISCALI     NUMBER;*/

  --diagnostic variables
  DIAGNOSTIC_CODE VARCHAR2(512):='GIAB4004';
  DIAGNOSTIC_LN VARCHAR2(512):=ADC_PKG_LOAD_USAGE.DIAGNOSTIC_LOGGER_NAME;
  DIAGNOSTIC_INFO_LEVEL VARCHAR2(512):=ADC_PKG_COMMON.INFO_LEVEL;
  DIAGNOSTIC_RESULT NUMBER;

  BEGIN

    l_start := dbms_utility.get_time ;  -- Start Time

    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'GETIDAGRAFICABASE - IDUsage (' ||  rigaAnagrafica.ID_USAGE || ') BEGIN'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);

    ID_ANAGRAFICA_BASE := NULL;
    NOME_CLI := rigaAnagrafica.nome;
    COGNOME_CLI := rigaAnagrafica.cognome;

    DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

    BEGIN
      SELECT /* ADC_PKG_LOAD_USAGE_S06 */  R.ID, R.TIPO_CLIENTE_FONTE, cf_corrente INTO ID_ANAGRAFICA_BASE, V_TIPO_CLIENTE_FONTE, V_cf_corrente FROM ADC_ANAGRAFICA_BASE R
            WHERE ( R.CF_CORRENTE=rigaAnagrafica.CODICE_FISCALE OR R.CF_CORRENTE = rigaAnagrafica.PIVA ) AND ROWNUM = 1;

    EXCEPTION WHEN NO_DATA_FOUND THEN
        ID_ANAGRAFICA_BASE := NULL;
    END;

    DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
    /* ID_ANAGRAFICA BY ANAGRAFICA_BASE */

    IF(ID_ANAGRAFICA_BASE IS NULL) THEN
        DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00020' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
        BEGIN
            SELECT /* ADC_PKG_LOAD_USAGE_S07 */  R.ID_ANAGRAFICA_BASE, 'B' INTO ID_ANAGRAFICA_BASE, V_TIPO_CLIENTE_FONTE  FROM ADC_CLIENTE_BUSINESS R
            WHERE ( R.PIVA_CORRENTE=rigaAnagrafica.PIVA OR R.PIVA_VARIATA=rigaAnagrafica.PIVA ) AND ROWNUM = 1;

        EXCEPTION WHEN NO_DATA_FOUND THEN
            ID_ANAGRAFICA_BASE := NULL;
        END;

        DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00020' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
         /* ID_ANAGRAFICA BY ADC_CLIENTE_BUSINESS */
        IF(ID_ANAGRAFICA_BASE IS  NULL) THEN
             DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00030' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
             BEGIN

                  SELECT /* ADC_PKG_LOAD_USAGE_S08 */ R.ID_ANAGRAFICA_BASE INTO ID_ANAGRAFICA_BASE
                  FROM ADC_VARIAZIONI_SISTEMA R
                  WHERE R.CODICE_CLIENTE_SORGENTE=rigaAnagrafica.CODICE_CLIENTE_NON_FISCALE
                      AND R.ID_SISTEMA_SORGENTE = RIGAANAGRAFICA.SISTEMA_CODICE_NON_FISCALE
                      AND ROWNUM = 1;

              EXCEPTION WHEN NO_DATA_FOUND THEN
                  ID_ANAGRAFICA_BASE := NULL;
              END;
              DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00030' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

              /* ID_ANAGRAFICA BY ADC_VARIAZIONI_SISTEMA */
              IF(ID_ANAGRAFICA_BASE IS NULL) THEN
                    DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00040' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
                    BEGIN
                        SELECT /* ADC_PKG_LOAD_USAGE_S09 */ R.ID_ANAGRAFICA_BASE, AB.TIPO_CLIENTE_FONTE INTO ID_ANAGRAFICA_BASE, V_TIPO_CLIENTE_FONTE FROM ADC_VARIAZIONI_FISCALI R, ADC_ANAGRAFICA_BASE AB
                        WHERE R.ID_ANAGRAFICA_BASE = AB.ID AND (R.CF_CORRENTE=rigaAnagrafica.CODICE_FISCALE OR R.PIVA_CORRENTE=rigaAnagrafica.PIVA) AND ROWNUM = 1;
                    EXCEPTION WHEN NO_DATA_FOUND THEN
                         ID_ANAGRAFICA_BASE := NULL;
                    END;
                    DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00040' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
                END IF;
             END IF;
         END IF;
         DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00050' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
         IF(V_TIPO_CLIENTE_FONTE is NOT NULL) THEN

            V_ID_ANAGRAFICA_BASE := ID_ANAGRAFICA_BASE;

            IF(V_TIPO_CLIENTE_FONTE='R') THEN
              select /* ADC_PKG_LOAD_USAGE_S10 */ CR.NOME, CR.COGNOME INTO NOME_CLI, COGNOME_CLI from ADC_CLIENTE_RETAIL CR where CR.ID_ANAGRAFICA_BASE=V_ID_ANAGRAFICA_BASE AND ROWNUM = 1;

            END IF;

            IF(V_TIPO_CLIENTE_FONTE='B') THEN
              select /* ADC_PKG_LOAD_USAGE_S11 */ CB.RAGIONE_SOCIALE INTO NOME_CLI from ADC_CLIENTE_BUSINESS CB where CB.ID_ANAGRAFICA_BASE=V_ID_ANAGRAFICA_BASE AND ROWNUM = 1;

            END IF;

          END IF;
          DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00050' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
    l_end := dbms_utility.get_time ;  -- Start Time
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'GETIDAGRAFICABASE - IDUsage (' ||  RIGAANAGRAFICA.ID_USAGE || ') END (elapsed:'|| (L_END - L_START)/100 ||' s)'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);

END;


PROCEDURE VIRTUAL_QUEUE_INFO(V_VIRTUAL_QUEUE VARCHAR2, INFO_STRING OUT VARCHAR2) IS

  OBJECT_NAME         VARCHAR2(255);
  JOB_ROW             USER_SCHEDULER_JOBS%ROWTYPE;
  QUEUE_SEPARATOR     VARCHAR2(255);
  JOB_SEPARATOR       VARCHAR2(255);
BEGIN
    BEGIN
        INFO_STRING := INFO_STRING || CHR(10) || 'CODA VIRTUALE: ' || V_VIRTUAL_QUEUE ||  CHR(10) || CHR(10) ;
        INFO_STRING := INFO_STRING || 'CODE AQ ';

        FOR I IN 1..LENGTH('%Q_'|| V_VIRTUAL_QUEUE ||'_00') LOOP
            QUEUE_SEPARATOR := QUEUE_SEPARATOR  ||'-';
        END LOOP;


        INFO_STRING := INFO_STRING  ||  CHR(10) ||  QUEUE_SEPARATOR || CHR(10);

        FOR ITEM IN (
              SELECT OBJECT_NAME FROM USER_OBJECTS WHERE OBJECT_NAME LIKE 'Q_'|| V_VIRTUAL_QUEUE ||'_%' AND OBJECT_TYPE='QUEUE'
        ) LOOP
              INFO_STRING := INFO_STRING || ITEM.OBJECT_NAME ||  CHR(10);
        END LOOP;

        FOR ITEM IN (
              SELECT OBJECT_NAME FROM USER_OBJECTS WHERE OBJECT_NAME LIKE 'Q_ERROR_'|| V_VIRTUAL_QUEUE  AND OBJECT_TYPE='QUEUE'
        ) LOOP
              INFO_STRING := INFO_STRING || ITEM.OBJECT_NAME ||  CHR(10);
        END LOOP;

        INFO_STRING := INFO_STRING  || QUEUE_SEPARATOR || CHR(10);
        INFO_STRING := INFO_STRING || CHR(10) || 'JOB DI SCODAMENTO '||  CHR(10);

         FOR I IN 1..LENGTH('%DEQ_Q_'|| V_VIRTUAL_QUEUE ||'_00 | DISABLED') LOOP
            JOB_SEPARATOR := JOB_SEPARATOR  ||'-';
        END LOOP;
        INFO_STRING := INFO_STRING || JOB_SEPARATOR || CHR(10);

        FOR ITEM IN (
            SELECT * FROM USER_SCHEDULER_JOBS WHERE JOB_NAME LIKE '%DEQ_Q_'|| V_VIRTUAL_QUEUE ||'_%'
        ) LOOP
            INFO_STRING := INFO_STRING || ITEM.JOB_NAME || ' | ' || ITEM.STATE ||  CHR(10);
        END LOOP;
        INFO_STRING := INFO_STRING || JOB_SEPARATOR;

    EXCEPTION WHEN OTHERS THEN
      INFO_STRING:= 'VERIFICARE LA CORRETTA CONGIGURAZIONE DEGLI OGGETTI ASSOCIATI ALLA CODA VIRTUALE ' || V_VIRTUAL_QUEUE ;
    END;
END;


/*  INSERIMENTO USAGE MODIFICATO PER GESTIRE ID_USAGE IN INPUT: ALLINEARE CON QUELLA IN UTILITY?   */
FUNCTION INSERTUSAGE(IS_DEBUG_ENABLED  BOOLEAN,rigaUsage ADC_WRK_USAGE%ROWTYPE, TID VARCHAR2 ) RETURN NUMBER IS
    returnValue NUMBER;
    copia ADC_WRK_USAGE%ROWTYPE;

    l_start       NUMBER;
    l_end         NUMBER;
    l_diff        NUMBER;
    LOGRESULT     NUMBER;

    --diagnostic variables
    DIAGNOSTIC_CODE VARCHAR2(512):='INUS4003';
    DIAGNOSTIC_LN VARCHAR2(512):=ADC_PKG_LOAD_USAGE.DIAGNOSTIC_LOGGER_NAME;
    DIAGNOSTIC_INFO_LEVEL VARCHAR2(512):=ADC_PKG_COMMON.INFO_LEVEL;
    DIAGNOSTIC_RESULT NUMBER;

    BEGIN

      L_START := DBMS_UTILITY.GET_TIME ;  -- Start Time

      --LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME,  RIGAUSAGE.ID  , ADC_PKG_COMMON.INFO_LEVEL,TID);
      DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

      returnValue := RIGAUSAGE.ID;
      COPIA := RIGAUSAGE;

      IF(returnValue IS NULL) THEN
        SELECT SEQ_ADC_WRK_USAGE.NEXTVAL INTO RETURNVALUE FROM DUAL;
        COPIA.ID := returnValue;
      END IF;

      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INSERTUSAGE - IDUsage (' ||   COPIA.ID || ') BEGIN'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);

      INSERT /* ADC_PKG_LOAD_USAGE_I20 */ INTO ADC_WRK_USAGE VALUES copia;

      l_end := dbms_utility.get_time ;  -- Start Time

      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INSERTUSAGE - IDUsage (' ||  COPIA.ID  || ') END (elapsed:'|| (l_end - l_start)/100 ||' s)'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);

      DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
      RETURN returnValue;
END;


PROCEDURE GETSERVIZIACCESSORI(IS_DEBUG_ENABLED  BOOLEAN,SA VARCHAR2, SISTEMA_SORGENTE VARCHAR2, TID VARCHAR2, SERVIZI_ACCESSORI OUT SERVIZIACCESSORI_TABLE) IS

    SERVIZIACCESSORI_ROW SERVIZIACCESSORI_TYPE;
    SA_COUNT      NUMBER;
    l_start       NUMBER;
    l_end         NUMBER;
    l_diff        NUMBER;
    LOGRESULT     NUMBER;


    STRING_TO_CONSUME VARCHAR2(2000) := 'R:LUCA-R';
    FOUND_SEPARATORE NUMBER := 0;
    FOUND_ASSEGNATORE NUMBER := 0;
    END_SEARCH BOOLEAN  := FALSE;
    V_KEY VARCHAR2(100);
    V_VALUE VARCHAR2(100);
    WORK_STRING VARCHAR2(2000);
    ASSEGNATORE VARCHAR2(2):='';

  BEGIN
      l_start := dbms_utility.get_time ;  -- Start Time
      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'GETSERVIZIACCESSORI - BEGIN'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);

      IF SA IS NOT NULL THEN
          SA_COUNT := 1;
          STRING_TO_CONSUME := SA;
          LOOP
            IF(STRING_TO_CONSUME IS NULL) THEN
               END_SEARCH := TRUE;
            ELSE
                  --DBMS_OUTPUT.PUT_LINE('STRINGA IN INPUT : ' || STRING_TO_CONSUME);
                  FOUND_SEPARATORE:= INSTR(STRING_TO_CONSUME, '-');

                  /* #117 START: AGGIUNTA PER GESTIRE IL CARATTERE - NEL NOME O NEL VALORE DELLA STRINGA DEI SERVIZI ACCESSORI */
                  LOOP
                    IF(FOUND_SEPARATORE > 0) THEN
                      ASSEGNATORE := SUBSTR(STRING_TO_CONSUME, FOUND_SEPARATORE+1, 1);
                      IF(ASSEGNATORE = ':') THEN
                        --DBMS_OUTPUT.PUT_LINE('FALSO SEPARATORE : RICERCA NUOVO');
                        FOUND_SEPARATORE := INSTR(STRING_TO_CONSUME, '-', FOUND_SEPARATORE + 2  );
                      ELSE
                        EXIT;
                      END IF;
                     ELSE
                      EXIT;
                    END IF;
                  END LOOP;
                  /* #117 END ------------------------------------------------------------------------------------------------ */

                  IF(FOUND_SEPARATORE = 0) THEN
                    END_SEARCH := TRUE;
                    WORK_STRING := STRING_TO_CONSUME;
                  ELSE
                    WORK_STRING := SUBSTR(STRING_TO_CONSUME, 0, FOUND_SEPARATORE -1);
                    STRING_TO_CONSUME := SUBSTR(STRING_TO_CONSUME, FOUND_SEPARATORE + 1);
                  END IF;

                  FOUND_ASSEGNATORE := INSTR(WORK_STRING, ':');
                  IF(FOUND_ASSEGNATORE > 0) THEN
                    V_KEY:= SUBSTR(WORK_STRING, 0, FOUND_ASSEGNATORE -1);
                    V_VALUE:= SUBSTR(WORK_STRING,  FOUND_ASSEGNATORE + 1);
                  ELSE
                    V_KEY:= WORK_STRING;
                    V_VALUE:=NULL;
                  END IF;

                 /* DBMS_OUTPUT.PUT_LINE('STRINGA DA SPLITTARE : ' || WORK_STRING);
                  DBMS_OUTPUT.PUT_LINE('CHIAVE : ' || V_KEY);
                  DBMS_OUTPUT.PUT_LINE('VALORE : ' || V_VALUE);*/


                  SERVIZIACCESSORI_ROW.NOME := V_KEY;
                  SERVIZIACCESSORI_ROW.VALORE := V_VALUE;

                  SERVIZI_ACCESSORI(SA_COUNT):= SERVIZIACCESSORI_ROW;
                  SA_COUNT := SA_COUNT + 1;
              END IF;

              EXIT WHEN END_SEARCH;
          END LOOP;
         /* FOR I IN 1..SERVIZI_ACCESSORI.LAST LOOP
             DBMS_OUTPUT.PUT_LINE(SERVIZI_ACCESSORI(i).VALORE);
          END LOOP;*/
        END IF;
    L_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
    --DBMS_OUTPUT.PUT_LINE('PROCEDURE: GETSERVIZIACCESSORI - END (elapsed:'|| (l_end - l_start)/100 ||' s)');
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'GETSERVIZIACCESSORI - END (elapsed:'|| (l_end - l_start)/100 ||' s)'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID);

    END;

