  PROCEDURE FINALIZE_TT_USAGE (V_SESSION_ID NUMBER, JOB_ID NUMBER, TID VARCHAR2, FINALIZE_ERROR OUT BOOLEAN) IS

      V_FILE                      UTL_FILE.FILE_TYPE;
      NOME_FILE                   VARCHAR(255);
      LOGRESULT                   NUMBER;

      CURSOR ADC_TX_USAGE_CUR IS
        SELECT /* ADC_PKG_LOAD_USAGE_S43 */ U.*, T.NOME_FILE FROM ADC_BAD_TX_USAGE_NEW U, ADC_TX_JOBID_SESSION S, ADC_TX_JOBID T
        WHERE S.SESSION_ID = V_SESSION_ID AND S.FLUSSO_ID = U.ID_FLUSSO AND T.ID_FLUSSO = U.PRG_FLUSSO;

      BEGIN
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZE_TT_USAGE (JOB ID: ' || JOB_ID || ') - BEGIN ', ADC_PKG_COMMON.INFO_LEVEL,TID);

        FINALIZE_ERROR := FALSE;
        NOME_FILE :='ADC_USAGESCARTI_' || TO_CHAR (SYSDATE,'YYYYMMDDHHmmSS') || '.CSV';
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZE_TT_USAGE (' || JOB_ID || ')('|| V_SESSION_ID ||') - CREAZIONE FILE: ' || NOME_FILE , ADC_PKG_COMMON.INFO_LEVEL,TID);
        DBMS_OUTPUT.PUT_LINE('PROCEDURE: FINALIZE_TT_USAGE (' || JOB_ID || ')('|| V_SESSION_ID ||') - CREAZIONE FILE: ' || NOME_FILE);

        v_file := UTL_FILE.FOPEN(location => 'WORK_DIR_PATH_FILE_BAD',
                                    filename     => nome_file,
                                    open_mode    => 'w',
                                    max_linesize => 32767);

        UTL_FILE.PUT_LINE(v_file, 'DATA_ORA_EVENTO|FASE_CICLO_DI_VITA|SOTTO_FASE_CICLO_DI_VITA|SISTEMA_SORGENTE|CODICE_PRODOTTO_SERVIZIO|ESITO|ID_PROCESSO_INTERNO|ID_TIPO_PROCESSO_INTERNO|SISTEMA_PROCESSO_INTERNO|ID_TRACCIATURA|TIPO_PRODOTTO_TRACCIATURA|SISTEMA_TRACCIATURA|ID_ALTRO_PROCESSO|ALTRO_PROCESSO_PRECEDENTE|ID_TIPO_ALTRO_PROCESSO|SISTEMA_ALTRO_PROCESSO|MOTIVO_CONTATTO|KEY_FRAZ_ACC|KEY_FRAZ_DST|KEY_ZONA_PTL|CODICE_FISCALE_RIC|CODICE_NAZIONE_FISCALE_RIC|PIVA_RIC|CODICE_NAZIONE_PIVA_RIC|SISTEMA_CODICE_NON_FISCALE_RIC|CODICE_CLIENTE_NON_FISCALE_RIC|NOME_RIC|COGNOME_RIC|INDIRIZZO_PARTICELLA_TOP_RIC|INDIRIZZO_RIC|NUMERO_CIVICO_RIC|CAP_RIC|COMUNE_RIC|PROVINCIA_RIC|STATO_RIC|CODICE_FISCALE_CLI|CODICE_NAZIONE_FISCALE_CLI|PIVA_CLI|CODICE_NAZIONE_PIVA_CLI|SISTEMA_CODICE_NON_FISCALE_CLI|CODICE_CLIENTE_NON_FISCALE_CLI|NOME_CLI|COGNOME_CLI|INDIRIZZO_PARTICELLA_TOP_CLI|INDIRIZZO_CLI|NUMERO_CIVICO_CLI|CAP_CLI|COMUNE_CLI|PROVINCIA_CLI|STATO_CLI|CODICE_FISCALE_MIT|CODICE_NAZIONE_FISCALE_MIT|PIVA_MIT|CODICE_NAZIONE_PIVA_MIT|SISTEMA_CODICE_NON_FISCALE_MIT|CODICE_CLIENTE_NON_FISCALE_MIT|NOME_MIT|COGNOME_MIT|INDIRIZZO_PARTICELLA_TOP_MIT|INDIRIZZO_MIT|NUMERO_CIVICO_MIT|CAP_MIT|COMUNE_MIT|PROVINCIA_MIT|STATO_MIT|CODICE_FISCALE_DEST|CODICE_NAZIONE_FISCALE_DEST|PIVA_DEST|CODICE_NAZIONE_PIVA_DEST|SISTEMA_CODICE_NON_FISC_DEST|CODICE_CLIENTE_NON_FISC_DEST|NOME_DEST|COGNOME_DEST|INDIRIZZO_PARTICELLA_TOP_DEST|INDIRIZZO_DEST|NUMERO_CIVICO_DEST|CAP_DEST|COMUNE_DEST|PROVINCIA_DEST|STATO_DEST|CODICE_FISCALE_INT|CODICE_NAZIONE_FISCALE_INT|PIVA_INT|CODICE_NAZIONE_PIVA_INT|SISTEMA_CODICE_NON_FISC_INT|CODICE_CLIENTE_NON_FISC_INT|NOME_INT|COGNOME_INT|INDIRIZZO_PARTICELLA_TOP_INT|INDIRIZZO_INT|NUMERO_CIVICO_INT|CAP_INT|COMUNE_INT|PROVINCIA_INT|STATO_INT|NOMEFILE|MOTIVOSCARTO');

        FOR I IN ADC_TX_USAGE_CUR
          LOOP
            UTL_FILE.PUT_LINE(V_FILE,
