              I.MAIL_DEST || '|' ||
              I.CODICE_FISCALE_INT || '|' ||
              I.CODICE_NAZIONE_FISCALE_INT || '|' ||
              I.PIVA_INT || '|' ||
              I.CODICE_NAZIONE_PIVA_INT || '|' ||
              I.SISTEMA_CODICE_NON_FISC_INT || '|' ||
              I.CODICE_CLIENTE_NON_FISC_INT || '|' ||
              I.NOME_INT || '|' ||
              I.COGNOME_INT || '|' ||
              I.INDIRIZZO_PARTICELLA_TOP_INT || '|' ||
              I.INDIRIZZO_INT || '|' ||
              I.NUMERO_CIVICO_INT || '|' ||
              I.CAP_INT || '|' ||
              I.COMUNE_INT || '|' ||
              I.PROVINCIA_INT || '|' ||
              I.STATO_INT || '|' ||
              I.TELEFONO_INT || '|' ||
              I.MAIL_INT || '|' ||
              I.NOME_FILE || '|' ||
              I.MOTIVO_SCARTO);
      END LOOP;
      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZE_SAP_EM_USAGE (JOB ID: ' || JOB_ID || ')('|| V_SESSION_ID ||') - CHIUSURA FILE: ' || NOME_FILE , ADC_PKG_COMMON.INFO_LEVEL,TID);
      DBMS_OUTPUT.PUT_LINE('PROCEDURE: FINALIZE_SAP_EM_USAGE (JOB ID: ' || JOB_ID || ')('|| V_SESSION_ID ||') - CHIUSURA FILE: ' || NOME_FILE);
      UTL_FILE.FCLOSE(V_FILE);
      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZE_SAP_EM_USAGE (JOB ID: ' || JOB_ID || ') - END ', ADC_PKG_COMMON.INFO_LEVEL,TID);
   EXCEPTION WHEN OTHERS THEN
     FINALIZE_ERROR := TRUE;
     LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZE_SAP_EM_USAGE (JOB ID: ' || JOB_ID || ')('|| V_SESSION_ID ||') - ERRORE NELLA CREAZIONE DEL FILE: ' || NOME_FILE  || ': ' || SQLERRM, ADC_PKG_COMMON.ERROR_LEVEL,TID);
     DBMS_OUTPUT.PUT_LINE('PROCEDURE: FINALIZE_SAP_EM_USAGE (JOB ID: ' || JOB_ID || ') - ERRORE NELLA CREAZIONE DEL FILE: ' || NOME_FILE  || ': ' || SQLERRM);
     UTL_FILE.FCLOSE(V_FILE);
  END;


/* --------------------------------------------------------------------------- */

PROCEDURE FINALIZZA_SESSIONI(JOB_ID NUMBER) IS

    V_FILE                      UTL_FILE.FILE_TYPE;
    NOME_FILE                   VARCHAR(255);
    LOGRESULT                   NUMBER;
    JOB_ENQUEUER_NUMBER         NUMBER;
    FINALIZE_ERROR              BOOLEAN;
    DROP_ERROR                  BOOLEAN;
    PARTITION_NOT_EXIST         EXCEPTION;

    TX_USAGE_NUMBER             NUMBER;

    MESSAGE                     VARCHAR2(200);
    ESITO                       VARCHAR2(200);
    TID                         VARCHAR2(200);
    TABLE_NAME                  VARCHAR2(100);
    FINALIZE_PROCEDURE          VARCHAR2(100);
    PROCEDURE_CALL              VARCHAR2(1000);

    PRAGMA EXCEPTION_INIT(PARTITION_NOT_EXIST, -2149);

  BEGIN
    TID:='FIN_'||TO_CHAR(SYSTIMESTAMP,'YYYYMMDDHH24missFF3');
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ') - BEGIN ', ADC_PKG_COMMON.INFO_LEVEL,TID);

    FINALIZE_ERROR              :=  FALSE;
    DROP_ERROR                  :=  FALSE;

    FOR SESSIONITEM IN (
                       /* SELECT DISTINCT SESSION_ID, VIRTUAL_QUEUE FROM (SELECT SESSION_ID, VIRTUAL_QUEUE, MAX(ACTIVE_ENQUEUER) AS MAX_ENQUEUER, MIN(ACTIVE_ENQUEUER) AS MIN_ENQUEUER
                        FROM ADC_TX_JOBID_SESSION WHERE STATO_ELAB=1 AND FINALIZZATO = 0 AND ACTIVE_ENQUEUER IS NOT NULL GROUP BY SESSION_ID)
                        WHERE MAX_ENQUEUER = MIN_ENQUEUER AND MIN_ENQUEUER = 0) */

                        SELECT /* ADC_PKG_LOAD_USAGE_S45 */ DISTINCT SESSION_ID, VIRTUAL_QUEUE FROM (SELECT SESSION_ID,VIRTUAL_QUEUE, MAX( ACTIVE_ENQUEUER) OVER (PARTITION BY SESSION_ID) AS MAX_ENQUEUER, MIN( ACTIVE_ENQUEUER) OVER (PARTITION BY SESSION_ID) AS MIN_ENQUEUER
                        FROM ADC_TX_JOBID_SESSION WHERE STATO_ELAB=1 AND FINALIZZATO = 0 AND ACTIVE_ENQUEUER IS NOT NULL)
                        WHERE MAX_ENQUEUER = MIN_ENQUEUER AND MIN_ENQUEUER = 0
                        AND SESSION_ID NOT IN (SELECT SESSION_ID FROM ADC_TX_JOBID_SESSION WHERE STATO_ELAB=0))
    LOOP

        /* TABLE_NAME NAME  - OBBLIGATORIO */
        SELECT PARAMETER_VALUE INTO TABLE_NAME FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = SESSIONITEM.VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='SOURCE_TABLE' AND ROWNUM = 1;

        /* PROCEDURA DI FINALIZZAZIONE */
        SELECT PARAMETER_VALUE INTO FINALIZE_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = SESSIONITEM.VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='FINALIZE_PROCEDURE' AND ROWNUM = 1;


        EXECUTE IMMEDIATE 'SELECT /* ADC_PKG_LOAD_USAGE_S12 */ COUNT(ID) FROM ' || TABLE_NAME || ' TX , ADC_TX_JOBID_SESSION S WHERE S.FLUSSO_ID = TX.ID_FLUSSO AND S.SESSION_ID=' || SESSIONITEM.SESSION_ID INTO TX_USAGE_NUMBER;

        IF(TX_USAGE_NUMBER = 0 ) THEN

                PROCEDURE_CALL := 'BEGIN ' ||
                              FINALIZE_PROCEDURE || '(
                              V_SESSION_ID       =>  :SESSIONITEM.SESSION_ID,
                              JOB_ID             =>  :JOB_ID,
                              TID                =>  :TID,
                              FINALIZE_ERROR     =>  :FINALIZE_ERROR
                              );
                          END;
                          ';
            BEGIN
              EXECUTE IMMEDIATE PROCEDURE_CALL USING IN SESSIONITEM.SESSION_ID,JOB_ID, TID, OUT FINALIZE_ERROR;
            EXCEPTION WHEN OTHERS THEN
              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI -  ERRORE NELLA FINALIZZAZIONE DELLA SESSION ' || SESSIONITEM.SESSION_ID || ': ' || SQLERRM || ' - ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE  , ADC_PKG_COMMON.ERROR_LEVEL,'');
            END;

            BEGIN
            /* DROP PARTIZIONI TABELLA RICAVATA */
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - DROP PARTIZIONI ADC_TX_USAGE_NEW', ADC_PKG_COMMON.INFO_LEVEL,TID);
                DBMS_OUTPUT.PUT_LINE('PROCEDURE: FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ') - DROP PARTIZIONI ADC_TX_USAGE_NEW');

                FOR ID_FLUSSO_ITEM IN ( SELECT /* ADC_PKG_LOAD_USAGE_S46 */ FLUSSO_ID FROM ADC_TX_JOBID_SESSION WHERE STATO_ELAB=1 AND ACTIVE_ENQUEUER = 0 AND SESSION_ID = SESSIONITEM.SESSION_ID)  LOOP
                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - DROP PARTIZIONE '||ID_FLUSSO_ITEM.FLUSSO_ID, ADC_PKG_COMMON.INFO_LEVEL,TID);
                    DBMS_OUTPUT.PUT_LINE('PROCEDURE: FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - DROP PARTIZIONE '||ID_FLUSSO_ITEM.FLUSSO_ID);
                    EXECUTE IMMEDIATE 'ALTER TABLE ' || TABLE_NAME || ' DROP PARTITION FOR (' || ID_FLUSSO_ITEM.FLUSSO_ID || ') UPDATE GLOBAL INDEXES';
                END LOOP;
                EXCEPTION WHEN PARTITION_NOT_EXIST THEN
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - PARTIZIONE INESISTENTE: NON E'' NECESSARIO PROCEDERE CON IL DROP', ADC_PKG_COMMON.INFO_LEVEL,TID);
                WHEN OTHERS THEN
                  DROP_ERROR := TRUE;
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - ERRORE NEL DROP PARTIZIONI ' || TABLE_NAME  ||  SQLERRM, ADC_PKG_COMMON.ERROR_LEVEL,TID);
                END;

                IF(NOT(FINALIZE_ERROR) AND NOT(DROP_ERROR)) THEN
                   LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - FINALIZZAZIONE SESSIONE ' || SESSIONITEM.SESSION_ID , ADC_PKG_COMMON.INFO_LEVEL,TID);
                   UPDATE /* ADC_PKG_LOAD_USAGE_U33 */ ADC_TX_JOBID_SESSION SET FINALIZZATO = 1 WHERE SESSION_ID = SESSIONITEM.SESSION_ID;
                END IF;
          ELSE
              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - RISCHEDULAZIONE ACCODAMENTI PER LA SESSION :' || SESSIONITEM.SESSION_ID, ADC_PKG_COMMON.INFO_LEVEL,TID);
              /* CHIAMO INIT GENERICA --------------------------------------------------------------*/
              ADC_PKG_LOAD_USAGE.ENQUEUE_USAGE_INIT(
                  INPUT_ID_SESSION => SESSIONITEM.SESSION_ID,
                  V_VIRTUAL_QUEUE => SESSIONITEM.VIRTUAL_QUEUE, -- IN FUTURO PRENDERE DALLA ADC_TX_JOBID_SESSION
                  MESSAGE => MESSAGE,
                  ESITO => ESITO
              );

          END IF;
    END LOOP;
    /* VERIFICA SE ESISTONO JOB DI ACCODAMENTO COMPLETATI IN MODO ANOMALO: ENQUEUE NUMBER > 0 E NESSUN JOB ATTIVO */
    FOR SESSIONITEM IN (
                        SELECT SESSION_ID, VIRTUAL_QUEUE FROM
                          (SELECT SESSION_ID,VIRTUAL_QUEUE, MAX( ACTIVE_ENQUEUER) OVER (PARTITION BY SESSION_ID) AS MAX_ENQUEUER
                        FROM ADC_TX_JOBID_SESSION WHERE STATO_ELAB=1 AND FINALIZZATO = 0 AND ACTIVE_ENQUEUER IS NOT NULL)
                        WHERE MAX_ENQUEUER > 0
    )
    LOOP
      SELECT COUNT(JOB_NAME) INTO JOB_ENQUEUER_NUMBER FROM USER_SCHEDULER_JOBS WHERE JOB_NAME LIKE ('ENQ_' || LPAD(TO_CHAR(SESSIONITEM.SESSION_ID), 4, '0') || '%');
      IF(JOB_ENQUEUER_NUMBER = 0) THEN
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - PER LA SESSION '|| SESSIONITEM.SESSION_ID || ' NON RISULTANO ESSERE ATTIVI JOB DI ACCODAMENTO PER IL COMPLETAMENTO DELLA FASE DI CARICAMENTO', ADC_PKG_COMMON.WARN_LEVEL,TID);
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ')('|| SESSIONITEM.SESSION_ID ||') - RISCHEDULAZIONE ACCODAMENTI PER LA SESSION :' || SESSIONITEM.SESSION_ID, ADC_PKG_COMMON.INFO_LEVEL,TID);

        ADC_PKG_LOAD_USAGE.ENQUEUE_USAGE_INIT(
                  INPUT_ID_SESSION  => SESSIONITEM.SESSION_ID,
                  V_VIRTUAL_QUEUE   => SESSIONITEM.VIRTUAL_QUEUE, -- IN FUTURO PRENDERE DALLA ADC_TX_JOBID_SESSION
                  MESSAGE           => MESSAGE,
                  ESITO             => ESITO
              );
      END IF;
    END LOOP;

    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ') - END ', ADC_PKG_COMMON.INFO_LEVEL,TID);
    DBMS_OUTPUT.PUT_LINE('PROCEDURE: FINALIZZA_SESSIONI (JOB ID: ' || JOB_ID || ') - END ');
END;

PROCEDURE INIT_JOB_TECNICI IS

    LOGRESULT                   NUMBER;
    ENABLED                     VARCHAR(10);
    SCHEDUL_INTERVAL_IN_MIN     NUMBER;
    FINALIZE_PROCEDURE          VARCHAR(255);
    V_VIRTUAL_QUEUE             VARCHAR(255);
    JOB_ROW                     USER_SCHEDULER_JOBS%ROWTYPE;
    V_JOB_NAME                  VARCHAR(255);

BEGIN
      V_VIRTUAL_QUEUE := 'FINALIZE_LOAD_USAGE';
      V_JOB_NAME      := 'FINALIZE_LOAD_USAGE';

      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_JOB_TECNICI - BEGIN ', ADC_PKG_COMMON.INFO_LEVEL,'');

      /*FINALIZE_PROCEDURE*/
      BEGIN
          SELECT PARAMETER_VALUE INTO FINALIZE_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='FINALIZE_PROCEDURE' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO FINALIZE_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='FINALIZE_PROCEDURE' AND ROWNUM = 1;
      END;

      /*SCHEDUL_INTERVAL_IN_MIN*/
      BEGIN
          SELECT PARAMETER_VALUE INTO SCHEDUL_INTERVAL_IN_MIN FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='SCHEDUL_INTERVAL_IN_MIN' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO SCHEDUL_INTERVAL_IN_MIN FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='SCHEDUL_INTERVAL_IN_MIN' AND ROWNUM = 1;
      END;

      /*ENABLED*/
      BEGIN
          SELECT PARAMETER_VALUE INTO ENABLED FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='ENABLED' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO ENABLED FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='ENABLED' AND ROWNUM = 1;
      END;


      BEGIN
          SELECT * INTO JOB_ROW FROM USER_SCHEDULER_JOBS WHERE JOB_NAME = V_JOB_NAME;

          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CANCELLAZIONE JOB DI FINALIZZAZIONE_' || V_JOB_NAME, ADC_PKG_COMMON.INFO_LEVEL,'');
          /* ARRESTO ESECUZIONE JOB */
          IF(JOB_ROW.STATE = 'RUNNING') THEN
            BEGIN
            DBMS_SCHEDULER.STOP_JOB (
              'ADC_OWN.' || V_JOB_NAME,
               FALSE);
             EXCEPTION WHEN OTHERS THEN
               DBMS_SCHEDULER.STOP_JOB (
                 'ADC_OWN.' || V_JOB_NAME,
                 TRUE);
              END;
            END IF;

            /* DISABILITAZIONE JOB */
            DBMS_SCHEDULER.DISABLE('ADC_OWN.' || V_JOB_NAME);

            /* DROP DEL JOB */
            DBMS_SCHEDULER.DROP_JOB (
            JOB_NAME => 'ADC_OWN.' || V_JOB_NAME);
        EXCEPTION  WHEN NO_DATA_FOUND THEN
            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'JOB DI FINALIZZAZIONE_' || V_JOB_NAME || ' NON PRESENTE', ADC_PKG_COMMON.INFO_LEVEL,'');
        END;
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CREAZIONE JOB DI FINALIZZAZIONE_' || V_JOB_NAME, ADC_PKG_COMMON.INFO_LEVEL,'');

         /* JOB DI FINALIZZAZIONE*/
         DBMS_SCHEDULER.CREATE_JOB (
             JOB_NAME            =>  'ADC_OWN.' || V_JOB_NAME,
             JOB_TYPE            =>  'STORED_PROCEDURE',
             JOB_ACTION     	    =>   FINALIZE_PROCEDURE,
             REPEAT_INTERVAL     =>  'FREQ=MINUTELY; INTERVAL='|| SCHEDUL_INTERVAL_IN_MIN ||';',
             COMMENTS            => 	'Finalizzazione delle session Batch');
        DBMS_SCHEDULER.ENABLE('ADC_OWN.' || V_JOB_NAME);
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_JOB_TECNICI - END ', ADC_PKG_COMMON.INFO_LEVEL,'');
END;

PROCEDURE INIT_AQ_FRAMEWORK(V_VIRTUAL_QUEUE VARCHAR2) IS

  USAGE_BLOCK                 NUMBER;
  QUEUE_NUMBER                NUMBER;
  CURRENT_MIN_USAGE           NUMBER;
  CURRENT_MAX_USAGE           NUMBER;

  LOGRESULT                   NUMBER;

  QUEUE_INDEX                 NUMBER;
  QUEUES                      QUEUES_TABLE;

  V_QUEUE                     VARCHAR2(255);
  V_QUEUE_TABLE               VARCHAR2(255);

  BAD_MESSAGE_QUEUE           VARCHAR2(255);
  ERROR_BUSINESS_QUEUE         VARCHAR2(255);
  ENQUEUE_BLOCK_SIZE          NUMBER;
  DEQUEUE_BLOCK_SIZE          NUMBER;
  SCHEDUL_INTERVAL_IN_MIN     NUMBER;
  JOB_TIME_LIMIT_INS_SEC      NUMBER;
  DEQUEUE_PROCEDURE           VARCHAR(255);
  ENABLED                     VARCHAR(10);

  MESSAGE_TYPE                VARCHAR2(255);
  QUEUE_SUFFIX                VARCHAR2(10);

  V_QUEUE_FOUND               VARCHAR2(255);

  ACTUAL_QUEUE_FOUND          VARCHAR2(255);

  QUEUE_COUNT                 VARCHAR2(255);
  QUEUE_TABLE                 VARCHAR2(255);
  GV_ROW                      QUEUE_INFO_TYPE;
  JOB_ROW                     USER_SCHEDULER_JOBS%ROWTYPE;
  JOB_STATE                   VARCHAR2(255);
 -- VR_TABLE                    VARCHAR2(255);
  MESSAGE_NUMBER              VARCHAR2(255);
  REPORT_STRING               VARCHAR2(4000);

BEGIN
      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - CONFIGURAZIONE FRAMEWORK PER LA CODA VIRTUALE ' ||  V_VIRTUAL_QUEUE || ' - BEGIN ', ADC_PKG_COMMON.INFO_LEVEL,'');

      QUEUE_INDEX :=1;

      /*QUEUE_NUMBER*/
      BEGIN
          SELECT PARAMETER_VALUE INTO QUEUE_NUMBER FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='QUEUE_NUMBER'  AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO QUEUE_NUMBER FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='QUEUE_NUMBER' AND ROWNUM = 1;
      END;

      /*ENQUEUE_BLOCK_SIZE*/
      BEGIN
          SELECT PARAMETER_VALUE INTO ENQUEUE_BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='ENQUEUE_BLOCK_SIZE' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO ENQUEUE_BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='ENQUEUE_BLOCK_SIZE'   AND ROWNUM = 1;
      END;

      /*DEQUEUE_BLOCK_SIZE*/
      BEGIN
          SELECT PARAMETER_VALUE INTO DEQUEUE_BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='DEQUEUE_BLOCK_SIZE'  AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO DEQUEUE_BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='DEQUEUE_BLOCK_SIZE' AND ROWNUM = 1;
      END;

      /*SCHEDUL_INTERVAL_IN_MIN*/
      BEGIN
          SELECT PARAMETER_VALUE INTO SCHEDUL_INTERVAL_IN_MIN FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='SCHEDUL_INTERVAL_IN_MIN' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO SCHEDUL_INTERVAL_IN_MIN FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='SCHEDUL_INTERVAL_IN_MIN' AND ROWNUM = 1;
      END;

      /*JOB_TIME_LIMIT_INS_SEC*/
      BEGIN
          SELECT PARAMETER_VALUE INTO JOB_TIME_LIMIT_INS_SEC FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='JOB_TIME_LIMIT_INS_SEC' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO JOB_TIME_LIMIT_INS_SEC FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='JOB_TIME_LIMIT_INS_SEC' AND ROWNUM = 1;
      END;


      /*ENABLED*/
      BEGIN
          SELECT PARAMETER_VALUE INTO ENABLED FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='ENABLED' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO ENABLED FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='ENABLED' AND ROWNUM = 1;
      END;

      /*DEQUEUE_PROCEDURE*/
      BEGIN
          SELECT PARAMETER_VALUE INTO DEQUEUE_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='DEQUEUE_PROCEDURE' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO DEQUEUE_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='DEQUEUE_PROCEDURE' AND ROWNUM = 1;
      END;


      /*MESSAGE_TYPE*/
      BEGIN
          SELECT PARAMETER_VALUE INTO MESSAGE_TYPE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='MESSAGE_TYPE' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO MESSAGE_TYPE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='MESSAGE_TYPE' AND ROWNUM = 1;
      END;


      /* SE LA CODA E' DISABILITATA VENGONO ELIMINATI TUTTI GLI OGGETTI ASSOCIATI */
      IF(UPPER(ENABLED) != 'TRUE') THEN
          QUEUE_NUMBER := 0;
          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - ' || V_VIRTUAL_QUEUE || ' DISABLED: GLI EVENTUALI OGGETTI ASSOCIATI VERRANNO RIMOSSI', ADC_PKG_COMMON.INFO_LEVEL,'');
          DBMS_OUTPUT.PUT_LINE('INIT_AQ_FRAMEWORK ' || V_VIRTUAL_QUEUE || ' DISABLED: GLI EVENTUALI OGGETTI ASSOCIATI VERRANNO RIMOSSI');
      END IF;

      /* ==============================================================================================
        CANCELLAZIONE DELLA CODA DI ERRORE SE VUOTA
        QUESTA FASE E' NECESSARIA NEL CASO SI DIMINUISCA IL PARALLELISMO
      =================================================================================================*/
      IF(QUEUE_NUMBER=0) THEN

        BEGIN

          ERROR_BUSINESS_QUEUE:= 'Q_ERROR_'|| V_VIRTUAL_QUEUE;

          BEGIN
              SELECT QUEUE_TABLE INTO QUEUE_TABLE FROM USER_QUEUES WHERE NAME=ERROR_BUSINESS_QUEUE;
          EXCEPTION WHEN NO_DATA_FOUND THEN
              QUEUE_TABLE:='QT_ERROR_'|| V_VIRTUAL_QUEUE;
          END;


          SELECT OBJECT_NAME INTO ERROR_BUSINESS_QUEUE  FROM USER_OBJECTS WHERE OBJECT_NAME=ERROR_BUSINESS_QUEUE  AND OBJECT_TYPE='QUEUE';

          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - ANALISI CODA: ' || ERROR_BUSINESS_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
          DBMS_OUTPUT.PUT_LINE('ANALISI CODA ' || ERROR_BUSINESS_QUEUE);

          EXECUTE IMMEDIATE 'SELECT COUNT(QUEUE) FROM AQ$'|| QUEUE_TABLE INTO MESSAGE_NUMBER;

          IF(MESSAGE_NUMBER = 0) THEN

              DBMS_AQADM.STOP_QUEUE(QUEUE_NAME =>ERROR_BUSINESS_QUEUE);

              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - CACELLAZIONE CODA ' || ERROR_BUSINESS_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
              DBMS_OUTPUT.PUT_LINE('CACELLAZIONE CODA ' || ERROR_BUSINESS_QUEUE);

              DBMS_AQADM.DROP_QUEUE (
                  QUEUE_NAME         => ERROR_BUSINESS_QUEUE);

              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - CACELLAZIONE TABELLA ' || QUEUE_TABLE, ADC_PKG_COMMON.INFO_LEVEL,'');
              DBMS_OUTPUT.PUT_LINE('CACELLAZIONE TABELLA ' || QUEUE_TABLE);

              DBMS_AQADM.DROP_QUEUE_TABLE (
                      QUEUE_TABLE        => QUEUE_TABLE);

          END IF;

        EXCEPTION WHEN OTHERS THEN
            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - QUEUE ' || ERROR_BUSINESS_QUEUE || ' NON PRESENTE', ADC_PKG_COMMON.WARN_LEVEL,'');
            DBMS_OUTPUT.PUT_LINE('QUEUE ' || ERROR_BUSINESS_QUEUE || ' INESISTENTE');
        END;

      END IF;

      /* ==============================================================================================
        CANCELLAZIONE DELLE CODE VUOTE ASSOCIATE ALLA VIRTUAL QUEUE
        QUESTA FASE E' NECESSARIA NEL CASO SI DIMINUISCA IL PARALLELISMO
      =================================================================================================*/
      FOR ITEM IN (
          SELECT OBJECT_NAME FROM USER_OBJECTS WHERE OBJECT_NAME LIKE 'Q_'|| V_VIRTUAL_QUEUE ||'_%' AND OBJECT_TYPE='QUEUE'
      ) LOOP

          ACTUAL_QUEUE_FOUND := ITEM.OBJECT_NAME;
          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - INDIVIDUATA CODA ' || ACTUAL_QUEUE_FOUND, ADC_PKG_COMMON.WARN_LEVEL,'');
          DBMS_OUTPUT.PUT_LINE('TROVATA CODA ' || ACTUAL_QUEUE_FOUND);

          QUEUE_COUNT   := SUBSTR(ACTUAL_QUEUE_FOUND,      LENGTH(ACTUAL_QUEUE_FOUND) -1);
          V_QUEUE_FOUND := SUBSTR(ACTUAL_QUEUE_FOUND,   3, LENGTH(ACTUAL_QUEUE_FOUND) -5);

          DBMS_OUTPUT.PUT_LINE(V_QUEUE_FOUND || '-->' || QUEUE_COUNT);

          IF(TO_NUMBER(QUEUE_COUNT) > QUEUE_NUMBER) THEN

            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - CODA INCOMPATIBILE CON ATTUALE LIVELLO DI PARALLELISMO ' || ACTUAL_QUEUE_FOUND, ADC_PKG_COMMON.INFO_LEVEL,'');
            DBMS_OUTPUT.PUT_LINE('CODA INCOMPATIBILE CON ATTUALE LIVELLO DI PARALLELISMO ' || ACTUAL_QUEUE_FOUND);

            BEGIN
               BEGIN
                  SELECT QUEUE_TABLE INTO QUEUE_TABLE FROM USER_QUEUES WHERE NAME=ACTUAL_QUEUE_FOUND;
              EXCEPTION WHEN NO_DATA_FOUND THEN
                  QUEUE_TABLE:='QT_'|| V_QUEUE_FOUND || '_' || QUEUE_COUNT;
              END;

              EXECUTE IMMEDIATE 'SELECT COUNT(QUEUE) FROM AQ$'|| QUEUE_TABLE into MESSAGE_NUMBER;

              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - ' ||  MESSAGE_NUMBER || ' NELLA CODA ' || ACTUAL_QUEUE_FOUND, ADC_PKG_COMMON.INFO_LEVEL,'');
              DBMS_OUTPUT.PUT_LINE('MESSAGGI IN CODA ' || MESSAGE_NUMBER);

              BEGIN
                SELECT QUEUE_TABLE INTO QUEUE_TABLE FROM USER_QUEUES WHERE NAME=ACTUAL_QUEUE_FOUND;
              EXCEPTION WHEN NO_DATA_FOUND THEN
                  QUEUE_TABLE:= 'QT_' || V_QUEUE_FOUND || '_' || QUEUE_COUNT;
              END;
              IF(MESSAGE_NUMBER = 0) THEN
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ARRESTO SCODAMENTO DALLA CODA ' || ACTUAL_QUEUE_FOUND, ADC_PKG_COMMON.INFO_LEVEL,'');
                  DBMS_OUTPUT.PUT_LINE('ARRESTO SCODAMENTO DALLA CODA ' || ACTUAL_QUEUE_FOUND);

                  DBMS_AQADM.STOP_QUEUE(queue_name =>'ADC_OWN.' || ACTUAL_QUEUE_FOUND);

                  /* CANCELLAZIONE EVENTUALI JOB ASSOCIATI ALLA CODA */
                  BEGIN
                        SELECT * INTO JOB_ROW FROM USER_SCHEDULER_JOBS WHERE JOB_NAME = 'DEQ_' || ACTUAL_QUEUE_FOUND;

                        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CANCELLAZIONE JOB DI SCODAMENTO SCODAMENTO DEQ_' || ACTUAL_QUEUE_FOUND, ADC_PKG_COMMON.INFO_LEVEL,'');
                        /* ARRESTO ESECUZIONE JOB */
                        IF(JOB_ROW.STATE = 'RUNNING') THEN
                            BEGIN
                                DBMS_SCHEDULER.STOP_JOB (
                                    'ADC_OWN.DEQ_' || ACTUAL_QUEUE_FOUND,
                                FALSE);
                            EXCEPTION WHEN OTHERS THEN
                                DBMS_SCHEDULER.STOP_JOB (
                                    'ADC_OWN.DEQ_' || ACTUAL_QUEUE_FOUND,
                                TRUE);
                            END;
                          END IF;

                          /* DISABILITAZIONE JOB */
                          DBMS_SCHEDULER.DISABLE('ADC_OWN.DEQ_' || ACTUAL_QUEUE_FOUND);

                          /* DROP DEL JOB */
                          DBMS_SCHEDULER.DROP_JOB (
                              JOB_NAME => 'ADC_OWN.DEQ_' || ACTUAL_QUEUE_FOUND);

                    EXCEPTION WHEN NO_DATA_FOUND THEN
                        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'JOB ADC_OWN.DEQ_'|| ACTUAL_QUEUE_FOUND ||' NON PRESENTE' , ADC_PKG_COMMON.WARN_LEVEL,'');
                        DBMS_OUTPUT.PUT_LINE('JOB ADC_OWN.DEQ_'|| ACTUAL_QUEUE_FOUND ||' NON PRESENTE' );
                    END;
                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CANCELLAZIONE CODA ' || ACTUAL_QUEUE_FOUND, ADC_PKG_COMMON.INFO_LEVEL,'');
                    DBMS_OUTPUT.PUT_LINE('CANCELLAZIONE CODA ' || ACTUAL_QUEUE_FOUND);

                    DBMS_AQADM.DROP_QUEUE (
                        QUEUE_NAME         => ACTUAL_QUEUE_FOUND
                    );

                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CANCELLAZIONE TABELLA ' || QUEUE_TABLE, ADC_PKG_COMMON.INFO_LEVEL,'');
                    DBMS_OUTPUT.PUT_LINE('CANCELLAZIONE TABELLA ' || QUEUE_TABLE);
                    DBMS_AQADM.DROP_QUEUE_TABLE (
                        queue_table        => QUEUE_TABLE
                    );
               ELSE
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'LA CODA ' || ACTUAL_QUEUE_FOUND || ' CONTIENE MESSAGGI E NON PUO'' ESSERE CANCELLATA', ADC_PKG_COMMON.INFO_LEVEL,'');
                  DBMS_OUTPUT.PUT_LINE('LA CODA' || ACTUAL_QUEUE_FOUND || 'CONTIENE '   || MESSAGE_NUMBER || ' MESSAGGI');
               END IF;

            EXCEPTION WHEN NO_DATA_FOUND THEN
               LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CONDIZIONE ANOMALA', ADC_PKG_COMMON.WARN_LEVEL,'');
               DBMS_OUTPUT.PUT_LINE('IMPOSSIBILE CHE SI VERIFICHI');
            END;
          END IF;
      END LOOP;


      /* ==============================================================================================
        CREAZIONE DELLE CODE E DEI JOB (DI BUSINESS E DI ERRORE) ASSOCIATI ALLA VIRTUAL QUEUE
        PER RAGGIUNGERE IL GRADO DI PARALLELISMO CONFIGURATO
      =================================================================================================*/

      /* CREAZIONE CODE DI BUSINESS E JOB IN BASE AL LIVELLO DI PARALLELISMO */
      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CREAZIONE CODE DI BUSINESS IN ACCORDO CON LIVELLO DI PARALLELISMO', ADC_PKG_COMMON.INFO_LEVEL,'');
      FOR I IN 1..QUEUE_NUMBER LOOP

        QUEUE_SUFFIX := '0'|| I;

			  DBMS_OUTPUT.PUT_LINE(V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1 ));

        V_QUEUE       :=  'Q_'  || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);
        V_QUEUE_TABLE :=  'QT_' || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);

        BEGIN
            SELECT NAME INTO ACTUAL_QUEUE_FOUND  FROM USER_QUEUES WHERE NAME=V_QUEUE;

            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CODA ' || V_QUEUE || ' GIA'' PRESENTE', ADC_PKG_COMMON.INFO_LEVEL,'');
            DBMS_OUTPUT.PUT_LINE(V_QUEUE || ' ALREADY EXISTS');

            /* CODA INESISTENTE */
            EXCEPTION WHEN NO_DATA_FOUND THEN
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CREAZIONE TABELLA ' || V_QUEUE_TABLE, ADC_PKG_COMMON.INFO_LEVEL,'');
                DBMS_OUTPUT.PUT_LINE('CREAZIONE TABELLA ' || V_QUEUE_TABLE);
                DBMS_AQADM.CREATE_QUEUE_TABLE(
                  QUEUE_TABLE        =>  V_QUEUE_TABLE,
                  QUEUE_PAYLOAD_TYPE =>  MESSAGE_TYPE,
                  storage_clause     => 'PCTFREE 10 PCTUSED 40 INITRANS 8 MAXTRANS 255 TABLESPACE ADC_AQ_TBS',
                  Sort_list          => 'PRIORITY,ENQ_TIME',
                  primary_instance   => 1,
                  secondary_instance => 2);

                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CREAZIONE CODA ' || V_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
                DBMS_OUTPUT.PUT_LINE('CREAZIONE CODA ' || V_QUEUE);
                DBMS_AQADM.CREATE_QUEUE(
                  QUEUE_NAME          => V_QUEUE,
                  Queue_table         => V_QUEUE_TABLE,
                  Queue_type          =>  0,
                  Max_retries         =>  10,
                  RETRY_DELAY         =>  0,
                  DEPENDENCY_TRACKING =>  FALSE);

                  DBMS_AQADM.START_QUEUE (QUEUE_NAME => V_QUEUE,
                          ENQUEUE => TRUE ,
                          dequeue => TRUE
                  );
            END;
            /* VERIFICA ESISTENZA JOB DI SCODAMENTO */
            BEGIN
                SELECT * INTO JOB_ROW FROM USER_SCHEDULER_JOBS WHERE JOB_NAME = 'DEQ_' || V_QUEUE;
                JOB_STATE:=JOB_ROW.STATE;

            /* JOB INESISTENTE */
            EXCEPTION WHEN NO_DATA_FOUND THEN
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CREAZIONE JOB ADC_OWN.DEQ_' || V_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
                  DBMS_OUTPUT.PUT_LINE('CREAZIONE JOB ADC_OWN.DEQ_' || V_QUEUE);
                /* JOB SCODAMENTO*/
                    DBMS_SCHEDULER.CREATE_JOB (
                        JOB_NAME         =>  'ADC_OWN.DEQ_' || V_QUEUE,
                        job_type         =>  'STORED_PROCEDURE',
                        job_action     	=>    DEQUEUE_PROCEDURE,
                        repeat_interval  =>  'FREQ=MINUTELY; INTERVAL='|| SCHEDUL_INTERVAL_IN_MIN ||';',
                        NUMBER_OF_ARGUMENTS => 3,
                        COMMENTS         => 	'Scodamento dalla coda ' || V_QUEUE);

                      /* CONFIGURAZIONE  DEQ_Q01_TT_LOAD_USAGE_01 */
                    DBMS_SCHEDULER.set_job_argument_value(
                        job_name =>  'ADC_OWN.DEQ_' || V_QUEUE,
                        ARGUMENT_POSITION => 1,
                        ARGUMENT_VALUE => V_QUEUE);

                    DBMS_SCHEDULER.SET_JOB_ARGUMENT_VALUE(
                        job_name =>  'ADC_OWN.DEQ_' || V_QUEUE,
                        ARGUMENT_POSITION => 2,
                        ARGUMENT_VALUE => JOB_TIME_LIMIT_INS_SEC);

                    DBMS_SCHEDULER.SET_JOB_ARGUMENT_VALUE(
                        job_name =>  'ADC_OWN.DEQ_' || V_QUEUE,
                        ARGUMENT_POSITION => 3,
                        ARGUMENT_VALUE => 'Q_ERROR_' || V_VIRTUAL_QUEUE);

                    JOB_STATE:='DISABLED';
                END;

            IF(JOB_STATE = 'DISABLED') THEN
               LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENABLE JOB ' || 'ADC_OWN.DEQ_' || V_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
               DBMS_OUTPUT.PUT_LINE('ENABLE JOB ' || 'ADC_OWN.DEQ_' || V_QUEUE);

               DBMS_SCHEDULER.ENABLE('ADC_OWN.DEQ_' || V_QUEUE);
            END IF;
      END LOOP;

     /* GESTIONE CODE DI ERRORE =================================================*/

      IF(QUEUE_NUMBER > 0) THEN
           BEGIN
               SELECT NAME INTO ACTUAL_QUEUE_FOUND  FROM USER_QUEUES WHERE NAME='Q_ERROR_' || V_VIRTUAL_QUEUE;
               LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CODA ' || ACTUAL_QUEUE_FOUND || ' GIA'' ESISTENTE', ADC_PKG_COMMON.INFO_LEVEL,'');
               DBMS_OUTPUT.PUT_LINE(ACTUAL_QUEUE_FOUND || ' ALREADY EXISTS');

          EXCEPTION WHEN OTHERS THEN

                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CREAZIONE TABELLA ' || 'QT_ERROR_' || V_VIRTUAL_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
                DBMS_OUTPUT.PUT_LINE('CREAZIONE TABELLA ' || 'QT_ERROR_' || V_VIRTUAL_QUEUE);

                DBMS_AQADM.CREATE_QUEUE_TABLE(
                  QUEUE_TABLE        =>  'QT_ERROR_' || V_VIRTUAL_QUEUE,
                  QUEUE_PAYLOAD_TYPE =>  MESSAGE_TYPE,
                  storage_clause     => 'PCTFREE 10 PCTUSED 40 INITRANS 8 MAXTRANS 255 TABLESPACE ADC_AQ_TBS',
                  Sort_list          => 'PRIORITY,ENQ_TIME',
                  primary_instance   => 1,
                  secondary_instance => 2);

                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'CREAZIONE CODA ' || 'Q_ERROR_' || V_VIRTUAL_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
                DBMS_OUTPUT.PUT_LINE('CREAZIONE CODA ' || 'Q_ERROR_' || V_VIRTUAL_QUEUE);
                DBMS_AQADM.CREATE_QUEUE(
                  QUEUE_NAME          =>  'Q_ERROR_' || V_VIRTUAL_QUEUE,
                  Queue_table         =>  'QT_ERROR_' || V_VIRTUAL_QUEUE,
                  Queue_type          =>  0,
                  Max_retries         =>  10,
                  RETRY_DELAY         =>  0,
                  DEPENDENCY_TRACKING =>  FALSE);

                  DBMS_AQADM.START_QUEUE (QUEUE_NAME => 'Q_ERROR_' || V_VIRTUAL_QUEUE,
                          ENQUEUE => TRUE ,
                          DEQUEUE => TRUE);
          END;

     END IF;

     VIRTUAL_QUEUE_INFO(V_VIRTUAL_QUEUE, REPORT_STRING );
     LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - CONFIGURAZIONE FRAMEWORK PER LA CODA VIRTUALE ' ||  V_VIRTUAL_QUEUE || ' - END ', ADC_PKG_COMMON.INFO_LEVEL,'');

     LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'INIT_AQ_FRAMEWORK - CONFIGURAZIONE CODA VIRTUALE ' ||  V_VIRTUAL_QUEUE || REPORT_STRING || chr(10), ADC_PKG_COMMON.INFO_LEVEL,'');

     DBMS_OUTPUT.PUT_LINE('INIT_AQ_FRAMEWORK - END');
END;

PROCEDURE TEST_ENQUEUE_USAGE(MESSAGE OUT VARCHAR2,ESITO OUT VARCHAR2) IS

  CONT NUMBER;
  ROW_COUNT                   NUMBER;

  V_ENQUEUE_OPTIONS           DBMS_AQ.ENQUEUE_OPTIONS_T;
	V_MESSAGE_PROPERTIES        DBMS_AQ.MESSAGE_PROPERTIES_T;

  V_USAGE_ROW               ADC_TX_USAGE_NEW%ROWTYPE;
  V_USAGE_MESSAGE_BODY      LOAD_USAGE_MESSAGE_TYPE;

  IN_QUEUE                  VARCHAR2(100);
  V_MESSAGE_HANDLE          RAW(16);
  --V_MESSAGE                 AQ.MESSAGE_TYP;



  recipients          DBMS_AQ.aq$_recipient_list_t;


  CURSOR ADC_TX_USAGE_CUR IS
  --select * FROM ADC_TX_USAGE_TEST ORDER BY ID DESC;
   select U.* FROM ADC_TX_USAGE_NEW U, ADC_TX_JOBID_SESSION J WHERE U.ID_FLUSSO = J.FLUSSO_ID AND J.SESSION_ID = '64949' AND ROWNUM < 10;

  TYPE USAGE_TX_TABLE IS TABLE OF ADC_TX_USAGE_CUR%ROWTYPE INDEX BY PLS_INTEGER;

  V_USAGE_TX USAGE_TX_TABLE;

  BLOCK_SIZE NUMBER;

BEGIN

  ROW_COUNT :=0;
  BLOCK_SIZE:=30;
  --OPEN ADC_TX_USAGE_CUR;

  --RECIPIENTS(1) := SYS.AQ$_AGENT('AG_TT_LOAD_USAGE', NULL, NULL);

  --V_MESSAGE_PROPERTIES.RECIPIENT_LIST := RECIPIENTS;

     FOR V_USAGE_ROW IN ADC_TX_USAGE_CUR

    LOOP



                  V_USAGE_MESSAGE_BODY := LOAD_USAGE_MESSAGE_TYPE();

                  V_USAGE_MESSAGE_BODY.DATA_ORA_EVENTO				:=V_USAGE_ROW.DATA_ORA_EVENTO				;
                  V_USAGE_MESSAGE_BODY.FASE_CICLO_DI_VITA				:=V_USAGE_ROW.FASE_CICLO_DI_VITA			;
                  V_USAGE_MESSAGE_BODY.SOTTO_FASE_CICLO_DI_VITA		:=V_USAGE_ROW.SOTTO_FASE_CICLO_DI_VITA		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_SORGENTE				:=V_USAGE_ROW.SISTEMA_SORGENTE				;
                  V_USAGE_MESSAGE_BODY.CODICE_PRODOTTO_SERVIZIO		:=V_USAGE_ROW.CODICE_PRODOTTO_SERVIZIO		;
                  V_USAGE_MESSAGE_BODY.ESITO							:=V_USAGE_ROW.ESITO							;
                  V_USAGE_MESSAGE_BODY.ID_PROCESSO_INTERNO			:=V_USAGE_ROW.ID_PROCESSO_INTERNO			;
                  V_USAGE_MESSAGE_BODY.ID_TIPO_PROCESSO_INTERNO		:=V_USAGE_ROW.ID_TIPO_PROCESSO_INTERNO		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_PROCESSO_INTERNO		:=V_USAGE_ROW.SISTEMA_PROCESSO_INTERNO		;
                  V_USAGE_MESSAGE_BODY.ID_TRACCIATURA					:=V_USAGE_ROW.ID_TRACCIATURA				;
                  V_USAGE_MESSAGE_BODY.TIPO_PRODOTTO_TRACCIATURA		:=V_USAGE_ROW.TIPO_PRODOTTO_TRACCIATURA		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_TRACCIATURA			:=V_USAGE_ROW.SISTEMA_TRACCIATURA			;
                  V_USAGE_MESSAGE_BODY.ID_ALTRO_PROCESSO				:=V_USAGE_ROW.ID_ALTRO_PROCESSO				;
                  V_USAGE_MESSAGE_BODY.ALTRO_PROCESSO_PRECEDENTE		:=V_USAGE_ROW.ALTRO_PROCESSO_PRECEDENTE		;
                  V_USAGE_MESSAGE_BODY.ID_TIPO_ALTRO_PROCESSO			:=V_USAGE_ROW.ID_TIPO_ALTRO_PROCESSO		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_ALTRO_PROCESSO			:=V_USAGE_ROW.SISTEMA_ALTRO_PROCESSO		;
                  V_USAGE_MESSAGE_BODY.MOTIVO_CONTATTO				:=V_USAGE_ROW.MOTIVO_CONTATTO				;
                  V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC					:=V_USAGE_ROW.KEY_FRAZ_ACC					;
                  V_USAGE_MESSAGE_BODY.KEY_FRAZ_DST					:=V_USAGE_ROW.KEY_FRAZ_DST					;
                  V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL					:=V_USAGE_ROW.KEY_ZONA_PTL					;
                  V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V					:=V_USAGE_ROW.KEY_FRAZ_ACC_V				;
                  V_USAGE_MESSAGE_BODY.KEY_FRAZ_DST_V					:=V_USAGE_ROW.KEY_FRAZ_DST_V				;
                  V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V					:=V_USAGE_ROW.KEY_ZONA_PTL_V				;
                  V_USAGE_MESSAGE_BODY.CODICE_FISCALE_RIC				:=V_USAGE_ROW.CODICE_FISCALE_RIC			;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_RIC		:=V_USAGE_ROW.CODICE_NAZIONE_FISCALE_RIC	;
                  V_USAGE_MESSAGE_BODY.PIVA_RIC						:=V_USAGE_ROW.PIVA_RIC						;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_RIC		:=V_USAGE_ROW.CODICE_NAZIONE_PIVA_RIC		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISCALE_RIC	:= V_USAGE_ROW.SISTEMA_CODICE_NON_FISCALE_RIC	;
                  V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISCALE_RIC	:=V_USAGE_ROW.CODICE_CLIENTE_NON_FISCALE_RIC	;
                  V_USAGE_MESSAGE_BODY.NOME_RIC						:=V_USAGE_ROW.NOME_RIC						;
                  V_USAGE_MESSAGE_BODY.COGNOME_RIC					:=V_USAGE_ROW.COGNOME_RIC					;
                  V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_RIC	:=V_USAGE_ROW.INDIRIZZO_PARTICELLA_TOP_RIC	;
                  V_USAGE_MESSAGE_BODY.INDIRIZZO_RIC					:=V_USAGE_ROW.INDIRIZZO_RIC					;
                  V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_RIC				:=V_USAGE_ROW.NUMERO_CIVICO_RIC				;
                  V_USAGE_MESSAGE_BODY.CAP_RIC						:=V_USAGE_ROW.CAP_RIC						;
                  V_USAGE_MESSAGE_BODY.COMUNE_RIC						:=V_USAGE_ROW.COMUNE_RIC					;
                  V_USAGE_MESSAGE_BODY.PROVINCIA_RIC					:=V_USAGE_ROW.PROVINCIA_RIC					;
                  V_USAGE_MESSAGE_BODY.STATO_RIC						:=V_USAGE_ROW.STATO_RIC						;
                  V_USAGE_MESSAGE_BODY.CODICE_FISCALE_CLI				:=V_USAGE_ROW.CODICE_FISCALE_CLI			;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_CLI		:=V_USAGE_ROW.CODICE_NAZIONE_FISCALE_CLI	;
                  V_USAGE_MESSAGE_BODY.PIVA_CLI						:=V_USAGE_ROW.PIVA_CLI						;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_CLI		:=V_USAGE_ROW.CODICE_NAZIONE_PIVA_CLI		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISCALE_CLI	:=V_USAGE_ROW.SISTEMA_CODICE_NON_FISCALE_CLI	;
                  V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISCALE_CLI	:=V_USAGE_ROW.CODICE_CLIENTE_NON_FISCALE_CLI	;
                  V_USAGE_MESSAGE_BODY.NOME_CLI						:=V_USAGE_ROW.NOME_CLI						;
                  V_USAGE_MESSAGE_BODY.COGNOME_CLI					:=V_USAGE_ROW.COGNOME_CLI					;
                  V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_CLI	:=V_USAGE_ROW.INDIRIZZO_PARTICELLA_TOP_CLI	;
                  V_USAGE_MESSAGE_BODY.INDIRIZZO_CLI					:=V_USAGE_ROW.INDIRIZZO_CLI					;
                  V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_CLI				:=V_USAGE_ROW.NUMERO_CIVICO_CLI				;
                  V_USAGE_MESSAGE_BODY.CAP_CLI						:=V_USAGE_ROW.CAP_CLI						;
                  V_USAGE_MESSAGE_BODY.COMUNE_CLI						:=V_USAGE_ROW.COMUNE_CLI					;
                  V_USAGE_MESSAGE_BODY.PROVINCIA_CLI					:=V_USAGE_ROW.PROVINCIA_CLI					;
                  V_USAGE_MESSAGE_BODY.STATO_CLI						:=V_USAGE_ROW.STATO_CLI						;
                  V_USAGE_MESSAGE_BODY.CODICE_FISCALE_MIT				:=V_USAGE_ROW.CODICE_FISCALE_MIT			;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_MIT		:=V_USAGE_ROW.CODICE_NAZIONE_FISCALE_MIT	;
                  V_USAGE_MESSAGE_BODY.PIVA_MIT						:=V_USAGE_ROW.PIVA_MIT						;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_MIT		:=V_USAGE_ROW.CODICE_NAZIONE_PIVA_MIT		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISCALE_MIT	:=V_USAGE_ROW.SISTEMA_CODICE_NON_FISCALE_MIT	;
                  V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISCALE_MIT	:=V_USAGE_ROW.CODICE_CLIENTE_NON_FISCALE_MIT	;
                  V_USAGE_MESSAGE_BODY.NOME_MIT						:=V_USAGE_ROW.NOME_MIT						;
                  V_USAGE_MESSAGE_BODY.COGNOME_MIT					:=V_USAGE_ROW.COGNOME_MIT					;
                  V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_MIT	:=V_USAGE_ROW.INDIRIZZO_PARTICELLA_TOP_MIT	;
                  V_USAGE_MESSAGE_BODY.INDIRIZZO_MIT					:=V_USAGE_ROW.INDIRIZZO_MIT					;
                  V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_MIT				:=V_USAGE_ROW.NUMERO_CIVICO_MIT				;
                  V_USAGE_MESSAGE_BODY.CAP_MIT						:=V_USAGE_ROW.CAP_MIT						;
                  V_USAGE_MESSAGE_BODY.COMUNE_MIT						:=V_USAGE_ROW.COMUNE_MIT					;
                  V_USAGE_MESSAGE_BODY.PROVINCIA_MIT					:=V_USAGE_ROW.PROVINCIA_MIT					;
                  V_USAGE_MESSAGE_BODY.STATO_MIT						:=V_USAGE_ROW.STATO_MIT						;
                  V_USAGE_MESSAGE_BODY.CODICE_FISCALE_DEST			:=V_USAGE_ROW.CODICE_FISCALE_DEST			;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_DEST	:=V_USAGE_ROW.CODICE_NAZIONE_FISCALE_DEST	;
                  V_USAGE_MESSAGE_BODY.PIVA_DEST						:=V_USAGE_ROW.PIVA_DEST						;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_DEST		:=V_USAGE_ROW.CODICE_NAZIONE_PIVA_DEST		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISC_DEST	:=V_USAGE_ROW.SISTEMA_CODICE_NON_FISC_DEST	;
                  V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISC_DEST	:=V_USAGE_ROW.CODICE_CLIENTE_NON_FISC_DEST	;
                  V_USAGE_MESSAGE_BODY.NOME_DEST						:=V_USAGE_ROW.NOME_DEST						;
