                  V_USAGE_MESSAGE_BODY.INDIRIZZO_DEST					:=V_USAGE_ROW.INDIRIZZO_DEST				;
                  V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_DEST				:=V_USAGE_ROW.NUMERO_CIVICO_DEST			;
                  V_USAGE_MESSAGE_BODY.CAP_DEST						:=V_USAGE_ROW.CAP_DEST						;
                  V_USAGE_MESSAGE_BODY.COMUNE_DEST					:=V_USAGE_ROW.COMUNE_DEST					;
                  V_USAGE_MESSAGE_BODY.PROVINCIA_DEST					:=V_USAGE_ROW.PROVINCIA_DEST				;
                  V_USAGE_MESSAGE_BODY.STATO_DEST						:=V_USAGE_ROW.STATO_DEST					;
                  V_USAGE_MESSAGE_BODY.CODICE_FISCALE_INT				:=V_USAGE_ROW.CODICE_FISCALE_INT			;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_INT		:=V_USAGE_ROW.CODICE_NAZIONE_FISCALE_INT	;
                  V_USAGE_MESSAGE_BODY.PIVA_INT						:=V_USAGE_ROW.PIVA_INT						;
                  V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_INT		:=V_USAGE_ROW.CODICE_NAZIONE_PIVA_INT		;
                  V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISC_INT	:=V_USAGE_ROW.SISTEMA_CODICE_NON_FISC_INT	;
                  V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISC_INT	:=V_USAGE_ROW.CODICE_CLIENTE_NON_FISC_INT	;
                  V_USAGE_MESSAGE_BODY.NOME_INT						:=V_USAGE_ROW.NOME_INT						;
                  V_USAGE_MESSAGE_BODY.COGNOME_INT					:=V_USAGE_ROW.COGNOME_INT					;
                  V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_INT	:=V_USAGE_ROW.INDIRIZZO_PARTICELLA_TOP_INT	;
                  V_USAGE_MESSAGE_BODY.INDIRIZZO_INT					:=V_USAGE_ROW.INDIRIZZO_INT					;
                  V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_INT				:=V_USAGE_ROW.NUMERO_CIVICO_INT				;
                  V_USAGE_MESSAGE_BODY.CAP_INT						:=V_USAGE_ROW.CAP_INT						;
                  V_USAGE_MESSAGE_BODY.COMUNE_INT						:=V_USAGE_ROW.COMUNE_INT					;
                  V_USAGE_MESSAGE_BODY.PROVINCIA_INT					:=V_USAGE_ROW.PROVINCIA_INT					;
                  V_USAGE_MESSAGE_BODY.STATO_INT						:=V_USAGE_ROW.STATO_INT						;
