                  /* MESSO A NULL PER TEST IN MODO DA NON DISALLINEARE LA SEQUENCE */
                  V_USAGE_MESSAGE_BODY.ID	:= NULL;

                  /* DECOMMENTARE PER I TEST BATCH
                  V_USAGE_MESSAGE_BODY.ID								:=V_USAGE_ROW.ID							;
                  */

                  V_USAGE_MESSAGE_BODY.ID_R1							:=V_USAGE_ROW.ID_R1							;
