                  V_USAGE_MESSAGE_BODY.COD_TIPO_TRACCIATURA			:=V_USAGE_ROW.COD_TIPO_TRACCIATURA			;
                  V_USAGE_MESSAGE_BODY.COD_TIPO_ALTROP				:=V_USAGE_ROW.COD_TIPO_ALTROP				;
                  V_USAGE_MESSAGE_BODY.ELAB_PROC						:=V_USAGE_ROW.ELAB_PROC						;
                  V_USAGE_MESSAGE_BODY.ELAB_TRAC						:=V_USAGE_ROW.ELAB_TRAC						;
                  V_USAGE_MESSAGE_BODY.ELAB_ALTR						:=V_USAGE_ROW.ELAB_ALTR						;
                  V_USAGE_MESSAGE_BODY.ID_FASE						:=V_USAGE_ROW.ID_FASE						;
                  V_USAGE_MESSAGE_BODY.ID_SOTTOFASE					:=V_USAGE_ROW.ID_SOTTOFASE					;
                  V_USAGE_MESSAGE_BODY.ID_PROD_SERVIZIO				:=V_USAGE_ROW.ID_PROD_SERVIZIO				;
                  V_USAGE_MESSAGE_BODY.ALTRO_ID_TRACCIATURA			:=V_USAGE_ROW.ALTRO_ID_TRACCIATURA			;
                  V_USAGE_MESSAGE_BODY.CODICE_PTL						:=V_USAGE_ROW.CODICE_PTL					;
                  V_USAGE_MESSAGE_BODY.COMUNE_LUOGO_EVENTO			:=V_USAGE_ROW.COMUNE_LUOGO_EVENTO			;
                  V_USAGE_MESSAGE_BODY.COSTO_PRODOTTO_SERVIZIO		:=V_USAGE_ROW.COSTO_PRODOTTO_SERVIZIO		;
                  V_USAGE_MESSAGE_BODY.DATA_INSERIMENTO				:=V_USAGE_ROW.DATA_INSERIMENTO				;
                  V_USAGE_MESSAGE_BODY.FILIALE_SDA					:=V_USAGE_ROW.FILIALE_SDA					;
                  V_USAGE_MESSAGE_BODY.FRAZ_ACC						:=V_USAGE_ROW.FRAZ_ACC						;
                  V_USAGE_MESSAGE_BODY.FRAZ_DST						:=V_USAGE_ROW.FRAZ_DST						;
                  V_USAGE_MESSAGE_BODY.ID_FLUSSO						:=V_USAGE_ROW.ID_FLUSSO						;
                  V_USAGE_MESSAGE_BODY.MAIL_RIC						:=V_USAGE_ROW.MAIL_RIC						;
                  V_USAGE_MESSAGE_BODY.MAIL_CLI						:=V_USAGE_ROW.MAIL_CLI						;
                  V_USAGE_MESSAGE_BODY.MAIL_MIT						:=V_USAGE_ROW.MAIL_MIT						;
