                  V_USAGE_MESSAGE_BODY.MAIL_INT						:=V_USAGE_ROW.MAIL_INT						;
                  V_USAGE_MESSAGE_BODY.METODO_PAGAMENTO_CLIENTE		:=V_USAGE_ROW.METODO_PAGAMENTO_CLIENTE		;
                  V_USAGE_MESSAGE_BODY.PROVINCIA_LUOGO_EVENTO			:=V_USAGE_ROW.PROVINCIA_LUOGO_EVENTO		;
