                  V_USAGE_MESSAGE_BODY.ZONA_PTL						:=V_USAGE_ROW.ZONA_PTL						;
                  V_USAGE_MESSAGE_BODY.KEY_CODICE_PTL					:=V_USAGE_ROW.KEY_CODICE_PTL				;
                  V_USAGE_MESSAGE_BODY.REFE_DEST						:=V_USAGE_ROW.REFE_DEST						;
                  V_USAGE_MESSAGE_BODY.ID_CANALE						:=V_USAGE_ROW.ID_CANALE						;
                  V_USAGE_MESSAGE_BODY.ID_METODO_PAGAMENTO_CLIENTE	:=V_USAGE_ROW.ID_METODO_PAGAMENTO_CLIENTE	;
                  V_USAGE_MESSAGE_BODY.ID_TIPO_CLIENTE_PAGAMENTO		:=V_USAGE_ROW.ID_TIPO_CLIENTE_PAGAMENTO		;
                  V_USAGE_MESSAGE_BODY.NFEA_DETTAGLIO_A_CHIAMATA		:=V_USAGE_ROW.NFEA_DETTAGLIO_A_CHIAMATA		;
                  V_USAGE_MESSAGE_BODY.NFEA_DETTAGLIO_B_CHIAMATA		:=V_USAGE_ROW.NFEA_DETTAGLIO_B_CHIAMATA		;
                  V_USAGE_MESSAGE_BODY.NFEA_SITO_CC					:=V_USAGE_ROW.NFEA_SITO_CC					;
                  V_USAGE_MESSAGE_BODY.NFEA_FORNITORE_CC				:=V_USAGE_ROW.NFEA_FORNITORE_CC				;
                  V_USAGE_MESSAGE_BODY.NFEA_TEAM						:=V_USAGE_ROW.NFEA_TEAM						;
                  V_USAGE_MESSAGE_BODY.NFEA_LOGIN						:=V_USAGE_ROW.NFEA_LOGIN					;
                  V_USAGE_MESSAGE_BODY.FRAZIONARIO_UP					:=V_USAGE_ROW.FRAZIONARIO_UP				;
                  V_USAGE_MESSAGE_BODY.NOME_UP						:=V_USAGE_ROW.NOME_UP						;
                  V_USAGE_MESSAGE_BODY.CITTA_LUOGO_EVENTO				:=V_USAGE_ROW.CITTA_LUOGO_EVENTO			;
                  V_USAGE_MESSAGE_BODY.ALT							:=V_USAGE_ROW.ALT							;
                  V_USAGE_MESSAGE_BODY.RAM							:=V_USAGE_ROW.RAM							;
                  V_USAGE_MESSAGE_BODY.CD								:=V_USAGE_ROW.CD							;
                  V_USAGE_MESSAGE_BODY.ZONA							:=V_USAGE_ROW.ZONA							;
                  V_USAGE_MESSAGE_BODY.TIPOLOGIA						:=V_USAGE_ROW.TIPOLOGIA						;
                  V_USAGE_MESSAGE_BODY.ID_TRACC_CORR					:=V_USAGE_ROW.ID_TRACC_CORR					;
                  V_USAGE_MESSAGE_BODY.TIPO_PROD_TRACC_CORR			:=V_USAGE_ROW.TIPO_PROD_TRACC_CORR			;
                  V_USAGE_MESSAGE_BODY.SIST_TRACC_CORR				:=V_USAGE_ROW.SIST_TRACC_CORR				;
                  V_USAGE_MESSAGE_BODY.COD_TIPO_PROD_TRACC_CORR		:=V_USAGE_ROW.COD_TIPO_PROD_TRACC_CORR		;
                  V_USAGE_MESSAGE_BODY.COD_SIST_TRACC_CORR			:=V_USAGE_ROW.COD_SIST_TRACC_CORR			;


                  v_message_properties.user_property := SYS.ANYDATA.ConvertNumber(V_USAGE_MESSAGE_BODY.ID_FLUSSO);

                  IN_QUEUE := 'Q_TT_LOAD_USAGE_01';

                  DBMS_AQ.ENQUEUE(
                      queue_name              => IN_QUEUE,
                      enqueue_options         => V_ENQUEUE_OPTIONS,
                      message_properties      => v_message_properties,
                      PAYLOAD                 => V_USAGE_MESSAGE_BODY,
                      MSGID                   => V_MESSAGE_HANDLE
                    );

                END LOOP;
                COMMIT;
END;


PROCEDURE ENQUEUE_USAGE_DYNAMIC_INIT(INPUT_ID_SESSION NUMBER,  V_VIRTUAL_QUEUE VARCHAR2, MESSAGE OUT VARCHAR2,ESITO OUT VARCHAR2) IS

  MIN_USAGE NUMBER;
  MAX_USAGE NUMBER;
  USAGE_BLOCK NUMBER;
  CURRENT_MIN_USAGE NUMBER;
  CURRENT_MAX_USAGE NUMBER;

  LOGRESULT         NUMBER;

  TYPE QUEUES_TABLE IS TABLE OF VARCHAR2(100) INDEX BY PLS_INTEGER;
  QUEUE_INDEX                 NUMBER;
  QUEUES                      QUEUES_TABLE;
  QUEUE_NUMBER                NUMBER;

  V_QUEUE                       VARCHAR2(255);
  BAD_RECORD_QUEUE              VARCHAR2(255);
  ENQUEUE_PROCEDURE             VARCHAR(255);
  ENABLED                       VARCHAR2(10);
  QUEUE_SUFFIX                  VARCHAR2(10);
  BLOCK_SIZE                    NUMBER;
  NAME_JOB                      VARCHAR2(255);
  ACTIVE_ENQUEUER_JOB_THRESHOLD VARCHAR2(255);
  ACTUAL_JOB_COUNT              NUMBER;
  V_JOB_CREATOR                 VARCHAR2(255) :=  'ADC_OWN';
  TABLE_NAME                    VARCHAR2(100);

  CURSOR SESSION_ENQUEUERS_CUR IS
      SELECT ACTIVE_ENQUEUER FROM ADC_TX_JOBID_SESSION S WHERE SESSION_ID=INPUT_ID_SESSION FOR UPDATE;

  ACTIVE_ENQUEUER_NUMBER          NUMBER;

  BEGIN

		  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - BEGIN ', ADC_PKG_COMMON.INFO_LEVEL,INPUT_ID_SESSION);

      BEGIN
          SELECT PARAMETER_VALUE INTO ENABLED FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='ENABLED' AND ROWNUM = 1;
		  EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO ENABLED FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='ENABLED' AND ROWNUM = 1;
		  END;

      /* ACTIVE_ENQUEUER_JOB_THRESHOLD */
      BEGIN
          SELECT PARAMETER_VALUE INTO ACTIVE_ENQUEUER_JOB_THRESHOLD FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'FINALIZE_LOAD_USAGE' AND AQC.PARAMETER_TYPE='ACTIVE_ENQUEUER_JOB_THRESHOLD' AND ROWNUM = 1;
		  EXCEPTION WHEN NO_DATA_FOUND THEN
           ACTIVE_ENQUEUER_JOB_THRESHOLD := 20;
		  END;


      /* TABLE_NAME NAME  - OBBLIGATORIO */
      SELECT PARAMETER_VALUE INTO TABLE_NAME FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='SOURCE_TABLE' AND ROWNUM = 1;

      IF(UPPER(ENABLED) = 'TRUE') THEN

            SELECT COUNT(JOB_NAME) INTO ACTUAL_JOB_COUNT FROM USER_SCHEDULER_JOBS WHERE JOB_NAME LIKE '%ENQ_%' AND JOB_CREATOR = V_JOB_CREATOR;

            IF(ACTUAL_JOB_COUNT < ACTIVE_ENQUEUER_JOB_THRESHOLD) THEN

              BEGIN
                  SELECT PARAMETER_VALUE INTO QUEUE_NUMBER FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='QUEUE_NUMBER' AND ROWNUM = 1;
              EXCEPTION WHEN NO_DATA_FOUND THEN
                  SELECT PARAMETER_VALUE INTO QUEUE_NUMBER FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='QUEUE_NUMBER' AND ROWNUM = 1;
              END;

              QUEUE_INDEX :=1;
              --FOR V_QUEUE IN (SELECT PARAMETER_VALUE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND PARAMETER_TYPE='QUEUE_MEMBER') LOOP
              FOR I IN 1..QUEUE_NUMBER LOOP

               QUEUE_SUFFIX := '0'||I;

                DBMS_OUTPUT.PUT_LINE(V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1 ));
                V_QUEUE       :=  'Q_'  || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);
                --V_QUEUE_TABLE :=  'QT_' || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);
                QUEUES(QUEUE_INDEX):= V_QUEUE;
                QUEUE_INDEX := QUEUE_INDEX + 1;
              END LOOP;

              BAD_RECORD_QUEUE := 'Q_BAD_' ||V_VIRTUAL_QUEUE;

              BEGIN
                  SELECT PARAMETER_VALUE INTO ENQUEUE_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='ENQUEUE_PROCEDURE'  AND ROWNUM = 1;
              EXCEPTION WHEN NO_DATA_FOUND THEN
                  SELECT PARAMETER_VALUE INTO ENQUEUE_PROCEDURE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='ENQUEUE_PROCEDURE'  AND ROWNUM = 1;
              END;

              BEGIN
                  SELECT PARAMETER_VALUE INTO BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='ENQUEUE_BLOCK_SIZE' AND ROWNUM = 1;
              EXCEPTION WHEN NO_DATA_FOUND THEN
                  SELECT PARAMETER_VALUE INTO BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='ENQUEUE_BLOCK_SIZE' AND ROWNUM = 1;
              END;

              QUEUE_NUMBER:= QUEUES.COUNT;

             EXECUTE IMMEDIATE 'SELECT /* ADC_PKG_LOAD_USAGE_S13 */ MIN(U.ID), MAX(U.ID)  FROM ' || TABLE_NAME || ' U, ADC_TX_JOBID_SESSION J WHERE U.ID_FLUSSO = J.FLUSSO_ID AND J.SESSION_ID = '||INPUT_ID_SESSION INTO MIN_USAGE, MAX_USAGE;

             IF(MIN_USAGE IS NOT NULL AND MAX_USAGE IS NOT NULL) THEN

                  IF((MAX_USAGE - MIN_USAGE) < QUEUE_NUMBER) THEN
                      IF(MAX_USAGE = MIN_USAGE) THEN
                        QUEUE_NUMBER :=1;
                        USAGE_BLOCK  := 0;
                      ELSE
                        QUEUE_NUMBER  := MAX_USAGE - MIN_USAGE;
                        USAGE_BLOCK   := 1;
                      END IF;
                  ELSE
                      USAGE_BLOCK := FLOOR((MAX_USAGE - MIN_USAGE )/QUEUE_NUMBER);
                  END IF;

                  BEGIN
                    OPEN SESSION_ENQUEUERS_CUR;
                      LOOP
                        FETCH SESSION_ENQUEUERS_CUR INTO ACTIVE_ENQUEUER_NUMBER;
                          EXIT WHEN SESSION_ENQUEUERS_CUR%NOTFOUND;
                          UPDATE /* ADC_PKG_LOAD_USAGE_U34 */ ADC_TX_JOBID_SESSION SET ACTIVE_ENQUEUER = QUEUE_NUMBER WHERE SESSION_ID = INPUT_ID_SESSION;
                        END LOOP;
                      CLOSE SESSION_ENQUEUERS_CUR;
                    EXCEPTION WHEN OTHERS THEN
                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - IMPOSSIBILE IMPOSTARE IL NUMERO DI ACCODATORI ATTIVI PER LA SESSIONE ' ||  INPUT_ID_SESSION, ADC_PKG_COMMON.ERROR_LEVEL, INPUT_ID_SESSION);
                    CLOSE SESSION_ENQUEUERS_CUR;
                  END;
                  -- DBMS_OUTPUT.PUT_LINE(USAGE_BLOCK);

                  -- DBMS_OUTPUT.PUT_LINE(MIN_USAGE || '-->' || MAX_USAGE);

                  FOR I IN 1..QUEUE_NUMBER LOOP
                    DBMS_OUTPUT.PUT_LINE(QUEUES(I));
                    CURRENT_MIN_USAGE := (MIN_USAGE + (I-1) * USAGE_BLOCK) + 1 ;
                    CURRENT_MAX_USAGE := MIN_USAGE + (I) * USAGE_BLOCK;

                    IF( I = 1) THEN
                      CURRENT_MIN_USAGE := MIN_USAGE;
                    ELSE IF( I= QUEUE_NUMBER) THEN
                      CURRENT_MAX_USAGE := MAX_USAGE;
                    END IF;
                    END IF;

                    -- DBMS_OUTPUT.PUT_LINE(CURRENT_MIN_USAGE || '-->' || CURRENT_MAX_USAGE);

                    NAME_JOB := SUBSTR('ENQ_' || LPAD(TO_CHAR(INPUT_ID_SESSION), 4, '0') || '_' || QUEUES(I), 1 , 29);

                    DBMS_SCHEDULER.CREATE_JOB (
                      JOB_NAME            =>  'ADC_OWN.' || NAME_JOB,
                      JOB_TYPE            => 	'STORED_PROCEDURE',
                      --JOB_ACTION     	  =>  'ADC_OWN.ADC_PKG_JOBS.ENQUEUE_TT_LOAD_USAGE',
                      JOB_ACTION     	    =>  ENQUEUE_PROCEDURE,
                      NUMBER_OF_ARGUMENTS =>  6,
                      comments            => 	'Accodamento nella coda ' || QUEUES(i) );


                    /*====== IMPOSTAZIONE PARAMETRI JOB =================================================*/

                    /* CONFIGURAZIONE  DEQ_Q01_TT_LOAD_USAGE_01 */

                    DBMS_SCHEDULER.set_job_argument_value(
                      job_name =>  NAME_JOB,
                      argument_position => 1,
                      argument_value => INPUT_ID_SESSION);

                    DBMS_SCHEDULER.set_job_argument_value(
                      job_name =>  NAME_JOB,
                      ARGUMENT_POSITION => 2,
                      argument_value => QUEUES(i));

                    DBMS_SCHEDULER.set_job_argument_value(
                      job_name =>  NAME_JOB,
                      ARGUMENT_POSITION => 3,
                      argument_value => BAD_RECORD_QUEUE);

                    DBMS_SCHEDULER.set_job_argument_value(
                      job_name =>  NAME_JOB,
                      ARGUMENT_POSITION => 4,
                      argument_value => BLOCK_SIZE);

                    DBMS_SCHEDULER.set_job_argument_value(
                      job_name =>  NAME_JOB,
                      ARGUMENT_POSITION => 5,
                      argument_value => CURRENT_MIN_USAGE);

                    DBMS_SCHEDULER.set_job_argument_value(
                      job_name =>  NAME_JOB,
                      ARGUMENT_POSITION => 6,
                      argument_value => CURRENT_MAX_USAGE);

                    dbms_scheduler.enable(NAME_JOB);

                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - ' || NAME_JOB || '  START ON QUEUE: ' || QUEUES(I), ADC_PKG_COMMON.DEBUG_LEVEL, INPUT_ID_SESSION);
                  END LOOP;
              ELSE
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - NESSUN RECORD PER LA SESSION: ' || INPUT_ID_SESSION , ADC_PKG_COMMON.INFO_LEVEL, INPUT_ID_SESSION);
                /* BISOGNA AZZERARE PURE QUI IL NUMERO DEGLI SCODATORI?*/
                  BEGIN
                  OPEN SESSION_ENQUEUERS_CUR;
                      LOOP
                          FETCH SESSION_ENQUEUERS_CUR INTO ACTIVE_ENQUEUER_NUMBER;
                          EXIT WHEN SESSION_ENQUEUERS_CUR%NOTFOUND;
                          UPDATE /* ADC_PKG_LOAD_USAGE_U35 */ ADC_TX_JOBID_SESSION SET ACTIVE_ENQUEUER = 0 WHERE SESSION_ID = INPUT_ID_SESSION;
                      END LOOP;
                  CLOSE SESSION_ENQUEUERS_CUR;
                EXCEPTION WHEN OTHERS THEN
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - IMPOSSIBILE AZZERARE IL NUMERO DI ACCODATORI ATTIVI PER LA SESSIONE ' ||  INPUT_ID_SESSION, ADC_PKG_COMMON.ERROR_LEVEL, INPUT_ID_SESSION);
                  CLOSE SESSION_ENQUEUERS_CUR;
                END;
              END IF;
          ELSE   -- SUPERATO LA SOGLIA DEI JOB DI ACCODAMENTO
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - ATTIVITA'' POSTICIPATA: SUPERATO IL NUMERO MASSIMO DI JOB DI ACCODADAMENTO PARALLELI:' || ACTUAL_JOB_COUNT , ADC_PKG_COMMON.ERROR_LEVEL, INPUT_ID_SESSION);

                BEGIN
                  OPEN SESSION_ENQUEUERS_CUR;
                      LOOP
                          FETCH SESSION_ENQUEUERS_CUR INTO ACTIVE_ENQUEUER_NUMBER;
                          EXIT WHEN SESSION_ENQUEUERS_CUR%NOTFOUND;
                          UPDATE /* ADC_PKG_LOAD_USAGE_U36 */ ADC_TX_JOBID_SESSION SET ACTIVE_ENQUEUER = 0 WHERE SESSION_ID= INPUT_ID_SESSION;
                      END LOOP;
                  CLOSE SESSION_ENQUEUERS_CUR;
                EXCEPTION WHEN OTHERS THEN
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - IMPOSSIBILE AZZERARE IL NUMERO DI ACCODATORI ATTIVI PER LA SESSIONE ' ||  INPUT_ID_SESSION, ADC_PKG_COMMON.ERROR_LEVEL, INPUT_ID_SESSION);
                  CLOSE SESSION_ENQUEUERS_CUR;
                END;
                COMMIT;
                raise_application_error(-20001,'SUPERATO IL NUMERO MASSIMO DI JOB DI ACCODADAMENTO PARALLELI: ' || ACTUAL_JOB_COUNT );
          END IF;
      ELSE
          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - VIRTUAL QUEUE ' || V_VIRTUAL_QUEUE || ' DISABLED: CLEAR ' || TABLE_NAME, ADC_PKG_COMMON.ERROR_LEVEL,INPUT_ID_SESSION);

          FOR ITEM IN(
            SELECT J.FLUSSO_ID  FROM ADC_TX_JOBID_SESSION J WHERE J.SESSION_ID = INPUT_ID_SESSION) LOOP
            BEGIN
              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - DROP ' || TABLE_NAME || ' PARTITION ' || ITEM.FLUSSO_ID, ADC_PKG_COMMON.INFO_LEVEL, INPUT_ID_SESSION);
              EXECUTE IMMEDIATE 'ALTER TABLE ' || TABLE_NAME || ' DROP PARTITION FOR (' || ITEM.FLUSSO_ID || ') UPDATE GLOBAL INDEXES';
            EXCEPTION WHEN OTHERS THEN
              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - ERROR IN DROP ' || TABLE_NAME || ' PARTITION ' || ITEM.FLUSSO_ID, ADC_PKG_COMMON.ERROR_LEVEL, INPUT_ID_SESSION);
            END;
          END LOOP;
          raise_application_error (-20001,'CODA VIRTUALE ' || V_VIRTUAL_QUEUE || ' DISABILITATA');
      END IF;
      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_DYNAMIC_INIT - END ', ADC_PKG_COMMON.INFO_LEVEL, INPUT_ID_SESSION);
END;


PROCEDURE ENQUEUE_USAGE_RANGE(JOB_ID NUMBER, INPUT_ID_SESSION NUMBER,  IN_QUEUE VARCHAR2, BAD_RECORD_QUEUE VARCHAR2, BLOCK_SIZE NUMBER, MIN_ID_USAGE NUMBER, MAX_ID_USAGE NUMBER, MESSAGE OUT VARCHAR2,ESITO OUT VARCHAR2) IS

  ROW_COUNT                   NUMBER;
  COMMIT_COUNT                NUMBER;
  MESSAGE_COUNT               NUMBER;
  BAD_MESSAGE_COUNT           NUMBER;

  V_USAGE_ROW                 ADC_TX_USAGE_NEW%ROWTYPE;
  V_USAGE_MESSAGE_BODY        LOAD_USAGE_MESSAGE_TYPE;
  V_DUP_USAGE_MESSAGE_BODY    LOAD_USAGE_MESSAGE_TYPE;

  V_COD_TIPO_PROC_INTERNO         VARCHAR(255);
  V_COD_SIS_PROC_INTERNO          VARCHAR(255);
  V_COD_TIPO_PROC_ALTROP          VARCHAR(255);
  V_COD_TIPO_PROD_TRACC           VARCHAR(255);
  V_COD_SIS_TRACCIATURA           VARCHAR(255);
  V_COD_FASE_VITA                 NUMBER;
  V_COD_SOTTOFASE_VITA            NUMBER;
  V_COD_PROD_SERVIZIO             VARCHAR(255);
  V_COD_CANALE                    NUMBER;
  V_COD_TIPO_CLIENTE_PAGA         VARCHAR(255);
  V_COD_METO_PAGA_CLIENTE         VARCHAR(255);
  V_COD_TIP_TIPO_PROC_INTERNO     VARCHAR(255);
  V_COD_TIP_SISTEMA_PROC_INTERNO  VARCHAR(255);
  V_COD_TIP_TIPO_PROD_TRACCIATUR  VARCHAR(255);
  V_COD_TIP_SISTEMA_TRACCIATURE   VARCHAR(255);
  V_COD_TIP_PROD_SERVIZIO           VARCHAR(255);
  V_COD_TIP_TIPO_CANALE               VARCHAR(255);
  V_COD_TIP_CLIENTE_PAGAM           VARCHAR(255);
  V_COD_TIP_PAGAM_CLIENTE           VARCHAR(255);

  V_COD_SIS_PROC_ALTRO            VARCHAR(255);
  V_COD_TIPO_PROC_ALTRO           VARCHAR(255);
  V_COD_TIP_SISTEMA_PROC_ALTRO    VARCHAR(255);
  V_COD_TIP_TIPO_PROC_ALTRO       VARCHAR(255);
  V_COD_TIP_ID_CANALE             NUMBER;
  V_COD_TIP_PAGAMENTO             VARCHAR(255);
  V_COD_TIP_METODO_PAGAMENTO      VARCHAR(255);
  V_COD_TIP_FASE_VITA             NUMBER;
  V_COD_TIP_SOTTOFASE_VITA        NUMBER;

  V_COD_TIP_SISTEMA_TR_CORREL     VARCHAR2(255);
  V_COD_TIP_TIPO_PROD_TR_CORR     VARCHAR(255);
  V_COD_SIS_TRACCIATURA_CORR      VARCHAR(255);
  V_COD_TIPO_PROD_TRACC_CORR      VARCHAR(255);

  V_COD_NAZIONALE_FIS_RIC VARCHAR2(255);
  V_COD_NAZIONALE_FIS_CLI VARCHAR2(255);
  V_COD_NAZIONALE_FIS_MIT VARCHAR2(255);
  V_COD_NAZIONALE_FIS_DEST VARCHAR2(255);
  V_COD_NAZIONALE_FIS_INT VARCHAR2(255);
  V_CN_PIVA_RIC VARCHAR2(255);
  V_CN_PIVA_CLI VARCHAR2(255);
  V_CN_PIVA_MIT VARCHAR2(255);
  V_CN_PIVA_DEST VARCHAR2(255);
  V_CN_PIVA_INT VARCHAR2(255);

  /*  OGGETTI ACCODAMENTO */
  V_ENQUEUE_OPTIONS               DBMS_AQ.ENQUEUE_OPTIONS_T;
	V_MESSAGE_PROPERTIES            DBMS_AQ.MESSAGE_PROPERTIES_T;
  V_MESSAGE_HANDLE_ARRAY          DBMS_AQ.MSGID_ARRAY_T;
  V_MSG_PROPERTIES_TABLE          DBMS_AQ.MESSAGE_PROPERTIES_ARRAY_T;
  V_USAGE_MESSAGE_BODY_ARRAY      LOAD_USAGE_MESSAGES_ARRAY;
  V_MESSAGE_HANDLE                RAW(16);
  V_ENQUEUED_CNT                  PLS_INTEGER;

  ACTIVE_ENQUEUER_NUMBER          NUMBER;
  --V_MESSAGE                 AQ.MESSAGE_TYP;

  CURSOR ADC_TX_USAGE_CUR IS
      SELECT U.* FROM ADC_TX_USAGE_NEW U, ADC_TX_JOBID_SESSION S
      WHERE U.ID BETWEEN MIN_ID_USAGE
      AND MAX_ID_USAGE AND S.SESSION_ID = INPUT_ID_SESSION AND S.FLUSSO_ID = U.ID_FLUSSO;


  CURSOR SESSION_ENQUEUERS_CUR IS
      select ACTIVE_ENQUEUER FROM ADC_TX_JOBID_SESSION S WHERE SESSION_ID=INPUT_ID_SESSION FOR UPDATE;

  TYPE USAGE_TX_TABLE IS TABLE OF ADC_TX_USAGE_CUR%ROWTYPE INDEX BY PLS_INTEGER;

  V_USAGE_TX        USAGE_TX_TABLE;


  LOGRESULT         NUMBER;
  L_START           NUMBER;
  L_END             NUMBER;

  Q_START           NUMBER;
  Q_END             NUMBER;

  WK_CODICE         VARCHAR2(32767);
  WK_TROVA          VARCHAR2(32767);
  IS_DEBUG_ENABLED  BOOLEAN;

BEGIN

  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_RANGE  (JOB ID: ' || JOB_ID || ') (' ||IN_QUEUE||  ')- BEGIN', ADC_PKG_COMMON.INFO_LEVEL,INPUT_ID_SESSION);
  DBMS_OUTPUT.PUT_LINE('PROCEDURE: ENQUEUE_USAGE_RANGE  (JOB ID: ' || JOB_ID || ') (' ||IN_QUEUE||  ')- BEGIN');

  ROW_COUNT           :=0;
  COMMIT_COUNT        :=0;
  MESSAGE_COUNT       :=0;
  BAD_MESSAGE_COUNT   :=0;
  v_enqueued_cnt      :=0;

  IS_DEBUG_ENABLED    := ADC_PKG_COMMON.IS_LEVEL_ENABLED(LOGGER_NAME, ADC_PKG_COMMON.DEBUG_LEVEL);

  L_START := DBMS_UTILITY.GET_TIME ;  -- Start Time

  OPEN ADC_TX_USAGE_CUR;

 -- LOAD in ARRAY ADC_TRANS_TIPO_PROC_INTERNO BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_TIPO_PROC_INTERNO)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_TIPO_PROC_INT(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_TIPO_PROC_INTERNO: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_TIPO_PROC_INT(wk_CODICE).COD_TIPO_PROC_INTERNO);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_SIS_PROC_INTERNO BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_SIS_PROC_INTERNO)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_SIS_PROC_INT(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_SIS_PROC_INTERNO: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_SIS_PROC_INT(wk_CODICE).COD_SIS_PROC_INTERNO);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_TIPO_PROD_TRACC BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_TIPO_PROD_TRACC)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_TIPO_PROD_TR(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_TIPO_PROD_TRACC: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_TIPO_PROD_TR(wk_CODICE).COD_TIPO_PROD_TRACC);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_SIS_TRACCIATURA BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_SIS_TRACCIATURA)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_SIS_TRACC(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_SIS_TRACCIATURA: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_SIS_TRACC(wk_CODICE).COD_SIS_TRACCIATURA);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_FASE_VITA BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_FASE_VITA)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_FASE_VITA(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_FASE_VITA: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_FASE_VITA(wk_CODICE).ID_FASE);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_SOTTOFASE_VITA BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_SOTTOFASE_VITA)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_SOTTOFASE_VI(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_SOTTOFASE_VITA: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_SOTTOFASE_VI(wk_CODICE).ID_SOTTOFASE);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_COD_PROD_SERVIZIO BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_COD_PROD_SERVIZIO)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_COD_PROD_SERV(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_COD_PROD_SERVIZIO: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_COD_PROD_SERV(wk_CODICE).ID_PROD_SERVIZIO);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_CANALE BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_CANALE)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_CANALE(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_CANALE: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_CANALE(wk_CODICE).ID_CANALE);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_TIPO_CLIENTE_PAGA BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_TIPO_CLIENTE_PAGA)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_TIPO_CLI_PA(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_TIPO_CLIENTE_PAGA: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_TIPO_CLI_PA(wk_CODICE).COD_TIPO_CLI_PAG);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_METO_PAGA_CLIENTE BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_METO_PAGA_CLIENTE)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_METO_PAGA_CLI(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TRANS_METO_PAGA_CLIENTE: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TRANS_METO_PAGA_CLI(wk_CODICE).ID_METOD_PAG);

      END LOOP;

  -- LOAD in ARRAY ADC_TIP_TIPO_PROC_INTERNO BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_TIPO_PROC_INTERNO)
        LOOP

            wk_CODICE := recordItem.CODICE;

            r_tIdx_ADC_TIP_TIPO_PROC_INT(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_TIPO_PROC_INTERNO: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_TIPO_PROC_INT(wk_CODICE).CODICE);

      END LOOP;

  -- LOAD in ARRAY ADC_TIP_SISTEMA_PROC_INTERNO BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_SISTEMA_PROC_INTERNO)
        LOOP

            wk_CODICE := recordItem.CODICE;

            r_tIdx_ADC_TIP_SIST_PROC_INT(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_SISTEMA_PROC_INTERNO: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_SIST_PROC_INT(wk_CODICE).CODICE);

      END LOOP;


  -- LOAD in ARRAY ADC_TIP_TIPO_PROD_TRACCIATURA BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_TIPO_PROD_TRACCIATURA)
        LOOP

            wk_CODICE := recordItem.CODICE;

            r_tIdx_ADC_TIP_TIPO_PROD_TRACC(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_TIPO_PROD_TRACCIATURA: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_TIPO_PROD_TRACC(wk_CODICE).CODICE);

      END LOOP;

  -- LOAD in ARRAY ADC_TIP_SISTEMA_TRACCIATURE BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_SISTEMA_TRACCIATURE)
        LOOP

            wk_CODICE := recordItem.CODICE;

            r_tIdx_ADC_TIP_SISTEMA_TRACC(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_SISTEMA_TRACCIATURE: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_SISTEMA_TRACC(wk_CODICE).CODICE);

      END LOOP;


  -- LOAD in ARRAY ADC_TIP_PROD_SERVIZIO BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_PROD_SERVIZIO)
        LOOP

            wk_CODICE := recordItem.CODICE;

            r_tIdx_ADC_TIP_PROD_SERVIZIO(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_PROD_SERVIZIO: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_PROD_SERVIZIO(wk_CODICE).CODICE);

      END LOOP;

  -- LOAD in ARRAY ADC_TIP_TIPO_CANALE BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_TIPO_CANALE)
        LOOP

            wk_CODICE := recordItem.ID;

            r_tIdx_ADC_TIP_TIPO_CANALE(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_TIPO_CANALE: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_TIPO_CANALE(wk_CODICE).CANALE);

      END LOOP;

   -- LOAD in ARRAY ADC_TIP_TIPO_CLIENTE_PAGAM BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_TIPO_CLIENTE_PAGAM)
        LOOP

            wk_CODICE := recordItem.CODICE;

            r_tIdx_ADC_TIP_TIPO_CLIENTE_P(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_TIPO_CLIENTE_PAGAM: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_TIPO_CLIENTE_P(wk_CODICE).PAGAMENTO);

      END LOOP;

   -- LOAD in ARRAY ADC_TIP_METOD_PAGAM_CLIENTE BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_METOD_PAGAM_CLIENTE)
        LOOP

            wk_CODICE := recordItem.CODICE;

            r_tIdx_ADC_TIP_METOD_PAGAM_CLI(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_METOD_PAGAM_CLIENTE: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_METOD_PAGAM_CLI(wk_CODICE).METODO);

      END LOOP;

  -- LOAD in ARRAY ADC_TIP_FASE_VITA BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_FASE_VITA)
        LOOP

            wk_CODICE := recordItem.ID;

            r_tIdx_ADC_TIP_FASE_VITA(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_FASE_VITA: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_FASE_VITA(wk_CODICE).ID);

      END LOOP;

  -- LOAD in ARRAY ADC_TIP_SOTTOFASE_VITA BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TIP_SOTTOFASE_VITA)
        LOOP

            wk_CODICE := recordItem.ID;

            r_tIdx_ADC_TIP_SOTTOFASE_VITA(wk_CODICE):= recordItem;

            --dbms_output.Put_Line('AGGIUNTO in ADC_TIP_SOTTOFASE_VITA: -->' || wk_CODICE || '-->' || 'Valore: ' || r_tIdx_ADC_TIP_SOTTOFASE_VITA(wk_CODICE).ID);

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_COD_NAZIONALE_FIS BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_COD_NAZIONALE_FIS)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_COD_NAZ_FIS(wk_CODICE):= recordItem;

      END LOOP;

  -- LOAD in ARRAY ADC_TRANS_COD_NAZIONALE_FIS BEGIN -------------------------------

      wk_CODICE := NULL;
      FOR recordItem IN (select * from ADC_TRANS_CODICE_NAZIONE_PIVA)
        LOOP

            wk_CODICE := recordItem.VALORE || '-' || recordItem.SISTEMA_SORGENTE;

            r_tIdx_ADC_TRANS_COD_NAZ_PIVA(wk_CODICE):= recordItem;

      END LOOP;

  LOOP

        FETCH ADC_TX_USAGE_CUR  BULK COLLECT INTO  V_USAGE_TX LIMIT BLOCK_SIZE;

        V_USAGE_MESSAGE_BODY_ARRAY  := LOAD_USAGE_MESSAGES_ARRAY();
        V_MSG_PROPERTIES_TABLE      := DBMS_AQ.MESSAGE_PROPERTIES_ARRAY_T();
        V_MESSAGE_HANDLE_ARRAY      := DBMS_AQ.MSGID_ARRAY_T();


        FOR I IN 1..V_USAGE_TX.COUNT

            LOOP
                  ROW_COUNT := ROW_COUNT + 1;
                  V_USAGE_ROW := V_USAGE_TX(I);

                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE_RANGE  (JOB ID: ' || JOB_ID || ') - MANAGE RECORD #' ||ROW_COUNT||': ( ' ||  V_USAGE_ROW.ID   || ' )'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_SESSION,IS_DEBUG_ENABLED);

                  /* TRANSCODIFICA -------------------------------------------------------------------------------------------*/

                  IF (  V_USAGE_ROW.ID_TIPO_PROCESSO_INTERNO is NULL or  V_USAGE_ROW.SISTEMA_SORGENTE is NULL ) THEN
                      V_COD_TIPO_PROC_INTERNO := NULL;
                  ELSE
                    BEGIN
                       V_COD_TIPO_PROC_INTERNO := r_tIdx_ADC_TRANS_TIPO_PROC_INT(V_USAGE_ROW.ID_TIPO_PROCESSO_INTERNO || '-' || V_USAGE_ROW.SISTEMA_SORGENTE).COD_TIPO_PROC_INTERNO;
                       EXCEPTION WHEN OTHERS THEN
                       V_COD_TIPO_PROC_INTERNO := NULL;
                    END;
                  END IF;

                /* TRANS TIPO PROCESSO ALTRO INTERNO ---------------------------------------------*/

                IF (  V_USAGE_ROW.ID_TIPO_ALTRO_PROCESSO is NULL or  V_USAGE_ROW.SISTEMA_SORGENTE is NULL ) THEN
                      V_COD_TIPO_PROC_ALTROP := NULL;
                  ELSE
                    BEGIN
                       V_COD_TIPO_PROC_ALTROP := r_tIdx_ADC_TRANS_TIPO_PROC_INT(V_USAGE_ROW.ID_TIPO_ALTRO_PROCESSO || '-' || V_USAGE_ROW.SISTEMA_SORGENTE).COD_TIPO_PROC_INTERNO;
                       EXCEPTION WHEN OTHERS THEN
                       V_COD_TIPO_PROC_ALTROP := NULL;
                    END;
                  END IF;

                /* TRANS SISTEMA_PROCESSO_INTERNO ---------------------------------------------*/

                IF (  V_USAGE_ROW.SISTEMA_PROCESSO_INTERNO is NULL or  V_USAGE_ROW.SISTEMA_SORGENTE is NULL ) THEN
                      V_COD_SIS_PROC_INTERNO := NULL;
                  ELSE
                    BEGIN
