                --V_USAGE_MESSAGE_BODY.COD_SISTEMA_PROCESSO			:=V_USAGE_ROW.COD_SISTEMA_PROCESSO;
                --V_USAGE_MESSAGE_BODY.COD_SISTEMA_TRACCIATURA		:=V_USAGE_ROW.COD_SISTEMA_TRACCIATURA;
