                --V_USAGE_MESSAGE_BODY.PROVINCIA_LUOGO_EVENTO			  :=V_USAGE_ROW.PROVINCIA_LUOGO_EVENTO;
                --V_USAGE_MESSAGE_BODY.SA								            :=V_USAGE_ROW.SA;
                V_USAGE_MESSAGE_BODY.TELEFONO_RIC					        :=V_USAGE_ROW.TELEFONO_RIC;
                V_USAGE_MESSAGE_BODY.TELEFONO_CLI					        :=V_USAGE_ROW.TELEFONO_CLI;
                V_USAGE_MESSAGE_BODY.TELEFONO_MIT					        :=V_USAGE_ROW.TELEFONO_MIT;
                V_USAGE_MESSAGE_BODY.TELEFONO_DEST					      :=V_USAGE_ROW.TELEFONO_DEST;
                V_USAGE_MESSAGE_BODY.TELEFONO_INT					        :=V_USAGE_ROW.TELEFONO_INT;
                --V_USAGE_MESSAGE_BODY.TIPO_CLIENTE_PAGAMENTO			  :=V_USAGE_ROW.TIPO_CLIENTE_PAGAMENTO;
                --V_USAGE_MESSAGE_BODY.VENDITA						          :=V_USAGE_ROW.VENDITA;
                --V_USAGE_MESSAGE_BODY.ZONA_PTL						          :=V_USAGE_ROW.ZONA_PTL;
                --V_USAGE_MESSAGE_BODY.KEY_CODICE_PTL					      :=V_USAGE_ROW.KEY_CODICE_PTL;
                --V_USAGE_MESSAGE_BODY.REFE_DEST						        :=V_USAGE_ROW.REFE_DEST;
                --V_USAGE_MESSAGE_BODY.ID_CANALE						        :=V_USAGE_ROW.ID_CANALE;
                --V_USAGE_MESSAGE_BODY.ID_METODO_PAGAMENTO_CLIENTE	:=V_USAGE_ROW.ID_METODO_PAGAMENTO_CLIENTE;
                --V_USAGE_MESSAGE_BODY.ID_TIPO_CLIENTE_PAGAMENTO		:=V_USAGE_ROW.ID_TIPO_CLIENTE_PAGAMENTO;
                --V_USAGE_MESSAGE_BODY.NFEA_DETTAGLIO_A_CHIAMATA		:=V_USAGE_ROW.NFEA_DETTAGLIO_A_CHIAMATA;
                --V_USAGE_MESSAGE_BODY.NFEA_DETTAGLIO_B_CHIAMATA		:=V_USAGE_ROW.NFEA_DETTAGLIO_B_CHIAMATA;
               -- V_USAGE_MESSAGE_BODY.NFEA_SITO_CC					        :=V_USAGE_ROW.NFEA_SITO_CC;
                --V_USAGE_MESSAGE_BODY.NFEA_FORNITORE_CC				    :=V_USAGE_ROW.NFEA_FORNITORE_CC;
                --V_USAGE_MESSAGE_BODY.NFEA_TEAM						        :=V_USAGE_ROW.NFEA_TEAM;
                --V_USAGE_MESSAGE_BODY.NFEA_LOGIN						        :=V_USAGE_ROW.NFEA_LOGIN;
                --V_USAGE_MESSAGE_BODY.FRAZIONARIO_UP					      :=V_USAGE_ROW.FRAZIONARIO_UP;
                --V_USAGE_MESSAGE_BODY.NOME_UP						          :=V_USAGE_ROW.NOME_UP;
                --V_USAGE_MESSAGE_BODY.CITTA_LUOGO_EVENTO				    :=V_USAGE_ROW.CITTA_LUOGO_EVENTO;
                --V_USAGE_MESSAGE_BODY.ALT							            :=V_USAGE_ROW.ALT;
                --V_USAGE_MESSAGE_BODY.RAM							            :=V_USAGE_ROW.RAM;
                --V_USAGE_MESSAGE_BODY.CD								            :=V_USAGE_ROW.CD;
                --V_USAGE_MESSAGE_BODY.ZONA							            :=V_USAGE_ROW.ZONA;
                --V_USAGE_MESSAGE_BODY.TIPOLOGIA						        :=V_USAGE_ROW.TIPOLOGIA;
                --V_USAGE_MESSAGE_BODY.ID_TRACC_CORR					      :=V_USAGE_ROW.ID_TRACC_CORR;
                --V_USAGE_MESSAGE_BODY.TIPO_PROD_TRACC_CORR			    :=V_USAGE_ROW.TIPO_PROD_TRACC_CORR;
                --V_USAGE_MESSAGE_BODY.SIST_TRACC_CORR				      :=V_USAGE_ROW.SIST_TRACC_CORR;
                --V_USAGE_MESSAGE_BODY.COD_TIPO_PROD_TRACC_CORR		  :=V_USAGE_ROW.COD_TIPO_PROD_TRACC_CORR;
                --V_USAGE_MESSAGE_BODY.COD_SIST_TRACC_CORR			    :=V_USAGE_ROW.COD_SIST_TRACC_CORR;


                IF(V_USAGE_ROW.DATA_ORA_EVENTO IS NULL OR V_USAGE_ROW.FASE_CICLO_DI_VITA IS NULL OR V_USAGE_ROW.SISTEMA_SORGENTE IS NULL) THEN

                      V_USAGE_MESSAGE_BODY.SCARTATO := 1;
                      V_USAGE_MESSAGE_BODY.MOTIVO_SCARTO := 'DATA FASE E SISTEMA SONO OBBLIGATORI';
                      V_USAGE_ROW.MOTIVO_SCARTO := 'DATA FASE E SISTEMA NON PRESENTI';

                      INSERT  /* ADC_PKG_LOAD_USAGE_I24 */ INTO ADC_BAD_TX_USAGE_SAP_EM VALUES V_USAGE_ROW;

                      /*DBMS_AQ.ENQUEUE(
                          queue_name              => BAD_RECORD_QUEUE,
                          enqueue_options         => V_ENQUEUE_OPTIONS,
                          message_properties      => v_message_properties,
                          PAYLOAD                 => V_USAGE_MESSAGE_BODY,
                          MSGID                   => V_MESSAGE_HANDLE
                      );*/

                      BAD_MESSAGE_COUNT := BAD_MESSAGE_COUNT + 1;
                      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_SAP_USAGE_RANGE (JOB ID: ' || JOB_ID || ') - BAD RECORD ADDED INTO ADC_BAD_TX_USAGE_SAP_EM', ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_SESSION,IS_DEBUG_ENABLED);

                ELSIF(V_USAGE_ROW.ID_PROCESSO_INTERNO IS NULL AND V_USAGE_ROW.ID_ALTRO_PROCESSO IS NULL AND V_USAGE_ROW.ID_TRACCIATURA IS NULL) THEN

                      V_USAGE_MESSAGE_BODY.SCARTATO := 1;
                      V_USAGE_MESSAGE_BODY.MOTIVO_SCARTO := 'LE CHIAVI DELLO USAGE SONO OBBLIGATORI';
                      V_USAGE_ROW.MOTIVO_SCARTO := 'CHIAVI DELLO USAGE NON PRESENTI';

                      INSERT  /* ADC_PKG_LOAD_USAGE_I25 */ INTO ADC_BAD_TX_USAGE_SAP_EM VALUES V_USAGE_ROW;

                      /*DBMS_AQ.ENQUEUE(
                          queue_name              => BAD_RECORD_QUEUE,
                          enqueue_options         => V_ENQUEUE_OPTIONS,
                          message_properties      => v_message_properties,
                          PAYLOAD                 => V_USAGE_MESSAGE_BODY,
                          MSGID                   => V_MESSAGE_HANDLE
                      );*/

                      BAD_MESSAGE_COUNT := BAD_MESSAGE_COUNT + 1;
                      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_SAP_USAGE_RANGE (JOB ID: ' || JOB_ID || ') - BAD RECORD ADDED INTO ADC_BAD_TX_USAGE_SAP_EM', ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_SESSION,IS_DEBUG_ENABLED);

                ELSE
                      V_USAGE_MESSAGE_BODY_ARRAY.EXTEND();
                      V_USAGE_MESSAGE_BODY_ARRAY(V_USAGE_MESSAGE_BODY_ARRAY.LAST) := V_USAGE_MESSAGE_BODY;

                      --LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_SAP_USAGE_RANGE (NOME: ' || V_USAGE_MESSAGE_BODY.NOME_CLI ||')',  ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_SESSION,IS_DEBUG_ENABLED);

                      V_MESSAGE_PROPERTIES.USER_PROPERTY := SYS.ANYDATA.CONVERTNUMBER(V_USAGE_MESSAGE_BODY.ID_FLUSSO);
                      V_MSG_PROPERTIES_TABLE.EXTEND();
                      V_MSG_PROPERTIES_TABLE(V_MSG_PROPERTIES_TABLE.LAST) := V_MESSAGE_PROPERTIES;


                      -- Q_END := DBMS_UTILITY.GET_TIME;

                      -- MESSAGE_COUNT := MESSAGE_COUNT + 1;

                      --LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE - ENQUEUED MESSAGE ( ' || V_MESSAGE_HANDLE || ' ) INTO ' || IN_QUEUE  || '(elapsed:'|| (Q_end - Q_start)/100 ||' s)', ADC_PKG_COMMON.DEBUG_LEVEL, INPUT_ID_SESSION);

                       /* DUPLICAZIONE RECORD NEL CASO DI VENDITA NULL DA OMP ------------------------------------------------------
                      IF(V_USAGE_ROW.VENDITA IS NULL AND V_USAGE_ROW.CANALE = 'OMP' AND V_USAGE_ROW.FASE_CICLO_DI_VITA = 'ACS') THEN



                          V_DUP_USAGE_MESSAGE_BODY                            :=  LOAD_USAGE_MESSAGE_TYPE();
                          V_DUP_USAGE_MESSAGE_BODY                            :=  V_USAGE_MESSAGE_BODY;
                          V_DUP_USAGE_MESSAGE_BODY.FASE_CICLO_DI_VITA				  :=  'ACV';
                          V_DUP_USAGE_MESSAGE_BODY.SOTTO_FASE_CICLO_DI_VITA		:=  'VND';
                          V_DUP_USAGE_MESSAGE_BODY.ID	:= NULL;

                          V_USAGE_MESSAGE_BODY_ARRAY.EXTEND();
                          V_USAGE_MESSAGE_BODY_ARRAY(V_USAGE_MESSAGE_BODY_ARRAY.LAST) := V_DUP_USAGE_MESSAGE_BODY;

                          V_MESSAGE_PROPERTIES.USER_PROPERTY := SYS.ANYDATA.CONVERTNUMBER(V_DUP_USAGE_MESSAGE_BODY.ID_FLUSSO);
                          V_MSG_PROPERTIES_TABLE.EXTEND();
                          V_MSG_PROPERTIES_TABLE(V_MSG_PROPERTIES_TABLE.LAST) := V_MESSAGE_PROPERTIES;


                          --LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_USAGE - CREATED FAKE RECORD FOR FLAG VENDITA, ENQUEUED MESSAGE ('|| V_MESSAGE_HANDLE || ') INTO ' || IN_QUEUE , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_SESSION);

                      END IF;
                      */

                END IF;

                DELETE /* ADC_PKG_LOAD_USAGE_D40 */ FROM ADC_TX_USAGE_SAP_EM WHERE ID = V_USAGE_ROW.ID AND ID_FLUSSO = V_USAGE_ROW.ID_FLUSSO;

                END LOOP;

                Q_START := DBMS_UTILITY.GET_TIME;

                if(V_USAGE_MESSAGE_BODY_ARRAY.COUNT > 0) THEN

                      v_enqueued_cnt := DBMS_AQ.ENQUEUE_ARRAY(
                                                QUEUE_NAME               => IN_QUEUE,
                                                ENQUEUE_OPTIONS          => V_ENQUEUE_OPTIONS,
                                                ARRAY_SIZE               => V_USAGE_MESSAGE_BODY_ARRAY.COUNT,
                                                MESSAGE_PROPERTIES_ARRAY => V_MSG_PROPERTIES_TABLE,
                                                PAYLOAD_ARRAY            => V_USAGE_MESSAGE_BODY_ARRAY,
                                                msgid_array              => V_MESSAGE_HANDLE_ARRAY
                                        );

                END IF;
                Q_END := DBMS_UTILITY.GET_TIME;
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_SAP_USAGE_RANGE  (JOB ID: ' || JOB_ID || ') - ENQUEUED  '||  V_ENQUEUED_CNT  || ' MESSAGES INTO ' || IN_QUEUE  || '(elapsed:'|| (Q_END - Q_START)/100 ||' s)', ADC_PKG_COMMON.DEBUG_LEVEL, INPUT_ID_SESSION,IS_DEBUG_ENABLED);
                MESSAGE_COUNT := MESSAGE_COUNT + V_ENQUEUED_CNT;

                COMMIT; /* ACCODO I BLOCK_SIZE NUM RECORD */

                COMMIT_COUNT := COMMIT_COUNT + 1;

                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_SAP_USAGE_RANGE (JOB ID: ' || JOB_ID || ') - COMMIT #' || COMMIT_COUNT || ' EXECUTED. READ: ' || ROW_COUNT
                                                                                                || ', OK MSG IN ' || IN_QUEUE  ||':' || MESSAGE_COUNT
                                                                                                || ', BAD MSG IN ADC_BAD_TX_USAGE_SAP_EM :' || BAD_MESSAGE_COUNT
                                                                                                , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_SESSION,IS_DEBUG_ENABLED);
            EXIT WHEN V_USAGE_TX.COUNT < BLOCK_SIZE;

        END LOOP;

    CLOSE ADC_TX_USAGE_CUR;
    L_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ENQUEUE_SAP_USAGE_RANGE (JOB ID: ' || JOB_ID || ') - END (elapsed: '|| (L_END - L_START)/100 ||' s): READ: ' || ROW_COUNT
                                                                                                || ', OK MSG IN ' || IN_QUEUE ||':' || MESSAGE_COUNT
                                                                                                || ', BAD MSG IN ADC_BAD_TX_USAGE_SAP_EM:' || BAD_MESSAGE_COUNT
                                                                                                , ADC_PKG_COMMON.INFO_LEVEL,INPUT_ID_SESSION);

    DBMS_OUTPUT.PUT_LINE('PROCEDURE: ENQUEUE_SAP_USAGE_RANGE (JOB ID: ' || JOB_ID || ' ) - END (elapsed:'|| (L_END - L_START)/100 ||' s): READ: ' || ROW_COUNT
                                                                                                || ', OK MSG IN' || IN_QUEUE ||':' || MESSAGE_COUNT
                                                                                                || ', BAD MSG IN ADC_BAD_TX_USAGE_SAP_EM:' || BAD_MESSAGE_COUNT);
    BEGIN
      OPEN SESSION_ENQUEUERS_CUR;
          LOOP
              FETCH SESSION_ENQUEUERS_CUR INTO ACTIVE_ENQUEUER_NUMBER;
              EXIT WHEN SESSION_ENQUEUERS_CUR%NOTFOUND;

              UPDATE /* ADC_PKG_LOAD_USAGE_U38 */ ADC_TX_JOBID_SESSION SET ACTIVE_ENQUEUER=ACTIVE_ENQUEUER_NUMBER-1 WHERE CURRENT OF SESSION_ENQUEUERS_CUR;
          END LOOP;
      CLOSE SESSION_ENQUEUERS_CUR;
    EXCEPTION WHEN OTHERS THEN
      CLOSE SESSION_ENQUEUERS_CUR;
    END;
END;


 PROCEDURE DEQUEUE_USAGE_TEST(JOB_ID VARCHAR2, IN_QUEUE VARCHAR2, V_SCHEDULING_INTERVAL NUMBER, MESSAGE OUT VARCHAR2,ESITO OUT VARCHAR2) IS

    -- not change
    msgid                     RAW (16);

    V_DEQUEUE_OPTIONS         DBMS_AQ.DEQUEUE_OPTIONS_T;
    V_MESSAGE_PROPERTIES      DBMS_AQ.MESSAGE_PROPERTIES_T;
    V_USAGE_MESSAGE_BODY      LOAD_USAGE_MESSAGE_TYPE;

    DATIAGGIUNTIVI_ROW DATIAGGIUNTIVI_TYPE;
    DATIAGGIUNTIVI DATIAGGIUNTIVI_TABLE;

    V_CHIAVEUSAGERECORD CHIAVEUSAGE_TYPE;
    V_CHIAVEUSAGELIST CHIAVEUSAGE_TABLE;

    V_ANAG_RIC_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_CLI_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_MIT_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_DEST_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_INT_RECORD DATIANAGRAFICI_TYPE;
    V_DATIANAGRAFICI  DATIANAGRAFICI_TABLE;

    V_SERVIZIACCESSORI SERVIZIACCESSORI_TABLE;

    V_CODICEPRODOTTOSERVIZIO  CODICEPRODOTTOSERVIZIO_TYPE;
    V_CODICEPRODOTTOSERVIZI   CODICEPRODOTTOSERVIZIO_TABLE;

    ESITOOPERAZIONE           VARCHAR2(100);
    INSERTED_ID_USAGE         VARCHAR2(100);
    LOGRESULT                 NUMBER;
    L_START                   NUMBER;
    L_END                     NUMBER;
    GLOBAL_START              NUMBER;
    GLOBAL_END                NUMBER;
    INPUT_ID_FLUSSO           NUMBER;

    DEQUEUED_MESSAGE            NUMBER;

    no_messages               exception;
    PRAGMA EXCEPTION_INIT (NO_MESSAGES, -25228);

  BEGIN
    --  V_DEQUEUE_OPTIONS.CONSUMER_NAME := 'AG_TT_LOAD_USAGE';
     V_DEQUEUE_OPTIONS.wait          := DBMS_AQ.NO_WAIT;
     V_DEQUEUE_OPTIONS.visibility    := dbms_aq.on_commit;
    --  V_DEQUEUE_OPTIONS.navigation    := DBMS_AQ.FIRST_MESSAGE;

    --LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_TEST (JOB ID: ' || JOB_ID || ' )  - BEGIN'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO);
    GLOBAL_START := DBMS_UTILITY.GET_TIME ;  -- Start Time
    DEQUEUED_MESSAGE :=0;

    LOOP
          L_START := DBMS_UTILITY.GET_TIME ;  -- Start Time

          DBMS_AQ.DEQUEUE (
                         queue_name           => IN_QUEUE,
                         dequeue_options      => V_DEQUEUE_OPTIONS,
                         message_properties   => V_MESSAGE_PROPERTIES,
                         PAYLOAD              => V_USAGE_MESSAGE_BODY,
                         MSGID                => MSGID);

          --DBMS_LOCK.SLEEP (1);

          --LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE (JOB ID: ' || JOB_ID || ' ) (elapsed:'|| (L_END - L_START)/100 ||' s)'  , ADC_PKG_COMMON.ERROR_LEVEL,INPUT_ID_FLUSSO);
          DEQUEUED_MESSAGE := DEQUEUED_MESSAGE +1;

  END LOOP;
  COMMIT;
  EXCEPTION
    WHEN no_messages THEN
        DBMS_OUTPUT.PUT_LINE ('No more messages for RED');
        GLOBAL_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_TEST (JOB ID: ' || JOB_ID || ') - END (NO MORE MESSAGES) - Messages: ' || DEQUEUED_MESSAGE || '(elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)'  , ADC_PKG_COMMON.ERROR_LEVEL,INPUT_ID_FLUSSO);
        COMMIT;
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE ('ERROR ' || SQLERRM);
        GLOBAL_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_TEST (JOB ID: ' || SQLERRM || '(elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)'  , ADC_PKG_COMMON.ERROR_LEVEL,INPUT_ID_FLUSSO);
        ROLLBACK;
        raise;
END;






PROCEDURE DEQUEUE_USAGE(JOB_ID VARCHAR2, IN_QUEUE VARCHAR2, ERROR_QUEUE VARCHAR2, V_SCHEDULING_INTERVAL NUMBER, MESSAGE OUT VARCHAR2,ESITO OUT VARCHAR2) IS

    -- not change
    msgid                     RAW (16);

    DATIAGGIUNTIVI_ROW DATIAGGIUNTIVI_TYPE;
    V_DATIAGGIUNTIVI_MSGTYPE DATIAGGIUNTIVI_TYPE;
    V_DATIAGGIUNTIVI_NUMERO_TENT_C DATIAGGIUNTIVI_TYPE;
    V_DATIAGGIUNTIVI_QUALIFICA DATIAGGIUNTIVI_TYPE;
    V_DATIAGGIUNTIVI DATIAGGIUNTIVI_TABLE;

    V_CHIAVEUSAGERECORD CHIAVEUSAGE_TYPE;
    V_CHIAVEUSAGELIST CHIAVEUSAGE_TABLE;

    V_ANAG_RIC_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_CLI_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_MIT_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_DEST_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_INT_RECORD DATIANAGRAFICI_TYPE;
    V_DATIANAGRAFICI  DATIANAGRAFICI_TABLE;

    V_SERVIZIACCESSORI SERVIZIACCESSORI_TABLE;

    V_CODICEPRODOTTOSERVIZIO        CODICEPRODOTTOSERVIZIO_TYPE;
    V_CODICEPRODOTTOSERVIZI         CODICEPRODOTTOSERVIZIO_TABLE;

    ESITOOPERAZIONE                 VARCHAR2(100);
    INSERTED_ID_USAGE               VARCHAR2(100);
    LOGRESULT                       NUMBER;
    L_START                         NUMBER;
    L_END                           NUMBER;
    GLOBAL_START                    NUMBER;
    GLOBAL_END                      NUMBER;
    INPUT_ID_FLUSSO                 NUMBER;

    DEQUEUED_MESSAGE                NUMBER;
    CURRENT_DEQUEUED_MESSAGE        NUMBER;
    DEQUEUE_BLOCK_SIZE              NUMBER;

    no_messages                     exception;


    V_USAGE_MESSAGE_BODY            LOAD_USAGE_MESSAGE_TYPE;

    V_DEQUEUE_OPTIONS               DBMS_AQ.DEQUEUE_OPTIONS_T;
    V_MESSAGE_PROPERTIES            DBMS_AQ.MESSAGE_PROPERTIES_T;
    V_MESSAGE_HANDLE_ARRAY          DBMS_AQ.MSGID_ARRAY_T;
    V_MSG_PROPERTIES_TABLE          DBMS_AQ.MESSAGE_PROPERTIES_ARRAY_T := DBMS_AQ.MESSAGE_PROPERTIES_ARRAY_T();
    V_USAGE_MESSAGE_BODY_ARRAY      LOAD_USAGE_MESSAGES_ARRAY;
    RETVAL                          PLS_INTEGER;
    V_VIRTUAL_QUEUE                 VARCHAR(255);
    PO_T                            DBMS_AQADM.AQ$_PURGE_OPTIONS_T;
    V_ERR_ENQUEUE_OPTIONS           DBMS_AQ.ENQUEUE_OPTIONS_T;
    V_ERR_MESSAGE_PROPERTIES        DBMS_AQ.MESSAGE_PROPERTIES_T;
    V_MESSAGE_HANDLE                RAW(16);
    QUEUE_TABLE                     VARCHAR2(255);

    PRAGMA EXCEPTION_INIT (NO_MESSAGES, -25228);

    IS_DEBUG_ENABLED                BOOLEAN;
    IS_DIAGNOSTIC_ENABLED           BOOLEAN;

    /*Gestione 4020*/
    retryCount NUMBER;
    maxRetry NUMBER;
    sleep_sec NUMBER;



    BEGIN
        retryCount:= 0;

        IS_DIAGNOSTIC_ENABLED  := ADC_PKG_COMMON.IS_LEVEL_ENABLED(ADC_PKG_LOAD_USAGE.DIAGNOSTIC_LOGGER_NAME, ADC_PKG_COMMON.INFO_LEVEL);
        IS_DEBUG_ENABLED := ADC_PKG_COMMON.IS_LEVEL_ENABLED(LOGGER_NAME, ADC_PKG_COMMON.DEBUG_LEVEL);

        --  V_DEQUEUE_OPTIONS.CONSUMER_NAME := 'AG_TT_LOAD_USAGE';
        V_DEQUEUE_OPTIONS.wait          := DBMS_AQ.NO_WAIT;
        V_DEQUEUE_OPTIONS.VISIBILITY    := DBMS_AQ.ON_COMMIT;
        --  V_DEQUEUE_OPTIONS.navigation    := DBMS_AQ.FIRST_MESSAGE;

        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ')  - BEGIN'  , ADC_PKG_COMMON.INFO_LEVEL,'');
        GLOBAL_START := DBMS_UTILITY.GET_TIME ;  -- Start Time

        V_VIRTUAL_QUEUE := SUBSTR(IN_QUEUE  ,3,LENGTH(IN_QUEUE) -5);
        BEGIN
            SELECT PARAMETER_VALUE INTO DEQUEUE_BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='DEQUEUE_BLOCK_SIZE' AND ROWNUM = 1;
            EXCEPTION WHEN NO_DATA_FOUND THEN
            SELECT PARAMETER_VALUE INTO DEQUEUE_BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='DEQUEUE_BLOCK_SIZE' AND ROWNUM = 1;
        END;

        DEQUEUED_MESSAGE          :=0;
        CURRENT_DEQUEUED_MESSAGE  :=0;

        LOOP
            L_START := DBMS_UTILITY.GET_TIME ;  -- Start Time

            DBMS_AQ.DEQUEUE(
                         queue_name           => IN_QUEUE,
                         dequeue_options      => V_DEQUEUE_OPTIONS,
                         message_properties   => V_MESSAGE_PROPERTIES,
                         PAYLOAD              => V_USAGE_MESSAGE_BODY,
                         MSGID                => MSGID);

            DEQUEUED_MESSAGE := DEQUEUED_MESSAGE + 1;
            CURRENT_DEQUEUED_MESSAGE := CURRENT_DEQUEUED_MESSAGE +1;

            V_DATIAGGIUNTIVI.DELETE();
            V_CODICEPRODOTTOSERVIZI.DELETE();

            INPUT_ID_FLUSSO :=  SYS.ANYDATA.accessNumber(V_MESSAGE_PROPERTIES.user_property);

            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ' ) - Scodato messaggio (' ||  msgid || ')'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);

            --DBMS_OUTPUT.PUT_LINE('RECEIVE: -->' ||msgid || ':' || V_USAGE_MESSAGE_BODY.ID);

            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') - Creazione oggetti per gestione dello USAGE (' ||  V_USAGE_MESSAGE_BODY.ID || ')'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);

          /* GESTIONE CHIAVI */
          V_CHIAVEUSAGERECORD.IDPROCESSOINTERNO 		    := V_USAGE_MESSAGE_BODY.ID_PROCESSO_INTERNO;
          V_CHIAVEUSAGERECORD.IDTIPOPROCESSOINTERNO 	  := V_USAGE_MESSAGE_BODY.ID_TIPO_PROCESSO_INTERNO;
          V_CHIAVEUSAGERECORD.SISTEMAPROCESSOINTERNO 	  := V_USAGE_MESSAGE_BODY.SISTEMA_PROCESSO_INTERNO;
          V_CHIAVEUSAGERECORD.IDALTROPROCESSO 		      := V_USAGE_MESSAGE_BODY.ID_ALTRO_PROCESSO;
          V_CHIAVEUSAGERECORD.ALTROPROCESSOPRECEDENTE   := V_USAGE_MESSAGE_BODY.ALTRO_PROCESSO_PRECEDENTE;
          V_CHIAVEUSAGERECORD.IDTIPOALTROPROCESSO 	    := V_USAGE_MESSAGE_BODY.ID_TIPO_ALTRO_PROCESSO;
          V_CHIAVEUSAGERECORD.SISTEMAALTROPROCESSO 	    := V_USAGE_MESSAGE_BODY.SISTEMA_ALTRO_PROCESSO;
          V_CHIAVEUSAGERECORD.CODTIPOPROCINTERNO        := V_USAGE_MESSAGE_BODY.COD_TIPO_PROCESSO;
          V_CHIAVEUSAGERECORD.CODSISPROCINTERNO         := V_USAGE_MESSAGE_BODY.COD_SISTEMA_PROCESSO;
          V_CHIAVEUSAGERECORD.CODSISTEMA                := V_USAGE_MESSAGE_BODY.COD_SISTEMA_ALTROP;
          V_CHIAVEUSAGERECORD.CODALTROPROC              := V_USAGE_MESSAGE_BODY.COD_TIPO_ALTROP;
          V_CHIAVEUSAGERECORD.CANALE                    := V_USAGE_MESSAGE_BODY.CANALE;

          V_CHIAVEUSAGELIST(1):= V_CHIAVEUSAGERECORD;

          /* GESTIONE ANAGRAFICHE */

          V_ANAG_RIC_RECORD.TIPORUOLO 	:=	'RICHIEDENTE';

          V_ANAG_RIC_RECORD.CF 	:=	V_USAGE_MESSAGE_BODY.CODICE_FISCALE_RIC;
          V_ANAG_RIC_RECORD.CNF 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_RIC;
          V_ANAG_RIC_RECORD.PIVA 	:=	V_USAGE_MESSAGE_BODY.PIVA_RIC;
          V_ANAG_RIC_RECORD.CNPIVA 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_RIC;
          V_ANAG_RIC_RECORD.SISTEMACODICENONFISCALE	:=	V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISCALE_RIC;
          V_ANAG_RIC_RECORD.CODICECLIENTENONFISCALE	:=	V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISCALE_RIC;
          V_ANAG_RIC_RECORD.NOME 	:=	V_USAGE_MESSAGE_BODY.NOME_RIC;
          V_ANAG_RIC_RECORD.COGNOME 	:=	V_USAGE_MESSAGE_BODY.COGNOME_RIC;
          V_ANAG_RIC_RECORD.PARTICELLATOPONOMASTICA	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_RIC;
          V_ANAG_RIC_RECORD.INDIRIZZO 	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_RIC;
          V_ANAG_RIC_RECORD.NUMEROCIVICO 	:=	V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_RIC;
          V_ANAG_RIC_RECORD.CAP 	:=	V_USAGE_MESSAGE_BODY.CAP_RIC;
          V_ANAG_RIC_RECORD.COMUNE 	:=	V_USAGE_MESSAGE_BODY.COMUNE_RIC;
          V_ANAG_RIC_RECORD.PROVINCIA 	:=	V_USAGE_MESSAGE_BODY.PROVINCIA_RIC;
          V_ANAG_RIC_RECORD.STATO	:=	V_USAGE_MESSAGE_BODY.STATO_RIC;
          V_ANAG_RIC_RECORD.TELEFONO 	:=	V_USAGE_MESSAGE_BODY.TELEFONO_RIC;
          V_ANAG_RIC_RECORD.mail 	:=	V_USAGE_MESSAGE_BODY.MAIL_RIC;
          V_ANAG_RIC_RECORD.codiceNazionaleFis :=	V_USAGE_MESSAGE_BODY.COD_NAZIONALE_FIS_RIC;
          V_ANAG_RIC_RECORD.codiceNazionalePiva :=	V_USAGE_MESSAGE_BODY.CN_PIVA_RIC;


          V_ANAG_CLI_RECORD.tipoRuolo 	:=	'CLIENTE';

          V_ANAG_CLI_RECORD.CF 	:=	V_USAGE_MESSAGE_BODY.CODICE_FISCALE_CLI;
          V_ANAG_CLI_RECORD.cnf 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_CLI;
          V_ANAG_CLI_RECORD.PIVA 	:=	V_USAGE_MESSAGE_BODY.PIVA_CLI;
          V_ANAG_CLI_RECORD.cnPiva 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_CLI;
          V_ANAG_CLI_RECORD.SISTEMACODICENONFISCALE	:=	V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISCALE_CLI;
          V_ANAG_CLI_RECORD.codiceClienteNonFiscale	:=	V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISCALE_CLI;
          V_ANAG_CLI_RECORD.NOME 	:=	V_USAGE_MESSAGE_BODY.NOME_CLI;
          V_ANAG_CLI_RECORD.cognome 	:=	V_USAGE_MESSAGE_BODY.COGNOME_CLI;
          V_ANAG_CLI_RECORD.PARTICELLATOPONOMASTICA	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_CLI;
          V_ANAG_CLI_RECORD.indirizzo 	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_CLI;
          V_ANAG_CLI_RECORD.NUMEROCIVICO 	:=	V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_CLI;
          V_ANAG_CLI_RECORD.CAP 	:=	V_USAGE_MESSAGE_BODY.CAP_CLI;
          V_ANAG_CLI_RECORD.COMUNE 	:=	V_USAGE_MESSAGE_BODY.COMUNE_CLI;
          V_ANAG_CLI_RECORD.provincia 	:=	V_USAGE_MESSAGE_BODY.PROVINCIA_CLI;
          V_ANAG_CLI_RECORD.STATO	:=	V_USAGE_MESSAGE_BODY.STATO_CLI;
          V_ANAG_CLI_RECORD.TELEFONO 	:=	V_USAGE_MESSAGE_BODY.TELEFONO_CLI;
          V_ANAG_CLI_RECORD.mail 	:=	V_USAGE_MESSAGE_BODY.MAIL_CLI;
          V_ANAG_CLI_RECORD.codiceNazionaleFis :=	V_USAGE_MESSAGE_BODY.COD_NAZIONALE_FIS_CLI;
          V_ANAG_CLI_RECORD.codiceNazionalePiva :=	V_USAGE_MESSAGE_BODY.CN_PIVA_CLI;

          V_ANAG_MIT_RECORD.tipoRuolo 	:=	'MITTENTE';
          V_ANAG_MIT_RECORD.CF 	:=	V_USAGE_MESSAGE_BODY.CODICE_FISCALE_MIT;
          V_ANAG_MIT_RECORD.cnf 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_MIT;
          V_ANAG_MIT_RECORD.PIVA 	:=	V_USAGE_MESSAGE_BODY.PIVA_MIT;
          V_ANAG_MIT_RECORD.cnPiva 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_MIT;
          V_ANAG_MIT_RECORD.SISTEMACODICENONFISCALE	:=	V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISCALE_MIT;
          V_ANAG_MIT_RECORD.codiceClienteNonFiscale	:=	V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISCALE_MIT;
          V_ANAG_MIT_RECORD.NOME 	:=	V_USAGE_MESSAGE_BODY.NOME_MIT;
          V_ANAG_MIT_RECORD.COGNOME 	:=	V_USAGE_MESSAGE_BODY.COGNOME_MIT;
          V_ANAG_MIT_RECORD.particellaToponomastica	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_MIT;
          V_ANAG_MIT_RECORD.INDIRIZZO 	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_MIT;
          V_ANAG_MIT_RECORD.numeroCivico 	:=	V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_MIT;
          V_ANAG_MIT_RECORD.CAP 	:=	V_USAGE_MESSAGE_BODY.CAP_MIT;
          V_ANAG_MIT_RECORD.comune 	:=	V_USAGE_MESSAGE_BODY.COMUNE_MIT;
          V_ANAG_MIT_RECORD.PROVINCIA 	:=	V_USAGE_MESSAGE_BODY.PROVINCIA_MIT;
          V_ANAG_MIT_RECORD.STATO	:=	V_USAGE_MESSAGE_BODY.STATO_MIT;
          V_ANAG_MIT_RECORD.TELEFONO 	:=	V_USAGE_MESSAGE_BODY.TELEFONO_MIT;
          V_ANAG_MIT_RECORD.mail 	:=	V_USAGE_MESSAGE_BODY.MAIL_MIT;
          V_ANAG_MIT_RECORD.codiceNazionaleFis :=	V_USAGE_MESSAGE_BODY.COD_NAZIONALE_FIS_MIT;
          V_ANAG_MIT_RECORD.codiceNazionalePiva :=	V_USAGE_MESSAGE_BODY.CN_PIVA_MIT;


          V_ANAG_DEST_RECORD.tipoRuolo 	:=	'DESTINATARIO';
          V_ANAG_DEST_RECORD.CF 	:=	V_USAGE_MESSAGE_BODY.CODICE_FISCALE_DEST;
          V_ANAG_DEST_RECORD.CNF 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_DEST;
          V_ANAG_DEST_RECORD.PIVA 	:=	V_USAGE_MESSAGE_BODY.PIVA_DEST;
          V_ANAG_DEST_RECORD.cnPiva 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_DEST;
          V_ANAG_DEST_RECORD.SISTEMACODICENONFISCALE	:=	V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISC_DEST;
          V_ANAG_DEST_RECORD.CODICECLIENTENONFISCALE	:=	V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISC_DEST;
          V_ANAG_DEST_RECORD.NOME 	:=	V_USAGE_MESSAGE_BODY.NOME_DEST;
          V_ANAG_DEST_RECORD.COGNOME 	:=	V_USAGE_MESSAGE_BODY.COGNOME_DEST;
          V_ANAG_DEST_RECORD.particellaToponomastica	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_DEST;
          V_ANAG_DEST_RECORD.INDIRIZZO 	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_DEST;
          V_ANAG_DEST_RECORD.numeroCivico 	:=	V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_DEST;
          V_ANAG_DEST_RECORD.cap 	:=	V_USAGE_MESSAGE_BODY.CAP_DEST;
          V_ANAG_DEST_RECORD.COMUNE 	:=	V_USAGE_MESSAGE_BODY.COMUNE_DEST;
          V_ANAG_DEST_RECORD.provincia 	:=	V_USAGE_MESSAGE_BODY.PROVINCIA_DEST;
          V_ANAG_DEST_RECORD.STATO	:=	V_USAGE_MESSAGE_BODY.STATO_DEST;
          V_ANAG_DEST_RECORD.TELEFONO 	:=	V_USAGE_MESSAGE_BODY.TELEFONO_DEST;
          V_ANAG_DEST_RECORD.mail 	:=	V_USAGE_MESSAGE_BODY.MAIL_DEST;
          V_ANAG_DEST_RECORD.codiceNazionaleFis :=	V_USAGE_MESSAGE_BODY.COD_NAZIONALE_FIS_DEST;
          V_ANAG_DEST_RECORD.codiceNazionalePiva :=	V_USAGE_MESSAGE_BODY.CN_PIVA_DEST;


          V_ANAG_INT_RECORD.tipoRuolo 	:=	'INTERMEDIARIO';
          V_ANAG_INT_RECORD.CF 	:=	V_USAGE_MESSAGE_BODY.CODICE_FISCALE_INT;
          V_ANAG_INT_RECORD.cnf 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_INT;
          V_ANAG_INT_RECORD.PIVA 	:=	V_USAGE_MESSAGE_BODY.PIVA_INT;
          V_ANAG_INT_RECORD.cnPiva 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_INT;
          V_ANAG_INT_RECORD.SISTEMACODICENONFISCALE	:=	V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISC_INT;
          V_ANAG_INT_RECORD.CODICECLIENTENONFISCALE	:=	V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISC_INT;
          V_ANAG_INT_RECORD.NOME 	:=	V_USAGE_MESSAGE_BODY.NOME_INT;
          V_ANAG_INT_RECORD.COGNOME 	:=	V_USAGE_MESSAGE_BODY.COGNOME_INT;
          V_ANAG_INT_RECORD.particellaToponomastica	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_INT;
          V_ANAG_INT_RECORD.indirizzo 	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_INT;
          V_ANAG_INT_RECORD.NUMEROCIVICO 	:=	V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_INT;
          V_ANAG_INT_RECORD.CAP 	:=	V_USAGE_MESSAGE_BODY.CAP_INT;
          V_ANAG_INT_RECORD.comune 	:=	V_USAGE_MESSAGE_BODY.COMUNE_INT;
          V_ANAG_INT_RECORD.PROVINCIA 	:=	V_USAGE_MESSAGE_BODY.PROVINCIA_INT;
          V_ANAG_INT_RECORD.stato	:=	V_USAGE_MESSAGE_BODY.STATO_INT;
          V_ANAG_INT_RECORD.TELEFONO 	:=	V_USAGE_MESSAGE_BODY.TELEFONO_INT;
          V_ANAG_INT_RECORD.MAIL 	:=	V_USAGE_MESSAGE_BODY.MAIL_INT;
          V_ANAG_INT_RECORD.codiceNazionaleFis :=	V_USAGE_MESSAGE_BODY.COD_NAZIONALE_FIS_INT;
          V_ANAG_INT_RECORD.codiceNazionalePiva :=	V_USAGE_MESSAGE_BODY.CN_PIVA_INT;

          V_DATIANAGRAFICI(1):= V_ANAG_RIC_RECORD;
          V_DATIANAGRAFICI(2):= V_ANAG_CLI_RECORD;
          V_DATIANAGRAFICI(3):= V_ANAG_MIT_RECORD;
          V_DATIANAGRAFICI(4):= V_ANAG_DEST_RECORD;
          V_DATIANAGRAFICI(5):= V_ANAG_INT_RECORD;

          --GETSERVIZIACCESSORI(IS_DEBUG_ENABLED, msgid, V_USAGE_MESSAGE_BODY.SA, V_USAGE_MESSAGE_BODY.SISTEMA_SORGENTE, V_SERVIZIACCESSORI);
          GETSERVIZIACCESSORI(IS_DEBUG_ENABLED, V_USAGE_MESSAGE_BODY.SA, V_USAGE_MESSAGE_BODY.SISTEMA_SORGENTE, msgid, V_SERVIZIACCESSORI);

          V_CODICEPRODOTTOSERVIZIO.CODICE   :=  V_USAGE_MESSAGE_BODY.CODICE_PRODOTTO_SERVIZIO;
          V_CODICEPRODOTTOSERVIZIO.codiceProdottoServizioTrans  :=  V_USAGE_MESSAGE_BODY.ID_PROD_SERVIZIO;

          V_CODICEPRODOTTOSERVIZI(1)        :=  V_CODICEPRODOTTOSERVIZIO;

          /* GESTIONE INSERIMENTO NUOVI CAMPI MSGTYPE; NUMERO_TENTATIVI_CONS; QUALIFICA DEL TRACCIATO TT */

          IF(V_USAGE_MESSAGE_BODY.MSGTYPE IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_MSGTYPE.VALORE := V_USAGE_MESSAGE_BODY.MSGTYPE;
                V_DATIAGGIUNTIVI_MSGTYPE.chiave := 'MSGTYPE';
                V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_MSGTYPE;
          END IF;

          IF(V_USAGE_MESSAGE_BODY.NUMERO_TENTATIVI_CONS IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_NUMERO_TENT_C.VALORE := V_USAGE_MESSAGE_BODY.NUMERO_TENTATIVI_CONS;
                V_DATIAGGIUNTIVI_NUMERO_TENT_C.chiave := 'NUMERO_TENTATIVI_CONS';

                IF(V_USAGE_MESSAGE_BODY.MSGTYPE IS NOT NULL) THEN
                    V_DATIAGGIUNTIVI(2) := V_DATIAGGIUNTIVI_NUMERO_TENT_C;
                ELSE
                    V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_NUMERO_TENT_C;
                END IF;

          END IF;

          IF(V_USAGE_MESSAGE_BODY.QUALIFICA IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_QUALIFICA.VALORE := V_USAGE_MESSAGE_BODY.QUALIFICA;
                V_DATIAGGIUNTIVI_QUALIFICA.chiave := 'QUALIFICA';

                IF(V_USAGE_MESSAGE_BODY.MSGTYPE IS NOT NULL AND V_USAGE_MESSAGE_BODY.NUMERO_TENTATIVI_CONS IS NOT NULL) THEN
                    V_DATIAGGIUNTIVI(3) := V_DATIAGGIUNTIVI_QUALIFICA;
                ELSE

                      IF((V_USAGE_MESSAGE_BODY.MSGTYPE IS NOT NULL AND V_USAGE_MESSAGE_BODY.NUMERO_TENTATIVI_CONS IS NULL) OR
                         (V_USAGE_MESSAGE_BODY.MSGTYPE IS NULL AND V_USAGE_MESSAGE_BODY.NUMERO_TENTATIVI_CONS IS NOT NULL)) THEN

                          V_DATIAGGIUNTIVI(2) := V_DATIAGGIUNTIVI_QUALIFICA;
                      ELSE
                          V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_QUALIFICA;
                      END IF;

                END IF;
          END IF;

          /* ELIMINATO INSERIMENTO DEI CAMPI KEY_* IN ATTESA DI INSERIMENTO DEI 3 CAMPI DEL NUOVO TRACCIATO TT */

          /* IF(V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_ACC.VALORE := V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V;
                V_DATIAGGIUNTIVI_ACC.chiave := 'KEY_FRAZ_ACC';
                V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_ACC;
          END IF;

          IF(V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_PTL.VALORE := V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V;
                V_DATIAGGIUNTIVI_PTL.chiave := 'KEY_FRAZ_PTL';

                IF(V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NOT NULL) THEN
                    V_DATIAGGIUNTIVI(2) := V_DATIAGGIUNTIVI_PTL;
                ELSE
                    V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_PTL;
                END IF;

          END IF;

          IF(V_USAGE_MESSAGE_BODY.KEY_FRAZ_DST_V IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_DST.VALORE := V_USAGE_MESSAGE_BODY.KEY_FRAZ_DST_V;
                V_DATIAGGIUNTIVI_DST.chiave := 'KEY_FRAZ_DST';

                IF(V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NOT NULL AND V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V IS NOT NULL) THEN
                    V_DATIAGGIUNTIVI(3) := V_DATIAGGIUNTIVI_DST;
                ELSE

                      IF((V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NOT NULL AND V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V IS NULL) OR
                         (V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NULL AND V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V IS NOT NULL)) THEN

                          V_DATIAGGIUNTIVI(2) := V_DATIAGGIUNTIVI_DST;
                      ELSE
                          V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_DST;
                      END IF;

                END IF;
          END IF; */

            BEGIN

                --raise_application_error (-20001,'only for debugging');
                SAVEPOINT GESTIONE_SINGOLO_USAGE;

                LOOP
                    BEGIN
                        ADC_PKG_LOAD_USAGE.INSERIMENTOARRICCHIMENTO_USAGE(
                            IS_DIAGNOSTIC_ENABLED       => IS_DIAGNOSTIC_ENABLED,
                            IS_DEBUG_ENABLED            => IS_DEBUG_ENABLED,
                            TID                         => MSGID,
                            INPUT_ID_FLUSSO             => V_USAGE_MESSAGE_BODY.ID_FLUSSO,
                            JOB_ID                      => JOB_ID,
                            INPUTIDUSAGE 				        => V_USAGE_MESSAGE_BODY.ID,
                            DATAORAEVENTO 				      => V_USAGE_MESSAGE_BODY.DATA_ORA_EVENTO,
                            FASECICLODIVITA 			      => V_USAGE_MESSAGE_BODY.FASE_CICLO_DI_VITA,
                            SOTTOFASECICLODIVITA 		    => V_USAGE_MESSAGE_BODY.SOTTO_FASE_CICLO_DI_VITA,
                            CANALE 						          => V_USAGE_MESSAGE_BODY.CANALE,
                            SISTEMASORGENTE 			      => V_USAGE_MESSAGE_BODY.SISTEMA_SORGENTE,
                            CODICEPRODOTTOSERVIZIO 		  => V_CODICEPRODOTTOSERVIZI,
                            COSTOPRODOTTOSERVIZIO 		  => V_USAGE_MESSAGE_BODY.COSTO_PRODOTTO_SERVIZIO,
                            METODOPAGAMENTOCLIENTE 		  => V_USAGE_MESSAGE_BODY.METODO_PAGAMENTO_CLIENTE,
                            ESITO 						          => V_USAGE_MESSAGE_BODY.ESITO,
                            CHIAVEUSAGELISTA 			      => V_CHIAVEUSAGELIST,
                            IDTRACCIATURA 				      => V_USAGE_MESSAGE_BODY.ID_TRACCIATURA,
                            SISTEMATRACCIATURA 			    => V_USAGE_MESSAGE_BODY.SISTEMA_TRACCIATURA,
                            TIPOPRODOTTOTRACCIATURA 	  => V_USAGE_MESSAGE_BODY.TIPO_PRODOTTO_TRACCIATURA,
                            MOTIVOCONTATTO 				      => V_USAGE_MESSAGE_BODY.MOTIVO_CONTATTO,
                            TIPOCLIENTEPAGAMENTO	      => V_USAGE_MESSAGE_BODY.TIPO_CLIENTE_PAGAMENTO,
                            DATIAGGIUNTIVIUSAGE 	      => V_DATIAGGIUNTIVI,
                            ANAGRAFICAUSAGE 			      => V_DATIANAGRAFICI,
                            COMUNELUOGOEVENTO 		      => V_USAGE_MESSAGE_BODY.COMUNE_LUOGO_EVENTO,
                            ALTROIDTRACCIATURA 		      => V_USAGE_MESSAGE_BODY.ALTRO_ID_TRACCIATURA,
                            CODICEPTL 					        => V_USAGE_MESSAGE_BODY.CODICE_PTL,
                            ZONAPTL 					          => V_USAGE_MESSAGE_BODY.ZONA_PTL,
                            FRAZACCETTAZIONE 			      => V_USAGE_MESSAGE_BODY.FRAZ_ACC,
                            FRAZDESTINATARIO 			      => V_USAGE_MESSAGE_BODY.FRAZ_DST,
                            PROVINCIALUOGOEVENTO	      => V_USAGE_MESSAGE_BODY.PROVINCIA_LUOGO_EVENTO,
                            FILIALESDA 					        => V_USAGE_MESSAGE_BODY.FILIALE_SDA,
                            SERVIACCESSORI 				      => V_SERVIZIACCESSORI,

                            ID_FASE                     => V_USAGE_MESSAGE_BODY.ID_FASE,
                            ID_SOTTOFASE                => V_USAGE_MESSAGE_BODY.ID_SOTTOFASE,
                            ID_METODO_PAGAMENTO_CLIENTE => V_USAGE_MESSAGE_BODY.ID_METODO_PAGAMENTO_CLIENTE,
                            COD_TIPO_PROCESSO           => V_USAGE_MESSAGE_BODY.COD_TIPO_PROCESSO,
                            COD_SISTEMA_PROCESSO        => V_USAGE_MESSAGE_BODY.COD_SISTEMA_PROCESSO,
                            COD_TIPO_TRACCIATURA        => V_USAGE_MESSAGE_BODY.COD_TIPO_TRACCIATURA,
                            COD_SISTEMA_TRACCIATURA     => V_USAGE_MESSAGE_BODY.COD_SISTEMA_TRACCIATURA,
                            COD_SISTEMA_ALTROP          => V_USAGE_MESSAGE_BODY.COD_SISTEMA_ALTROP,
                            COD_TIPO_ALTROP             => V_USAGE_MESSAGE_BODY.COD_TIPO_ALTROP,
                            ID_PROD_SERVIZIO            => V_USAGE_MESSAGE_BODY.ID_PROD_SERVIZIO,
                            ID_CANALE                   => V_USAGE_MESSAGE_BODY.ID_CANALE,
                            ID_TIPO_CLIENTE_PAGAMENTO   => V_USAGE_MESSAGE_BODY.ID_TIPO_CLIENTE_PAGAMENTO,
                            ID_PROCESSO                 => V_USAGE_MESSAGE_BODY.ID_PROCESSO,
                            VENDITA                     => V_USAGE_MESSAGE_BODY.VENDITA,
                            NFEA_DETTAGLIO_A_CHIAMATA   => V_USAGE_MESSAGE_BODY.NFEA_DETTAGLIO_A_CHIAMATA,
                            NFEA_DETTAGLIO_B_CHIAMATA   => V_USAGE_MESSAGE_BODY.NFEA_DETTAGLIO_B_CHIAMATA,
                            NFEA_SITO_CC                => V_USAGE_MESSAGE_BODY.NFEA_SITO_CC,
                            NFEA_FORNITORE_CC           => V_USAGE_MESSAGE_BODY.NFEA_FORNITORE_CC,
                            NFEA_TEAM                   => V_USAGE_MESSAGE_BODY.NFEA_TEAM,
                            NFEA_LOGIN => V_USAGE_MESSAGE_BODY.NFEA_LOGIN,
                            FRAZIONARIO_UP => V_USAGE_MESSAGE_BODY.FRAZIONARIO_UP,
                            NOME_UP => V_USAGE_MESSAGE_BODY.NOME_UP,
                            CITTA_LUOGO_EVENTO => V_USAGE_MESSAGE_BODY.CITTA_LUOGO_EVENTO,
                            ALT => V_USAGE_MESSAGE_BODY.ALT,
                            RAM => V_USAGE_MESSAGE_BODY.RAM,
                            CD => V_USAGE_MESSAGE_BODY.CD,
                            ZONA => V_USAGE_MESSAGE_BODY.ZONA,
                            TIPOLOGIA_ASSISTENZA => V_USAGE_MESSAGE_BODY.TIPOLOGIA,
                            ID_TRACC_CORR => V_USAGE_MESSAGE_BODY.ID_TRACC_CORR,
                            TIPO_PROD_TRACC_CORR => V_USAGE_MESSAGE_BODY.TIPO_PROD_TRACC_CORR,
                            SIST_TRACC_CORR => V_USAGE_MESSAGE_BODY.SIST_TRACC_CORR,
                            COD_TIPO_PROD_TRACC_CORR => V_USAGE_MESSAGE_BODY.COD_TIPO_PROD_TRACC_CORR,
                            COD_SIST_TRACC_CORR => V_USAGE_MESSAGE_BODY.COD_SIST_TRACC_CORR,
                            ESITOOPERAZIONE 			      => ESITOOPERAZIONE,
                            IDUSAGE 					          => INSERTED_ID_USAGE,
                            MSGTYPE => V_USAGE_MESSAGE_BODY.MSGTYPE,
                            NUMERO_TENTATIVI_CONS        => V_USAGE_MESSAGE_BODY.NUMERO_TENTATIVI_CONS,
                            QUALIFICA                    => V_USAGE_MESSAGE_BODY.QUALIFICA,
                            SOURCE_TIPOLOGIA_ASSISTENZA => NULL
                      );
                    EXIT;
                    EXCEPTION WHEN LOCK_DETECTED THEN
                        ROLLBACK TO GESTIONE_SINGOLO_USAGE;
                        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') - ERROR :' || SQLERRM , ADC_PKG_COMMON.ERROR_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);

                        BEGIN
                            select valore into maxRetry from ADC_SYS_CONFIG where chiave = 'MAX_RETRY';
                            EXCEPTION WHEN NO_DATA_FOUND THEN
                            maxRetry :=3;
                        END;
                        BEGIN
                            select valore into sleep_sec from ADC_SYS_CONFIG where chiave = 'SLEEP_SEC';
                            EXCEPTION WHEN NO_DATA_FOUND THEN
                            sleep_sec :=2;
                        END;

                        IF(retryCount = maxRetry) then
                            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') - RETRY - Massimo Tentativi Raggiunto'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);

                            RAISE;

                        ELSE
                            dbms_lock.sleep(sleep_sec);
                            retryCount := retryCount+1;
                            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') -  RETRY - Tentativo n '|| retryCount  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);
                        END IF;
                    END;
                END LOOP;
            EXCEPTION WHEN OTHERS THEN
                ROLLBACK TO GESTIONE_SINGOLO_USAGE;
                v_ERR_message_properties.user_property := V_MESSAGE_PROPERTIES.user_property;

                V_USAGE_MESSAGE_BODY.MOTIVO_SCARTO := SUBSTR('ERROR IN INSERTING USAGE: ' || SQLERRM || ' - ' || dbms_utility.format_error_backtrace,1,256);

                DBMS_AQ.ENQUEUE(
                    QUEUE_NAME              => ERROR_QUEUE,
                    ENQUEUE_OPTIONS         => V_ERR_ENQUEUE_OPTIONS,
                    message_properties      => v_ERR_message_properties,
                    PAYLOAD                 => V_USAGE_MESSAGE_BODY,
                    MSGID                   => V_MESSAGE_HANDLE
                );

                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') - Message (' ||  V_MESSAGE_HANDLE || ') ERROR IN INSERTING UDSAGE: ' || SQLERRM || ' - ' || dbms_utility.format_error_backtrace  , ADC_PKG_COMMON.ERROR_LEVEL,INPUT_ID_FLUSSO);

            END;

              -- DBMS_OUTPUT.PUT_LINE(ESITOOPERAZIONE);
            L_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') - Message (' ||  MSGID || ') gestito correttamente (elapsed:'|| (L_END - L_START)/100 ||' s)'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);

        --  END LOOP; -- ARRAY DI SCODAMENTO

            IF(CURRENT_DEQUEUED_MESSAGE > DEQUEUE_BLOCK_SIZE) THEN
                COMMIT;
                CURRENT_DEQUEUED_MESSAGE:=0;
            END IF;

        EXIT WHEN ((L_END - GLOBAL_START)/100 )> V_SCHEDULING_INTERVAL;
        END LOOP;
    COMMIT;
    GLOBAL_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ' ) - END  -  Messages : ' || DEQUEUED_MESSAGE || ' dequeued from queue ' || IN_QUEUE ||' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)'  , ADC_PKG_COMMON.INFO_LEVEL,'');
    DBMS_OUTPUT.PUT_LINE('PROCEDURE: DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ' ) - END - Messages: ' || DEQUEUED_MESSAGE || ' dequeued from queue ' || IN_QUEUE || ' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)');
  EXCEPTION
    WHEN NO_MESSAGES THEN
        COMMIT;
        BEGIN
            SELECT QUEUE_TABLE INTO QUEUE_TABLE FROM USER_QUEUES WHERE NAME=IN_QUEUE;
            /* ABBASSA IL HWM */
            DBMS_AQADM.PURGE_QUEUE_TABLE(
                QUEUE_TABLE,
                NULL,
                PO_T
            );
        EXCEPTION WHEN NO_DATA_FOUND THEN
          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || SQLERRM || ' error in purging queue ' || IN_QUEUE, ADC_PKG_COMMON.ERROR_LEVEL,'');
        END;

        GLOBAL_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') - END (NO MORE MESSAGES) - Messages: ' || DEQUEUED_MESSAGE || ' dequeued from queue ' || IN_QUEUE || ' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)'  , ADC_PKG_COMMON.INFO_LEVEL,'');
        DBMS_OUTPUT.PUT_LINE('PROCEDURE: DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ' ) - END (NO MORE MESSAGES) - Messages: ' || DEQUEUED_MESSAGE || ' dequeued from queue ' || IN_QUEUE || ' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)');
    WHEN OTHERS THEN
        GLOBAL_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') error in dequeuing from queue ' || IN_QUEUE ||' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)' || SQLERRM  , ADC_PKG_COMMON.ERROR_LEVEL,'');
        DBMS_OUTPUT.PUT_LINE('PROCEDURE: DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') error in dequeuing from queue ' || IN_QUEUE ||' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)' || SQLERRM);
        ROLLBACK;
        RAISE;
END;

PROCEDURE DEQUEUE_USAGE_SAP_EM(JOB_ID VARCHAR2, IN_QUEUE VARCHAR2, ERROR_QUEUE VARCHAR2, V_SCHEDULING_INTERVAL NUMBER, MESSAGE OUT VARCHAR2,ESITO OUT VARCHAR2) IS

    -- not change
    msgid                     RAW (16);

    DATIAGGIUNTIVI_ROW DATIAGGIUNTIVI_TYPE;
    V_DATIAGGIUNTIVI_ACC DATIAGGIUNTIVI_TYPE;
    V_DATIAGGIUNTIVI_PTL DATIAGGIUNTIVI_TYPE;
    V_DATIAGGIUNTIVI_DST DATIAGGIUNTIVI_TYPE;
    V_DATIAGGIUNTIVI DATIAGGIUNTIVI_TABLE;

    V_CHIAVEUSAGERECORD CHIAVEUSAGE_TYPE;
    V_CHIAVEUSAGELIST CHIAVEUSAGE_TABLE;

    V_ANAG_RIC_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_CLI_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_MIT_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_DEST_RECORD DATIANAGRAFICI_TYPE;
    V_ANAG_INT_RECORD DATIANAGRAFICI_TYPE;
    V_DATIANAGRAFICI  DATIANAGRAFICI_TABLE;

    V_SERVIZIACCESSORI SERVIZIACCESSORI_TABLE;

    V_CODICEPRODOTTOSERVIZIO        CODICEPRODOTTOSERVIZIO_TYPE;
    V_CODICEPRODOTTOSERVIZI         CODICEPRODOTTOSERVIZIO_TABLE;

    ESITOOPERAZIONE                 VARCHAR2(100);
    INSERTED_ID_USAGE               VARCHAR2(100);
    LOGRESULT                       NUMBER;
    L_START                         NUMBER;
    L_END                           NUMBER;
    GLOBAL_START                    NUMBER;
    GLOBAL_END                      NUMBER;
    INPUT_ID_FLUSSO                 NUMBER;

    DEQUEUED_MESSAGE                NUMBER;
    CURRENT_DEQUEUED_MESSAGE        NUMBER;
    DEQUEUE_BLOCK_SIZE              NUMBER;

    no_messages                     exception;


    V_USAGE_MESSAGE_BODY            LOAD_USAGE_MESSAGE_SAPEM_TYPE;

    V_DEQUEUE_OPTIONS               DBMS_AQ.DEQUEUE_OPTIONS_T;
    V_MESSAGE_PROPERTIES            DBMS_AQ.MESSAGE_PROPERTIES_T;
    V_MESSAGE_HANDLE_ARRAY          DBMS_AQ.MSGID_ARRAY_T;
    V_MSG_PROPERTIES_TABLE          DBMS_AQ.MESSAGE_PROPERTIES_ARRAY_T := DBMS_AQ.MESSAGE_PROPERTIES_ARRAY_T();
    V_USAGE_MESSAGE_BODY_ARRAY      LOAD_USAGE_MESSAGES_ARRAY;
    RETVAL                          PLS_INTEGER;
    V_VIRTUAL_QUEUE                 VARCHAR(255);
    PO_T                            DBMS_AQADM.AQ$_PURGE_OPTIONS_T;
    V_ERR_ENQUEUE_OPTIONS           DBMS_AQ.ENQUEUE_OPTIONS_T;
    V_ERR_MESSAGE_PROPERTIES        DBMS_AQ.MESSAGE_PROPERTIES_T;
    V_MESSAGE_HANDLE                RAW(16);
    QUEUE_TABLE                     VARCHAR2(255);

    PRAGMA EXCEPTION_INIT (NO_MESSAGES, -25228);

    IS_DEBUG_ENABLED                BOOLEAN;
    IS_DIAGNOSTIC_ENABLED           BOOLEAN;

    BEGIN

      IS_DIAGNOSTIC_ENABLED  := ADC_PKG_COMMON.IS_LEVEL_ENABLED(ADC_PKG_LOAD_USAGE.DIAGNOSTIC_LOGGER_NAME, ADC_PKG_COMMON.INFO_LEVEL);
      IS_DEBUG_ENABLED := ADC_PKG_COMMON.IS_LEVEL_ENABLED(LOGGER_NAME, ADC_PKG_COMMON.DEBUG_LEVEL);

      --  V_DEQUEUE_OPTIONS.CONSUMER_NAME := 'AG_TT_LOAD_USAGE';
      V_DEQUEUE_OPTIONS.wait          := DBMS_AQ.NO_WAIT;
      V_DEQUEUE_OPTIONS.VISIBILITY    := DBMS_AQ.ON_COMMIT;
      --  V_DEQUEUE_OPTIONS.navigation    := DBMS_AQ.FIRST_MESSAGE;

      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ')  - BEGIN'  , ADC_PKG_COMMON.INFO_LEVEL,'');
      GLOBAL_START := DBMS_UTILITY.GET_TIME ;  -- Start Time

      V_VIRTUAL_QUEUE := SUBSTR(IN_QUEUE  ,3,LENGTH(IN_QUEUE) -5);
      BEGIN
          SELECT PARAMETER_VALUE INTO DEQUEUE_BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='DEQUEUE_BLOCK_SIZE' AND ROWNUM = 1;
		  EXCEPTION WHEN NO_DATA_FOUND THEN
          SELECT PARAMETER_VALUE INTO DEQUEUE_BLOCK_SIZE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='DEQUEUE_BLOCK_SIZE' AND ROWNUM = 1;
		  END;

      DEQUEUED_MESSAGE          :=0;
      CURRENT_DEQUEUED_MESSAGE  :=0;

      LOOP
          L_START := DBMS_UTILITY.GET_TIME ;  -- Start Time

          DBMS_AQ.DEQUEUE(
                         queue_name           => IN_QUEUE,
                         dequeue_options      => V_DEQUEUE_OPTIONS,
                         message_properties   => V_MESSAGE_PROPERTIES,
                         PAYLOAD              => V_USAGE_MESSAGE_BODY,
                         MSGID                => MSGID);

          DEQUEUED_MESSAGE := DEQUEUED_MESSAGE + 1;
          CURRENT_DEQUEUED_MESSAGE := CURRENT_DEQUEUED_MESSAGE +1;

          V_DATIAGGIUNTIVI.DELETE();
          V_CODICEPRODOTTOSERVIZI.DELETE();

          INPUT_ID_FLUSSO :=  SYS.ANYDATA.accessNumber(V_MESSAGE_PROPERTIES.user_property);

          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ' ) - Scodato messaggio (' ||  msgid || ')'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);

          --DBMS_OUTPUT.PUT_LINE('RECEIVE: -->' ||msgid || ':' || V_USAGE_MESSAGE_BODY.ID);

          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ') - Creazione oggetti per gestione dello USAGE (' ||  V_USAGE_MESSAGE_BODY.ID || ')'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);

          /* GESTIONE CHIAVI */
          V_CHIAVEUSAGERECORD.IDPROCESSOINTERNO 		    := V_USAGE_MESSAGE_BODY.ID_PROCESSO_INTERNO;
          V_CHIAVEUSAGERECORD.IDTIPOPROCESSOINTERNO 	  := V_USAGE_MESSAGE_BODY.ID_TIPO_PROCESSO_INTERNO;
          V_CHIAVEUSAGERECORD.SISTEMAPROCESSOINTERNO 	  := V_USAGE_MESSAGE_BODY.SISTEMA_PROCESSO_INTERNO;
          V_CHIAVEUSAGERECORD.IDALTROPROCESSO 		      := V_USAGE_MESSAGE_BODY.ID_ALTRO_PROCESSO;
          V_CHIAVEUSAGERECORD.ALTROPROCESSOPRECEDENTE   := V_USAGE_MESSAGE_BODY.ALTRO_PROCESSO_PRECEDENTE;
          V_CHIAVEUSAGERECORD.IDTIPOALTROPROCESSO 	    := V_USAGE_MESSAGE_BODY.ID_TIPO_ALTRO_PROCESSO;
          V_CHIAVEUSAGERECORD.SISTEMAALTROPROCESSO 	    := V_USAGE_MESSAGE_BODY.SISTEMA_ALTRO_PROCESSO;
          V_CHIAVEUSAGERECORD.CODTIPOPROCINTERNO        := V_USAGE_MESSAGE_BODY.COD_TIPO_PROCESSO;
          V_CHIAVEUSAGERECORD.CODSISPROCINTERNO         := V_USAGE_MESSAGE_BODY.COD_SISTEMA_PROCESSO;
          V_CHIAVEUSAGERECORD.CODSISTEMA                := V_USAGE_MESSAGE_BODY.COD_SISTEMA_ALTROP;
          V_CHIAVEUSAGERECORD.CODALTROPROC              := V_USAGE_MESSAGE_BODY.COD_TIPO_ALTROP;
          V_CHIAVEUSAGERECORD.CANALE                    := V_USAGE_MESSAGE_BODY.CANALE;

          V_CHIAVEUSAGELIST(1):= V_CHIAVEUSAGERECORD;

          /* GESTIONE ANAGRAFICHE */

          V_ANAG_RIC_RECORD.TIPORUOLO 	:=	'RICHIEDENTE';

          V_ANAG_RIC_RECORD.CF 	:=	V_USAGE_MESSAGE_BODY.CODICE_FISCALE_RIC;
          V_ANAG_RIC_RECORD.CNF 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_RIC;
          V_ANAG_RIC_RECORD.PIVA 	:=	V_USAGE_MESSAGE_BODY.PIVA_RIC;
          V_ANAG_RIC_RECORD.CNPIVA 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_RIC;
          V_ANAG_RIC_RECORD.SISTEMACODICENONFISCALE	:=	V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISCALE_RIC;
          V_ANAG_RIC_RECORD.CODICECLIENTENONFISCALE	:=	V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISCALE_RIC;
          V_ANAG_RIC_RECORD.NOME 	:=	V_USAGE_MESSAGE_BODY.NOME_RIC;
          V_ANAG_RIC_RECORD.COGNOME 	:=	V_USAGE_MESSAGE_BODY.COGNOME_RIC;
          V_ANAG_RIC_RECORD.PARTICELLATOPONOMASTICA	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_RIC;
          V_ANAG_RIC_RECORD.INDIRIZZO 	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_RIC;
          V_ANAG_RIC_RECORD.NUMEROCIVICO 	:=	V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_RIC;
          V_ANAG_RIC_RECORD.CAP 	:=	V_USAGE_MESSAGE_BODY.CAP_RIC;
          V_ANAG_RIC_RECORD.COMUNE 	:=	V_USAGE_MESSAGE_BODY.COMUNE_RIC;
          V_ANAG_RIC_RECORD.PROVINCIA 	:=	V_USAGE_MESSAGE_BODY.PROVINCIA_RIC;
          V_ANAG_RIC_RECORD.STATO	:=	V_USAGE_MESSAGE_BODY.STATO_RIC;
          V_ANAG_RIC_RECORD.TELEFONO 	:=	V_USAGE_MESSAGE_BODY.TELEFONO_RIC;
          V_ANAG_RIC_RECORD.mail 	:=	V_USAGE_MESSAGE_BODY.MAIL_RIC;
          V_ANAG_RIC_RECORD.codiceNazionaleFis :=	V_USAGE_MESSAGE_BODY.COD_NAZIONALE_FIS_RIC;
          V_ANAG_RIC_RECORD.codiceNazionalePiva :=	V_USAGE_MESSAGE_BODY.CN_PIVA_RIC;


          V_ANAG_CLI_RECORD.tipoRuolo 	:=	'CLIENTE';

          V_ANAG_CLI_RECORD.CF 	:=	V_USAGE_MESSAGE_BODY.CODICE_FISCALE_CLI;
          V_ANAG_CLI_RECORD.cnf 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_FISCALE_CLI;
          V_ANAG_CLI_RECORD.PIVA 	:=	V_USAGE_MESSAGE_BODY.PIVA_CLI;
          V_ANAG_CLI_RECORD.cnPiva 	:=	V_USAGE_MESSAGE_BODY.CODICE_NAZIONE_PIVA_CLI;
          V_ANAG_CLI_RECORD.SISTEMACODICENONFISCALE	:=	V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISCALE_CLI;
          V_ANAG_CLI_RECORD.codiceClienteNonFiscale	:=	V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISCALE_CLI;
          V_ANAG_CLI_RECORD.NOME 	:=	V_USAGE_MESSAGE_BODY.NOME_CLI;
          V_ANAG_CLI_RECORD.cognome 	:=	V_USAGE_MESSAGE_BODY.COGNOME_CLI;
          V_ANAG_CLI_RECORD.PARTICELLATOPONOMASTICA	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_CLI;
          V_ANAG_CLI_RECORD.indirizzo 	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_CLI;
          V_ANAG_CLI_RECORD.NUMEROCIVICO 	:=	V_USAGE_MESSAGE_BODY.NUMERO_CIVICO_CLI;
          V_ANAG_CLI_RECORD.CAP 	:=	V_USAGE_MESSAGE_BODY.CAP_CLI;
          V_ANAG_CLI_RECORD.COMUNE 	:=	V_USAGE_MESSAGE_BODY.COMUNE_CLI;
          V_ANAG_CLI_RECORD.provincia 	:=	V_USAGE_MESSAGE_BODY.PROVINCIA_CLI;
          V_ANAG_CLI_RECORD.STATO	:=	V_USAGE_MESSAGE_BODY.STATO_CLI;
