          V_ANAG_INT_RECORD.SISTEMACODICENONFISCALE	:=	V_USAGE_MESSAGE_BODY.SISTEMA_CODICE_NON_FISC_INT;
          V_ANAG_INT_RECORD.CODICECLIENTENONFISCALE	:=	V_USAGE_MESSAGE_BODY.CODICE_CLIENTE_NON_FISC_INT;
          V_ANAG_INT_RECORD.NOME 	:=	V_USAGE_MESSAGE_BODY.NOME_INT;
          V_ANAG_INT_RECORD.COGNOME 	:=	V_USAGE_MESSAGE_BODY.COGNOME_INT;
          V_ANAG_INT_RECORD.particellaToponomastica	:=	V_USAGE_MESSAGE_BODY.INDIRIZZO_PARTICELLA_TOP_INT;
