          V_DATIANAGRAFICI(4):= V_ANAG_DEST_RECORD;
          V_DATIANAGRAFICI(5):= V_ANAG_INT_RECORD;

          --GETSERVIZIACCESSORI(IS_DEBUG_ENABLED, msgid, V_USAGE_MESSAGE_BODY.SA, V_USAGE_MESSAGE_BODY.SISTEMA_SORGENTE, V_SERVIZIACCESSORI);
          --GETSERVIZIACCESSORI(IS_DEBUG_ENABLED, V_USAGE_MESSAGE_BODY.SA, V_USAGE_MESSAGE_BODY.SISTEMA_SORGENTE, msgid, V_SERVIZIACCESSORI);

          V_CODICEPRODOTTOSERVIZIO.CODICE   :=  V_USAGE_MESSAGE_BODY.CODICE_PRODOTTO_SERVIZIO;
          V_CODICEPRODOTTOSERVIZIO.codiceProdottoServizioTrans  :=  V_USAGE_MESSAGE_BODY.ID_PROD_SERVIZIO;

          V_CODICEPRODOTTOSERVIZI(1)        :=  V_CODICEPRODOTTOSERVIZIO;

          /* ELIMINATO INSERIMENTO DEI CAMPI KEY_* IN ATTESA DI INSERIMENTO DEI 3 CAMPI DEL NUOVO TRACCIATO TT */

          /* IF(V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_ACC.VALORE := V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V;
                V_DATIAGGIUNTIVI_ACC.chiave := 'KEY_FRAZ_ACC';
                V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_ACC;
          END IF;

          IF(V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_PTL.VALORE := V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V;
                V_DATIAGGIUNTIVI_PTL.chiave := 'KEY_FRAZ_PTL';

                IF(V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NOT NULL) THEN
                    V_DATIAGGIUNTIVI(2) := V_DATIAGGIUNTIVI_PTL;
                ELSE
                    V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_PTL;
                END IF;

          END IF;

          IF(V_USAGE_MESSAGE_BODY.KEY_FRAZ_DST_V IS NOT NULL) THEN
                V_DATIAGGIUNTIVI_DST.VALORE := V_USAGE_MESSAGE_BODY.KEY_FRAZ_DST_V;
                V_DATIAGGIUNTIVI_DST.chiave := 'KEY_FRAZ_DST';

                IF(V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NOT NULL AND V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V IS NOT NULL) THEN
                    V_DATIAGGIUNTIVI(3) := V_DATIAGGIUNTIVI_DST;
                ELSE

                      IF((V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NOT NULL AND V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V IS NULL) OR
                         (V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC_V IS NULL AND V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL_V IS NOT NULL)) THEN

                          V_DATIAGGIUNTIVI(2) := V_DATIAGGIUNTIVI_DST;
                      ELSE
                          V_DATIAGGIUNTIVI(1) := V_DATIAGGIUNTIVI_DST;
                      END IF;

                END IF;
          END IF; */

          BEGIN

            --raise_application_error (-20001,'only for debugging');
            SAVEPOINT GESTIONE_SINGOLO_USAGE;
            ADC_PKG_LOAD_USAGE.INSERIMENTOARRICCHIMENTO_USAGE(
                        IS_DIAGNOSTIC_ENABLED       => IS_DIAGNOSTIC_ENABLED,
                        IS_DEBUG_ENABLED            => IS_DEBUG_ENABLED,
                        TID                         => MSGID,
                        INPUT_ID_FLUSSO             => V_USAGE_MESSAGE_BODY.ID_FLUSSO,
                        JOB_ID                      => JOB_ID,
                        INPUTIDUSAGE 				        => V_USAGE_MESSAGE_BODY.ID,
                        DATAORAEVENTO 				      => V_USAGE_MESSAGE_BODY.DATA_ORA_EVENTO,
                        FASECICLODIVITA 			      => V_USAGE_MESSAGE_BODY.FASE_CICLO_DI_VITA,
                        SOTTOFASECICLODIVITA 		    => V_USAGE_MESSAGE_BODY.SOTTO_FASE_CICLO_DI_VITA,
                        CANALE 						          => V_USAGE_MESSAGE_BODY.CANALE,
                        SISTEMASORGENTE 			      => V_USAGE_MESSAGE_BODY.SISTEMA_SORGENTE,
                        CODICEPRODOTTOSERVIZIO 		  => V_CODICEPRODOTTOSERVIZI,
                        COSTOPRODOTTOSERVIZIO 		  => V_USAGE_MESSAGE_BODY.COSTO_PRODOTTO_SERVIZIO,
                        METODOPAGAMENTOCLIENTE 		  => NULL /*V_USAGE_MESSAGE_BODY.METODO_PAGAMENTO_CLIENTE */,
                        ESITO 						          => V_USAGE_MESSAGE_BODY.ESITO,
                        CHIAVEUSAGELISTA 			      => V_CHIAVEUSAGELIST,
                        IDTRACCIATURA 				      => V_USAGE_MESSAGE_BODY.ID_TRACCIATURA,
                        SISTEMATRACCIATURA 			    => V_USAGE_MESSAGE_BODY.SISTEMA_TRACCIATURA,
                        TIPOPRODOTTOTRACCIATURA 	  => V_USAGE_MESSAGE_BODY.TIPO_PRODOTTO_TRACCIATURA,
                        MOTIVOCONTATTO 				      => NULL /*V_USAGE_MESSAGE_BODY.MOTIVO_CONTATTO*/,
                        TIPOCLIENTEPAGAMENTO	      => V_USAGE_MESSAGE_BODY.TIPO_CLIENTE_PAGAMENTO,
                        DATIAGGIUNTIVIUSAGE 	      => V_DATIAGGIUNTIVI,
                        ANAGRAFICAUSAGE 			      => V_DATIANAGRAFICI,
                        COMUNELUOGOEVENTO 		      => NULL /*V_USAGE_MESSAGE_BODY.COMUNE_LUOGO_EVENTO */,
                        ALTROIDTRACCIATURA 		      => NULL/*V_USAGE_MESSAGE_BODY.ALTRO_ID_TRACCIATURA */,
                        CODICEPTL 					        => V_USAGE_MESSAGE_BODY.CODICE_PTL,
                        ZONAPTL 					          => V_USAGE_MESSAGE_BODY.KEY_ZONA_PTL,
                        FRAZACCETTAZIONE 			      => V_USAGE_MESSAGE_BODY.KEY_FRAZ_ACC,
                        FRAZDESTINATARIO 			      => V_USAGE_MESSAGE_BODY.KEY_FRAZ_DST,
                        PROVINCIALUOGOEVENTO	      => NULL /*V_USAGE_MESSAGE_BODY.PROVINCIA_LUOGO_EVENTO */,
                        FILIALESDA 					        => NULL /*V_USAGE_MESSAGE_BODY.FILIALE_SDA */,
                        SERVIACCESSORI 				      => V_SERVIZIACCESSORI,

                        ID_FASE                     => V_USAGE_MESSAGE_BODY.ID_FASE,
                        ID_SOTTOFASE                => V_USAGE_MESSAGE_BODY.ID_SOTTOFASE,
                        ID_METODO_PAGAMENTO_CLIENTE => NULL /*V_USAGE_MESSAGE_BODY.ID_METODO_PAGAMENTO_CLIENTE */,
                        COD_TIPO_PROCESSO           => V_USAGE_MESSAGE_BODY.COD_TIPO_PROCESSO,
                        COD_SISTEMA_PROCESSO        => V_USAGE_MESSAGE_BODY.COD_SISTEMA_PROCESSO,
                        COD_TIPO_TRACCIATURA        => V_USAGE_MESSAGE_BODY.COD_TIPO_TRACCIATURA,
                        COD_SISTEMA_TRACCIATURA     => V_USAGE_MESSAGE_BODY.COD_SISTEMA_TRACCIATURA,
                        COD_SISTEMA_ALTROP          => V_USAGE_MESSAGE_BODY.COD_SISTEMA_ALTROP,
                        COD_TIPO_ALTROP             => V_USAGE_MESSAGE_BODY.COD_TIPO_ALTROP,
                        ID_PROD_SERVIZIO            => V_USAGE_MESSAGE_BODY.ID_PROD_SERVIZIO,
                        ID_CANALE                   => V_USAGE_MESSAGE_BODY.ID_CANALE,
                        ID_TIPO_CLIENTE_PAGAMENTO   => V_USAGE_MESSAGE_BODY.ID_TIPO_CLIENTE_PAGAMENTO,
                        ID_PROCESSO                 => V_USAGE_MESSAGE_BODY.ID_PROCESSO,
                        VENDITA                     => NULL /*V_USAGE_MESSAGE_BODY.VENDITA */,
                        NFEA_DETTAGLIO_A_CHIAMATA   => NULL /*V_USAGE_MESSAGE_BODY.NFEA_DETTAGLIO_A_CHIAMATA */,
                        NFEA_DETTAGLIO_B_CHIAMATA   => NULL /*V_USAGE_MESSAGE_BODY.NFEA_DETTAGLIO_B_CHIAMATA */,
                        NFEA_SITO_CC                => NULL /*V_USAGE_MESSAGE_BODY.NFEA_SITO_CC */,
                        NFEA_FORNITORE_CC           => NULL /*V_USAGE_MESSAGE_BODY.NFEA_FORNITORE_CC */,
                        NFEA_TEAM                   => NULL /*V_USAGE_MESSAGE_BODY.NFEA_TEAM */,
                        NFEA_LOGIN                  => NULL /*V_USAGE_MESSAGE_BODY.NFEA_LOGIN */,
                        FRAZIONARIO_UP              => NULL /*V_USAGE_MESSAGE_BODY.FRAZIONARIO_UP */,
                        NOME_UP                     => NULL /*V_USAGE_MESSAGE_BODY.NOME_UP*/,
                        CITTA_LUOGO_EVENTO          => NULL /*V_USAGE_MESSAGE_BODY.CITTA_LUOGO_EVENTO*/,
                        ALT                         => NULL /*V_USAGE_MESSAGE_BODY.ALT */,
                        RAM                         => NULL /*V_USAGE_MESSAGE_BODY.RAM */,
                        CD                          => NULL /*V_USAGE_MESSAGE_BODY.CD */,
                        ZONA                        => NULL /*V_USAGE_MESSAGE_BODY.ZONA */,
                        TIPOLOGIA_ASSISTENZA        => NULL /*V_USAGE_MESSAGE_BODY.TIPOLOGIA */,
                        ID_TRACC_CORR               => NULL /*V_USAGE_MESSAGE_BODY.ID_TRACC_CORR */,
                        TIPO_PROD_TRACC_CORR        => NULL /*V_USAGE_MESSAGE_BODY.TIPO_PROD_TRACC_CORR */,
                        SIST_TRACC_CORR             => NULL /*V_USAGE_MESSAGE_BODY.SIST_TRACC_CORR */,
                        COD_TIPO_PROD_TRACC_CORR    => NULL /*V_USAGE_MESSAGE_BODY.COD_TIPO_PROD_TRACC_CORR */,
                        COD_SIST_TRACC_CORR         => NULL /*V_USAGE_MESSAGE_BODY.COD_SIST_TRACC_CORR */,
                        ESITOOPERAZIONE 			      => ESITOOPERAZIONE,
                        IDUSAGE 					          => INSERTED_ID_USAGE,
                        MSGTYPE                     => NULL,
                        NUMERO_TENTATIVI_CONS       => NULL,
                        QUALIFICA                   => NULL,
                        SOURCE_TIPOLOGIA_ASSISTENZA => NULL
                  );

              EXCEPTION WHEN OTHERS THEN
                  ROLLBACK TO GESTIONE_SINGOLO_USAGE;
                  v_ERR_message_properties.user_property := V_MESSAGE_PROPERTIES.user_property;

                  V_USAGE_MESSAGE_BODY.MOTIVO_SCARTO := SUBSTR('ERROR IN INSERTING USAGE: ' || SQLERRM || ' - ' || dbms_utility.format_error_backtrace,1,256);

                  DBMS_AQ.ENQUEUE(
                      QUEUE_NAME              => ERROR_QUEUE,
                      ENQUEUE_OPTIONS         => V_ERR_ENQUEUE_OPTIONS,
                      message_properties      => v_ERR_message_properties,
                      PAYLOAD                 => V_USAGE_MESSAGE_BODY,
                      MSGID                   => V_MESSAGE_HANDLE
                    );

                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ') - Message (' ||  V_MESSAGE_HANDLE || ') ERROR IN INSERTING UDSAGE: ' || SQLERRM || ' - ' || dbms_utility.format_error_backtrace  , ADC_PKG_COMMON.ERROR_LEVEL,INPUT_ID_FLUSSO);

              END;

              -- DBMS_OUTPUT.PUT_LINE(ESITOOPERAZIONE);
              L_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ') - Message (' ||  MSGID || ') gestito correttamente (elapsed:'|| (L_END - L_START)/100 ||' s)'  , ADC_PKG_COMMON.DEBUG_LEVEL,INPUT_ID_FLUSSO,IS_DEBUG_ENABLED);

      --  END LOOP; -- ARRAY DI SCODAMENTO

        IF(CURRENT_DEQUEUED_MESSAGE > DEQUEUE_BLOCK_SIZE) THEN
            COMMIT;
            CURRENT_DEQUEUED_MESSAGE:=0;
        END IF;

        EXIT WHEN ((L_END - GLOBAL_START)/100 )> V_SCHEDULING_INTERVAL;
  END LOOP;
  COMMIT;
  GLOBAL_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ' ) - END  -  Messages : ' || DEQUEUED_MESSAGE || ' dequeued from queue ' || IN_QUEUE ||' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)'  , ADC_PKG_COMMON.INFO_LEVEL,'');
  DBMS_OUTPUT.PUT_LINE('PROCEDURE: DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ' ) - END - Messages: ' || DEQUEUED_MESSAGE || ' dequeued from queue ' || IN_QUEUE || ' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)');
  EXCEPTION
    WHEN NO_MESSAGES THEN
        COMMIT;
        BEGIN
            SELECT QUEUE_TABLE INTO QUEUE_TABLE FROM USER_QUEUES WHERE NAME=IN_QUEUE;
            /* ABBASSA IL HWM */
            DBMS_AQADM.PURGE_QUEUE_TABLE(
                QUEUE_TABLE,
                NULL,
                PO_T
            );
        EXCEPTION WHEN NO_DATA_FOUND THEN
          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_SAP_EM (JOB ID: ' || SQLERRM || ' error in purging queue ' || IN_QUEUE, ADC_PKG_COMMON.ERROR_LEVEL,'');
        END;

        GLOBAL_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ') - END (NO MORE MESSAGES) - Messages: ' || DEQUEUED_MESSAGE || ' dequeued from queue ' || IN_QUEUE || ' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)'  , ADC_PKG_COMMON.INFO_LEVEL,'');
        DBMS_OUTPUT.PUT_LINE('PROCEDURE: DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ' ) - END (NO MORE MESSAGES) - Messages: ' || DEQUEUED_MESSAGE || ' dequeued from queue ' || IN_QUEUE || ' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)');
    WHEN OTHERS THEN
        GLOBAL_END := DBMS_UTILITY.GET_TIME ;  -- Start Time
        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'DEQUEUE_USAGE (JOB ID: ' || JOB_ID || ') error in dequeuing from queue ' || IN_QUEUE ||' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)' || SQLERRM  , ADC_PKG_COMMON.ERROR_LEVEL,'');
        DBMS_OUTPUT.PUT_LINE('PROCEDURE: DEQUEUE_USAGE_SAP_EM (JOB ID: ' || JOB_ID || ') error in dequeuing from queue ' || IN_QUEUE ||' (elapsed:'|| (GLOBAL_END - GLOBAL_START)/100 ||' s)' || SQLERRM);
        ROLLBACK;
        RAISE;
END;

PROCEDURE INSERIMENTOUSAGEONLINE(
    TID VARCHAR2,
    dataOraEvento TIMESTAMP,
    faseCicloDiVita VARCHAR2,
    sottoFaseCicloDiVita VARCHAR2,
    canale VARCHAR2,
    sistemaSorgente VARCHAR2 ,
    codiceProdottoServizio CODICEPRODOTTOSERVIZIO_TABLE,
    costoProdottoServizio VARCHAR2,
    metodoPagamentoCliente VARCHAR2,
    esito VARCHAR2,
    chiaveUsageLista CHIAVEUSAGE_TABLE,
    idTracciatura VARCHAR2,
    sistemaTracciatura VARCHAR2,
    tipoProdottoTracciatura VARCHAR2,
    motivoContatto VARCHAR2,
    tipoClientePagamento VARCHAR2,
    datiAggiuntiviUsage DATIAGGIUNTIVI_TABLE,
    anagraficaUsage DATIANAGRAFICI_TABLE,
    ComuneLuogoEvento VARCHAR2,
    AltroIdTracciatura VARCHAR2,
    CodicePTL VARCHAR2,
    ZonaPTL VARCHAR2,
    FrazAccettazione VARCHAR2,
    FrazDestinatario VARCHAR2,
    ProvinciaLuogoEvento VARCHAR2,
    FilialeSDA VARCHAR2,
    SERVIACCESSORI SERVIZIACCESSORI_TABLE,
    idTracciaturaCorrelata VARCHAR2,
    sistemaTracciaturaCorrelata VARCHAR2,
    tipoProdTracciaturaCorrelata VARCHAR2,
    esitoOperazione OUT VARCHAR2,
    ERROR_MESSAGE OUT VARCHAR2,
    idUsage OUT NUMBER

) IS
      LOGRESULT NUMBER;
      L_START NUMBER;
      l_end number;

      codice VARCHAR2(4);
      descrizione VARCHAR2(255);

      IS_DEBUG_ENABLED BOOLEAN;

      ID_FASE_TRANS VARCHAR2(255);
      ID_SOTTOFASE_TRANS VARCHAR2(255);
      ID_CANALE_TRANS VARCHAR2(255);
      COD_TIPO_PROD_TRACC_TRANS VARCHAR2(255);
      COD_SIS_TRACCIATURA_TRANS VARCHAR2(255);
      COD_TIPO_PROD_TRACC_CORR_TRANS VARCHAR2(255);
      COD_SIS_TRACCIATURA_CORR_TRANS VARCHAR2(255);
      ID_TIPO_CLIENTE_PAGAMENTO  VARCHAR2(255);
      ID_METODO_PAGAMENTO_CLIENTE VARCHAR2(255);
      CODICE_PRODOTTO_SERVIZIO_TRANS VARCHAR2(255);
      COD_TIPO_PROC_INTERNO VARCHAR2(255);
      COD_SIS_PROC_INTERNO VARCHAR2(255);
      COD_ALTRO_PROC VARCHAR2(255);
      COD_SISTEMA VARCHAR2(255);

      idProcessoInterno_IN VARCHAR2(255);
      idAltroProcesso_IN VARCHAR2(255);


      J   NUMBER;

      --diagnostic variables
      DIAGNOSTIC_CODE VARCHAR2(512):='IUO4006';
      DIAGNOSTIC_LN VARCHAR2(512):=ADC_PKG_LOAD_USAGE.DIAGNOSTIC_LOGGER_NAME;
      DIAGNOSTIC_INFO_LEVEL VARCHAR2(512):=ADC_PKG_COMMON.INFO_LEVEL;
      DIAGNOSTIC_RESULT NUMBER;

      retryCount NUMBER;
      maxRetry NUMBER;
      sleep_sec NUMBER;

      chiaveUsageListaWork CHIAVEUSAGE_TABLE;
      V_CHIAVEUSAGERECORD CHIAVEUSAGE_TYPE;

BEGIN
   BEGIN
       retryCount:= 0;

       LOGGER_NAME:='USAGE'; -- set logger_name per la sessione
       esitoOperazione := 'OK';
       l_start := dbms_utility.get_time ;  -- Start Time
       IS_DEBUG_ENABLED := ADC_PKG_COMMON.IS_LEVEL_ENABLED(LOGGER_NAME, ADC_PKG_COMMON.DEBUG_LEVEL);
       logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE- BEGIN', ADC_PKG_COMMON.INFO_LEVEL,TID);

       DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
       /*TRANSCODIFICHE*/
       ID_FASE_TRANS := PKG_UTILITY.transFaseCicloVita(sistemaSorgente, faseCicloDiVita);
       ID_SOTTOFASE_TRANS := PKG_UTILITY.transSottoFaseCicloVita(sistemaSorgente, sottoFaseCicloDiVita);
       ID_CANALE_TRANS := PKG_USAGE_UTILITY.transCanaleUsage(sistemaSorgente, canale);
       COD_TIPO_PROD_TRACC_TRANS := PKG_UTILITY.transTipoTracciatura(sistemaSorgente, tipoProdottoTracciatura);
       COD_SIS_TRACCIATURA_TRANS := PKG_UTILITY.transCodiceSistemaTracciatura(sistemaSorgente, sistemaTracciatura);
       ID_TIPO_CLIENTE_PAGAMENTO := PKG_UTILITY.transTipoClientePagamento(sistemaSorgente, tipoClientePagamento);
       ID_METODO_PAGAMENTO_CLIENTE := PKG_UTILITY.transMetodoPagamentoCliente(sistemaSorgente, metodoPagamentoCliente);

       DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
       J:= codiceProdottoServizio.FIRST;

       IF(J IS NOT NULL) THEN
          CODICE_PRODOTTO_SERVIZIO_TRANS := PKG_UTILITY.transCodiceProdottoServizio(sistemaSorgente, codiceProdottoServizio(J).codice);
       ELSE
          CODICE_PRODOTTO_SERVIZIO_TRANS := NULL;
       END IF;

       DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00020' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

       J:= chiaveUsageLista.FIRST;

       IF(J IS NOT NULL) THEN

          COD_TIPO_PROC_INTERNO := PKG_UTILITY.transTipoProcessoInterno(sistemaSorgente, chiaveUsageLista(J).idTipoProcessoInterno);
          COD_SIS_PROC_INTERNO := PKG_UTILITY.transSistemaProcessoInterno(sistemaSorgente, chiaveUsageLista(J).sistemaProcessoInterno);
          COD_ALTRO_PROC := PKG_UTILITY.transTipoProcessoInterno(sistemaSorgente, chiaveUsageLista(j).idTipoAltroProcesso);
          COD_SISTEMA := PKG_UTILITY.transSistemaProcessoInterno(sistemaSorgente, chiaveUsageLista(J).sistemaAltroProcesso);

          idProcessoInterno_IN :=  chiaveUsageLista(J).idProcessoInterno;
          idAltroProcesso_IN := chiaveUsageLista(j).idAltroProcesso;

          V_CHIAVEUSAGERECORD.IDPROCESSOINTERNO 		    := chiaveUsageLista(J).IDPROCESSOINTERNO;
          V_CHIAVEUSAGERECORD.IDTIPOPROCESSOINTERNO 	  := chiaveUsageLista(J).IDTIPOPROCESSOINTERNO;
          V_CHIAVEUSAGERECORD.SISTEMAPROCESSOINTERNO 	  := chiaveUsageLista(J).SISTEMAPROCESSOINTERNO;
          V_CHIAVEUSAGERECORD.IDALTROPROCESSO 		      := chiaveUsageLista(J).IDALTROPROCESSO;
          V_CHIAVEUSAGERECORD.ALTROPROCESSOPRECEDENTE   := chiaveUsageLista(J).ALTROPROCESSOPRECEDENTE;
          V_CHIAVEUSAGERECORD.IDTIPOALTROPROCESSO 	    := chiaveUsageLista(J).IDTIPOALTROPROCESSO;
          V_CHIAVEUSAGERECORD.SISTEMAALTROPROCESSO 	    := chiaveUsageLista(J).SISTEMAALTROPROCESSO;
          V_CHIAVEUSAGERECORD.CODTIPOPROCINTERNO        := chiaveUsageLista(J).CODTIPOPROCINTERNO;
          V_CHIAVEUSAGERECORD.CODSISPROCINTERNO         := chiaveUsageLista(J).CODSISPROCINTERNO;
          V_CHIAVEUSAGERECORD.CODSISTEMA                := chiaveUsageLista(J).CODSISTEMA;
          V_CHIAVEUSAGERECORD.CODALTROPROC              := chiaveUsageLista(J).CODALTROPROC;
          V_CHIAVEUSAGERECORD.CANALE                    := chiaveUsageLista(J).CANALE;

          IF(COD_TIPO_PROC_INTERNO = 'ORD') THEN

            COD_TIPO_PROC_INTERNO := NULL;
            COD_SIS_PROC_INTERNO := NULL;

            V_CHIAVEUSAGERECORD.idTipoProcessoInterno := NULL;
            V_CHIAVEUSAGERECORD.sistemaProcessoInterno := NULL;

            idProcessoInterno_IN :=  NULL;
             V_CHIAVEUSAGERECORD.IDPROCESSOINTERNO := NULL;

          END IF;

          IF(COD_ALTRO_PROC ='ORD' ) THEN

            COD_ALTRO_PROC := NULL;
            COD_SISTEMA := NULL;

            V_CHIAVEUSAGERECORD.idTipoAltroProcesso := NULL;
            V_CHIAVEUSAGERECORD.sistemaAltroProcesso := NULL;
            V_CHIAVEUSAGERECORD.altroProcessoPrecedente := NULL;

            idAltroProcesso_IN := NULL;
            V_CHIAVEUSAGERECORD.IDALTROPROCESSO := NULL;

          END IF;
          IF(V_CHIAVEUSAGERECORD.IDPROCESSOINTERNO IS NOT NULL OR V_CHIAVEUSAGERECORD.IDALTROPROCESSO IS NOT NULL) THEN
            CHIAVEUSAGELISTAWORK(1) := V_CHIAVEUSAGERECORD;
          END IF;
       ELSE

          COD_TIPO_PROC_INTERNO := NULL;
          COD_SIS_PROC_INTERNO := NULL;
          COD_ALTRO_PROC := NULL;
          COD_SISTEMA := NULL;

          idProcessoInterno_IN :=  NULL;
          idAltroProcesso_IN := NULL;

       END IF;


        /*TRANSCODIFICHE PER R2*/
       COD_TIPO_PROD_TRACC_CORR_TRANS := PKG_UTILITY.transTipoTracciatura(sistemaSorgente, tipoProdTracciaturaCorrelata);
       COD_SIS_TRACCIATURA_CORR_TRANS := PKG_UTILITY.transCodiceSistemaTracciatura(sistemaSorgente, sistemaTracciaturaCorrelata);

       DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00020' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

      IF (idProcessoInterno_IN IS NULL AND idAltroProcesso_IN IS NULL AND idTracciatura IS NULL AND idTracciaturaCorrelata IS NULL )
      THEN /* SCARTO USAGE */
        esitoOperazione := 'OK';
        IDUSAGE := 0;

        l_end := dbms_utility.get_time ;  -- End Time
        logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - IDUSAGE: '||IDUSAGE, ADC_PKG_COMMON.DEBUG_LEVEL,TID);

        logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - END: (elapsed: '|| (L_END - L_START)/100 ||' s)', ADC_PKG_COMMON.INFO_LEVEL,TID);


      ELSE

        LOOP

            BEGIN

            INSERIMENTOUSAGE(
                IS_DEBUG_ENABLED => IS_DEBUG_ENABLED,
                TID => TID,
                INPUT_ID_FLUSSO => null,
                JOB_ID => null,
                INPUTIDUSAGE => null,
                DATAORAEVENTO => DATAORAEVENTO,
                FASECICLODIVITA => FASECICLODIVITA,
                SOTTOFASECICLODIVITA => SOTTOFASECICLODIVITA,
                CANALE => CANALE,
                SISTEMASORGENTE => SISTEMASORGENTE,
                CODICEPRODOTTOSERVIZIO => CODICEPRODOTTOSERVIZIO,
                COSTOPRODOTTOSERVIZIO => COSTOPRODOTTOSERVIZIO,
                METODOPAGAMENTOCLIENTE => METODOPAGAMENTOCLIENTE,
                ESITO => ESITO,
                --CHIAVEUSAGELISTA => CHIAVEUSAGELISTA,
                CHIAVEUSAGELISTA =>CHIAVEUSAGELISTAWORK,
                IDTRACCIATURA => IDTRACCIATURA,
                SISTEMATRACCIATURA => SISTEMATRACCIATURA,
                TIPOPRODOTTOTRACCIATURA => TIPOPRODOTTOTRACCIATURA,
                MOTIVOCONTATTO => MOTIVOCONTATTO,
                TIPOCLIENTEPAGAMENTO => TIPOCLIENTEPAGAMENTO,
                DATIAGGIUNTIVIUSAGE => DATIAGGIUNTIVIUSAGE,
                ANAGRAFICAUSAGE => ANAGRAFICAUSAGE,
                COMUNELUOGOEVENTO => COMUNELUOGOEVENTO,
                ALTROIDTRACCIATURA => ALTROIDTRACCIATURA,
                CODICEPTL => CODICEPTL,
                ZONAPTL => ZONAPTL,
                FRAZACCETTAZIONE => FRAZACCETTAZIONE,
                FRAZDESTINATARIO => FRAZDESTINATARIO,
                PROVINCIALUOGOEVENTO => PROVINCIALUOGOEVENTO,
                FILIALESDA => FILIALESDA,
                SERVIACCESSORI => SERVIACCESSORI,

                ID_FASE => ID_FASE_TRANS,
                ID_SOTTOFASE => ID_SOTTOFASE_TRANS,
                ID_METODO_PAGAMENTO_CLIENTE => ID_METODO_PAGAMENTO_CLIENTE,
                COD_TIPO_PROCESSO => COD_TIPO_PROC_INTERNO,
                COD_SISTEMA_PROCESSO => COD_SIS_PROC_INTERNO,
                COD_TIPO_TRACCIATURA => COD_TIPO_PROD_TRACC_TRANS,
                COD_SISTEMA_TRACCIATURA => COD_SIS_TRACCIATURA_TRANS,
                COD_SISTEMA_ALTROP => COD_SISTEMA,
                COD_TIPO_ALTROP => COD_ALTRO_PROC,
                ID_PROD_SERVIZIO => CODICE_PRODOTTO_SERVIZIO_TRANS,
                ID_CANALE => ID_CANALE_TRANS,
                ID_TIPO_CLIENTE_PAGAMENTO => ID_TIPO_CLIENTE_PAGAMENTO,

                ID_PROCESSO => null,
                VENDITA => null,
                NFEA_DETTAGLIO_A_CHIAMATA => null,
                NFEA_DETTAGLIO_B_CHIAMATA => null,
                NFEA_SITO_CC => null,
                NFEA_FORNITORE_CC => null,
                NFEA_TEAM => null,
                NFEA_LOGIN => null,
                FRAZIONARIO_UP => null,
                NOME_UP => null,
                CITTA_LUOGO_EVENTO => null,
                ALT => null,
                RAM => null,
                CD => null,
                ZONA => null,
                TIPOLOGIA_ASSISTENZA => null,
                ID_TRACC_CORR => idTracciaturaCorrelata,
                TIPO_PROD_TRACC_CORR => tipoProdTracciaturaCorrelata,
                SIST_TRACC_CORR => sistemaTracciaturaCorrelata,
                COD_TIPO_PROD_TRACC_CORR => COD_TIPO_PROD_TRACC_CORR_TRANS,
                COD_SIST_TRACC_CORR => COD_SIS_TRACCIATURA_CORR_TRANS,

                ESITOOPERAZIONE => ESITOOPERAZIONE,
                IDUSAGE => IDUSAGE,
                MSGTYPE => null,
                NUMERO_TENTATIVI_CONS => null,
                QUALIFICA  => null,
                SOURCE_TIPOLOGIA_ASSISTENZA => NULL
              );
              exit;
              EXCEPTION

               WHEN lock_detected THEN

                  logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - ERROR: lock_detected', ADC_PKG_COMMON.ERROR_LEVEL,TID);

                  ROLLBACK;

                  BEGIN
                    select valore into maxRetry from ADC_SYS_CONFIG where chiave = 'MAX_RETRY';
                    EXCEPTION WHEN NO_DATA_FOUND THEN
                    maxRetry :=3;
                  END;
                  BEGIN
                    select valore into sleep_sec from ADC_SYS_CONFIG where chiave = 'SLEEP_SEC';
                    EXCEPTION WHEN NO_DATA_FOUND THEN
                    sleep_sec :=2;
                  END;

                IF(retryCount = maxRetry) then
                  logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - RETRY - Massimo Tentativi Raggiunto', ADC_PKG_COMMON.INFO_LEVEL,TID);
                  DBMS_OUTPUT.PUT_LINE('RETRY - Massimo Tentativi Raggiunto'||retryCount);
                  esitoOperazione := '1';
                  ERROR_MESSAGE :=  'Errore interno';
                  exit;
                ELSE
                  retryCount := retryCount+1;
                  logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - RETRY - Tentativo n '||retryCount, ADC_PKG_COMMON.INFO_LEVEL,TID);
                  DBMS_OUTPUT.PUT_LINE('RETRY - Tentativo n '||retryCount);
                  dbms_lock.sleep(sleep_sec);

               END IF;

               WHEN OTHERS THEN
               pkg_mapping_error.ricercaMappingErrore(
                  messaggio => TRIM(substr(sqlerrm,INSTR(sqlerrm,':')+1)),
                  codice => esitoOperazione,
                  DESCRIZIONE => ERROR_MESSAGE
              );



              l_end := dbms_utility.get_time ;  -- Start Time

                if(esitoOperazione IS null) then
                  esitoOperazione := '1';
                  ERROR_MESSAGE := 'Errore interno';

                 logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - ERROR: ('|| sqlerrm ||') - (elapsed: '|| (l_end - l_start)/100 ||' s)', ADC_PKG_COMMON.ERROR_LEVEL,TID);
                else
                  logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - ERROR: ('|| esitoOperazione ||':' || ERROR_MESSAGE ||') - (elapsed: '|| (l_end - l_start)/100 ||' s)', ADC_PKG_COMMON.ERROR_LEVEL,TID);
                end if;

              ROLLBACK;
              exit;
            END;

        END LOOP;

          IF( esitoOperazione = 'OK') THEN

            esitoOperazione := esitoOperazione;
            IDUSAGE := IDUSAGE;
            l_end := dbms_utility.get_time ;  -- End Time
            logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - END: (elapsed: '|| (L_END - L_START)/100 ||' s)', ADC_PKG_COMMON.INFO_LEVEL,TID);
          end if;

      END IF;

    EXCEPTION WHEN OTHERS THEN
    logResult := ADC_PKG_COMMON.LOGGER('USAGE', 'INSERIMENTOUSAGEONLINE - ERROR: ('|| sqlerrm ||') - (elapsed: '|| (l_end - l_start)/100 ||' s)', ADC_PKG_COMMON.ERROR_LEVEL,TID);
        raise;
    end;
  ADC_PKG_COMMON.FLUSH_LOGGER(DIAGNOSTIC_LN);

END;

PROCEDURE INSERIMENTOUSAGE(
    IS_DEBUG_ENABLED  BOOLEAN,
    TID VARCHAR2,
    INPUT_ID_FLUSSO NUMBER,
    JOB_ID NUMBER,
    inputIdUsage NUMBER,
    dataOraEvento TIMESTAMP,
    faseCicloDiVita VARCHAR2,
    sottoFaseCicloDiVita VARCHAR2,
    canale VARCHAR2,
    sistemaSorgente VARCHAR2 ,
    codiceProdottoServizio CODICEPRODOTTOSERVIZIO_TABLE,
    costoProdottoServizio VARCHAR2,
    metodoPagamentoCliente VARCHAR2,
    esito VARCHAR2,
    chiaveUsageLista CHIAVEUSAGE_TABLE,
    idTracciatura VARCHAR2,
    sistemaTracciatura VARCHAR2,
    tipoProdottoTracciatura VARCHAR2,
    motivoContatto VARCHAR2,
    tipoClientePagamento VARCHAR2,
    datiAggiuntiviUsage DATIAGGIUNTIVI_TABLE,
    anagraficaUsage DATIANAGRAFICI_TABLE,
    ComuneLuogoEvento VARCHAR2,
    AltroIdTracciatura VARCHAR2,
    CodicePTL VARCHAR2,
    ZonaPTL VARCHAR2,
    FrazAccettazione VARCHAR2,
    FrazDestinatario VARCHAR2,
    ProvinciaLuogoEvento VARCHAR2,
    FilialeSDA VARCHAR2,
    SERVIACCESSORI SERVIZIACCESSORI_TABLE,

    ID_FASE NUMBER,
    ID_SOTTOFASE NUMBER,
    ID_METODO_PAGAMENTO_CLIENTE VARCHAR2,
    COD_TIPO_PROCESSO VARCHAR2,
    COD_SISTEMA_PROCESSO VARCHAR2,
    COD_TIPO_TRACCIATURA VARCHAR2,
    COD_SISTEMA_TRACCIATURA VARCHAR2,
    COD_SISTEMA_ALTROP VARCHAR2,
    COD_TIPO_ALTROP VARCHAR2,
    ID_PROD_SERVIZIO VARCHAR2,
    ID_CANALE NUMBER,
    ID_TIPO_CLIENTE_PAGAMENTO VARCHAR2,
    ID_PROCESSO VARCHAR2,
    VENDITA VARCHAR2,
    NFEA_DETTAGLIO_A_CHIAMATA VARCHAR2,
    NFEA_DETTAGLIO_B_CHIAMATA VARCHAR2,
    NFEA_SITO_CC VARCHAR2,
    NFEA_FORNITORE_CC VARCHAR2,
    NFEA_TEAM VARCHAR2,
    NFEA_LOGIN VARCHAR2,
    FRAZIONARIO_UP VARCHAR2,
    NOME_UP VARCHAR2,
    CITTA_LUOGO_EVENTO VARCHAR2,
    ALT VARCHAR2,
    RAM VARCHAR2,
    CD VARCHAR2,
    ZONA VARCHAR2,
    TIPOLOGIA_ASSISTENZA VARCHAR2,
    ID_TRACC_CORR VARCHAR2,
    TIPO_PROD_TRACC_CORR VARCHAR2,
    SIST_TRACC_CORR VARCHAR2,
    COD_TIPO_PROD_TRACC_CORR VARCHAR2,
    COD_SIST_TRACC_CORR VARCHAR2,

    esitoOperazione OUT VARCHAR2,
    idUsage OUT NUMBER,
    MSGTYPE VARCHAR2,
    NUMERO_TENTATIVI_CONS NUMBER,
    QUALIFICA  VARCHAR2,
    SOURCE_TIPOLOGIA_ASSISTENZA VARCHAR2

) IS
      rigaUsage                           ADC_WRK_USAGE%ROWTYPE;
      rigaDatiAggiuntiviUsage             ADC_WRK_DATI_AGG%ROWTYPE;
      rigaDatiAggiuntiviAnagrafica        ADC_WRK_ANAG_DATI_AGG%ROWTYPE;

      rigaChiavi              ADC_WRK_CHIAVI%ROWTYPE;
      --rigaProdServizio ADC_USAGE_PROD_SERVIZIO%ROWTYPE;
      RIGAPRODOTTO            ADC_WRK_COD_PROD_SERV%ROWTYPE;
      RIGAANAGRAFICA          ADC_USAGE_ANAGRAFICA%ROWTYPE;
      RIGAANAGRAFICATRAC      ADC_USAGE_ANAGRAFICA%ROWTYPE;
      rigaAnagrafica2         ADC_USAGE_ANAGRAFICA%ROWTYPE;
      idAnagrafica            NUMBER;
      idRuolo                 NUMBER;
      appAggiuntivi           DATIAGGIUNTIVI_TABLE;
      cnt                     NUMBER;
      j                       PLS_INTEGER;
      i                       PLS_INTEGER;
      /* Modifiche per dati Usage per rilascio 19/02 */
      k PLS_INTEGER;
      appSerAccessori         SERVIZIACCESSORI_TABLE;

      rigaUSAGE_SA            ADC_USAGE_SERVIZI_ACCESSORI%ROWTYPE;

      COUNT_CORRELAZIONI_ANAGRAFICA NUMBER;

      LOGRESULT                   NUMBER;
      L_START                     NUMBER;
      L_END                       NUMBER;
      V_ID_TRACCIATURA            NUMBER;
      ADC_RANGE_USAGE_ROW         ADC_RANGE_USAGE%ROWTYPE;
      ADC_RANGE_TRACCIATURE_ROW   ADC_RANGE_TRACCIATURE%ROWTYPE;
      V_PIVA_CORRENTE             VARCHAR2(255);
      V_RAGIONE_SOCIALE           VARCHAR2(255);
      V_CF_CORRENTE               VARCHAR2(255);

      V_RUOLO_ANAGRAFICA          VARCHAR2(255);
      V_CODICE_CLIENTE_SORGENTE   VARCHAR2(255);
      V_COD_SAP                   VARCHAR2(255);
      V_CF_CORRENTE_2COMM         VARCHAR2(255);
      V_PIVA_CORR_2COMM           VARCHAR2(255);
      V_RAG_SOC_2COMM             VARCHAR2(255);
      V_ID_ANAG_BASE_2COMM        VARCHAR2(255);

      --diagnostic variables
      DIAGNOSTIC_CODE VARCHAR2(512):='IU4001';
      DIAGNOSTIC_LN VARCHAR2(512):=ADC_PKG_LOAD_USAGE.DIAGNOSTIC_LOGGER_NAME;
      DIAGNOSTIC_INFO_LEVEL VARCHAR2(512):=ADC_PKG_COMMON.INFO_LEVEL;
      DIAGNOSTIC_RESULT NUMBER;

      add_SA BOOLEAN;

      NOME_SA_TO_ADD VARCHAR2(255);
      VALORE_SA_TO_ADD VARCHAR2(255);
      ID_COD_SA_TO_ADD VARCHAR2(255);
      rigaUSAGE_SA_TO_ADD ADC_USAGE_SERVIZI_ACCESSORI%ROWTYPE;

      BEGIN

          L_START := DBMS_UTILITY.GET_TIME ;  -- Start Time
          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  inputIdUsage || ') BEGIN'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
          DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
          IF dataOraEvento IS NULL THEN
              raise_application_error (-20001,'DATA_USAGE_MANCANTE');
          END IF;

          IF faseCicloDiVita IS NULL THEN
              raise_application_error (-20001,'FASE_VITA_MANCANTE');
          END IF;

          IF sistemaSorgente IS NULL THEN
              raise_application_error (-20001,'SISTEMA_USAGE_MANCANTE');
          END IF;

          RIGAUSAGE.ID := inputIdUsage;
          RIGAUSAGE.DATA_ORA_EVENTO := DATAORAEVENTO;
          RIGAUSAGE.FASE_CICLO_VITA := FASECICLODIVITA;
          --Transcodificato prima: rigaUsage.ID_FASE := ID_FASE;
          RIGAUSAGE.ID_FASE := ID_FASE;
          RIGAUSAGE.SOTTO_FASE_CICLO_VITA := SOTTOFASECICLODIVITA;
          --Transcodificato prima: RIGAUSAGE.ID_SOTTOFASE := PKG_UTILITY.TRANSSOTTOFASECICLOVITA(SISTEMASORGENTE, SOTTOFASECICLODIVITA);
          RIGAUSAGE.ID_SOTTOFASE := ID_SOTTOFASE;

          IF MSGTYPE='BE' AND NUMERO_TENTATIVI_CONS>0 AND FASECICLODIVITA='CON' AND sistemaSorgente='TT' AND CANALE='TT' THEN
              RIGAUSAGE.CANALE := 'PTL';
              RIGAUSAGE.ID_CANALE := 5;
          ELSE
              --Transcodificato prima: rigaUsage.CANALE := canale;  -- TRANSCODIFICATO IN ACCODAMENTO
              RIGAUSAGE.CANALE := CANALE;
              --Transcodificato prima: RIGAUSAGE.ID_CANALE := ADC_PKG_USAGE_UTILITY.TRANSCANALEUSAGE(SISTEMASORGENTE, CANALE);
              RIGAUSAGE.ID_CANALE := ID_CANALE;
          END IF;

          rigaUsage.SISTEMA_SORGENTE := sistemaSorgente;
          RIGAUSAGE.COSTO_PRODOTTO_SERVIZIO := COSTOPRODOTTOSERVIZIO;
          --Transcodificato prima:
          RIGAUSAGE.METODO_PAGAMENTO_CLIENTE := METODOPAGAMENTOCLIENTE;-- TRANSCODIFICATO IN ACCODAMENTO
          --Transcodificato prima:
          RIGAUSAGE.ID_METODO_PAGAMENTO_CLIENTE :=ID_METODO_PAGAMENTO_CLIENTE;-- TRANSCODIFICATO IN ACCODAMENTO
          rigaUsage.ESITO := esito;
          RIGAUSAGE.MOTIVO_CONTATTO := MOTIVOCONTATTO;
          --Transcodificato prima:
          RIGAUSAGE.TIPO_CLIENTE_PAGAMENTO := TIPOCLIENTEPAGAMENTO;-- TRANSCODIFICATO IN ACCODAMENTO
          RIGAUSAGE.ID_TIPO_CLIENTE_PAGAMENTO :=ID_TIPO_CLIENTE_PAGAMENTO; -- TRANSCODIFICATO IN ACCODAMENTO
          rigaUsage.ID_TRACCIATURA := UPPER(idTracciatura); --#88
          RIGAUSAGE.TIPO_PRODOTTO_TRACCIATURA := TIPOPRODOTTOTRACCIATURA;
          --Transcodificato prima:rigaUsage.COD_TIPO_PROD_TRACC := PKG_UTILITY.transTipoTracciatura(sistemaSorgente, tipoProdottoTracciatura);
          RIGAUSAGE.COD_TIPO_PROD_TRACC := COD_TIPO_TRACCIATURA;
          rigaUsage.SISTEMA_TRACCIATURA := sistemaTracciatura;
          --Transcodificato prima: rigaUsage.COD_SIS_TRACCIATURA := PKG_UTILITY.transCodiceSistemaTracciatura(sistemaSorgente, sistemaTracciatura);
          rigaUsage.COD_SIS_TRACCIATURA := COD_SISTEMA_TRACCIATURA;
          rigaUsage.ID_PROCESSO := ID_PROCESSO;
          RIGAUSAGE.COMUNE_LUOGO_EVENTO   := COMUNELUOGOEVENTO    ;
          rigaUsage.altro_id_tracciatura  := UPPER(altroIdTracciatura)   ; --#88
          rigaUsage.codice_ptl            := CodicePTL            ;
          rigaUsage.zona_ptl              := ZonaPTL              ;
          rigaUsage.fraz_acc              := FrazAccettazione     ;
          RIGAUSAGE.FRAZ_DST              := FRAZDESTINATARIO     ;
          RIGAUSAGE.PROVINCIA_LUOGO_EVENTO:= PROVINCIALUOGOEVENTO ;
          RIGAUSAGE.FILIALE_SDA           := FILIALESDA           ;
          RIGAUSAGE.ID_FLUSSO             := INPUT_ID_FLUSSO;
          rigaUsage.DATA_INSERIMENTO := CURRENT_TIMESTAMP; --#MM_0329_01
          rigaUsage.ID_PRODOTTO_SERVIZIO := ID_PROD_SERVIZIO;
          rigaUsage.VENDITA := VENDITA;
          rigaUsage.NFEA_DETTAGLIO_A_CHIAMATA := NFEA_DETTAGLIO_A_CHIAMATA;
          rigaUsage.NFEA_DETTAGLIO_B_CHIAMATA := NFEA_DETTAGLIO_B_CHIAMATA;
          rigaUsage.NFEA_SITO_CC := NFEA_SITO_CC;
          rigaUsage.NFEA_FORNITORE_CC := NFEA_FORNITORE_CC;
          rigaUsage.NFEA_TEAM := NFEA_TEAM;
          rigaUsage.NFEA_LOGIN := NFEA_LOGIN;
          rigaUsage.FRAZIONARIO_UP := FRAZIONARIO_UP;
          rigaUsage.NOME_UP := NOME_UP;
          rigaUsage.CITTA_LUOGO_EVENTO := CITTA_LUOGO_EVENTO;
          rigaUsage.ALT := ALT;
          rigaUsage.RAM := RAM;
          rigaUsage.CD := CD;
          rigaUsage.ZONA := ZONA;
          RIGAUSAGE.TIPOLOGIA_ASSISTENZA  := TIPOLOGIA_ASSISTENZA;
          rigaUsage.ID_TRACC_CORR := UPPER(ID_TRACC_CORR); --#88
          rigaUsage.TIPO_PROD_TRACC_CORR := TIPO_PROD_TRACC_CORR;
          rigaUsage.SIST_TRACC_CORR := SIST_TRACC_CORR;
          --Transcodificato prima:
          rigaUsage.COD_TIPO_PROD_TRACC_CORR := COD_TIPO_PROD_TRACC_CORR;
          --Transcodificato prima:
          rigaUsage.COD_SIST_TRACC_CORR := COD_SIST_TRACC_CORR;

          IF SOURCE_TIPOLOGIA_ASSISTENZA IS NOT NULL THEN
            rigaUsage.TIPOLOGIA_ASSISTENZA_ORIG := SOURCE_TIPOLOGIA_ASSISTENZA;
          END IF;

          DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

          DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00020' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

          /* RICERCA USAGE DUPLICATO {#54} */
          IF(INPUT_ID_FLUSSO IS NULL)THEN
            CERCA_USAGE_DUPLICATO(RIGAUSAGE, CHIAVEUSAGELISTA,TID, IS_DEBUG_ENABLED, IDUSAGE);
          ELSE
            IDUSAGE := NULL;
          END IF;
          DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00020' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

          IF(idUsage IS NULL) THEN

              DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00030' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

              idUsage := ADC_PKG_LOAD_USAGE.insertUsage(IS_DEBUG_ENABLED,rigaUsage, TID);

              DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00030' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
              IF ( rigaUsage.ID_TRACCIATURA IS NOT NULL ) THEN
                  PKG_USAGE_CORRELAZIONE.ProcPerTracciatura(rigaUsage, idUsage);
              END IF;

              IF ( rigaUsage.ID_TRACC_CORR IS NOT NULL ) THEN
                  PKG_USAGE_CORRELAZIONE.ProcPerTracciaturaCorrelata(rigaUsage, idUsage);
              END IF;

              DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00040' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
              -- Codici prodotti per popolamento WRK_COD_PROD_SERV

              J := CODICEPRODOTTOSERVIZIO.FIRST;

              WHILE J IS NOT NULL LOOP

                  RIGAPRODOTTO.CODICE_PRODOTTO_SERVIZIO := CODICEPRODOTTOSERVIZIO(J).CODICE;
                  --Transcodificato prima: RIGAPRODOTTO.CODICE_PRODOTTO_SERVIZIO_TRANS := PKG_UTILITY.TRANSCODICEPRODOTTOSERVIZIO(SISTEMASORGENTE, CODICEPRODOTTOSERVIZIO(J).CODICE);
                  RIGAPRODOTTO.CODICE_PRODOTTO_SERVIZIO_TRANS := ID_PROD_SERVIZIO;
                  RIGAPRODOTTO.ID_USAGE := idUsage;

                  --DBMS_OUTPUT.PUT_LINE(SISTEMASORGENTE || '-->' || CODICEPRODOTTOSERVIZIO(J).CODICE || '-->' || RIGAPRODOTTO.CODICE_PRODOTTO_SERVIZIO_TRANS);

                  IF ( RIGAPRODOTTO.CODICE_PRODOTTO_SERVIZIO_TRANS IS NOT NULL ) THEN
                      RIGAPRODOTTO.FAMIGLIA_PRODOTTO_SERVIZIO := PKG_UTILITY.GETFAMIGLIAPRODOTTOSERVIZIO(RIGAPRODOTTO.CODICE_PRODOTTO_SERVIZIO_TRANS);
                  END IF;

                 ADC_PKG_USAGE_UTILITY.INSERTPRODOTTO(IS_DEBUG_ENABLED, RIGAPRODOTTO, TID);

                 --PKG_USAGE_UTILITY.insertProdServizio(rigaProdServizio);

                  J := CODICEPRODOTTOSERVIZIO.NEXT(J);

              END LOOP;

              -- chiaveUsageLista
              j := chiaveUsageLista.FIRST;

              WHILE j IS NOT NULL LOOP

                  rigaChiavi.ID := NULL;
                  rigaChiavi.ID_USAGE := idUsage;
                  -- chiaveInterna
                  rigaChiavi.ID_PROCESSO_INTERNO := chiaveUsageLista(j).idProcessoInterno;
                  rigaChiavi.ID_TIPO_PROCESSO_INTERNO := chiaveUsageLista(j).idTipoProcessoInterno;

                  --rigaChiavi.COD_TIPO_PROC_INTERNO := PKG_UTILITY.transTipoProcessoInterno(sistemaSorgente, chiaveUsageLista(j).idTipoProcessoInterno);
                  rigaChiavi.COD_TIPO_PROC_INTERNO := COD_TIPO_PROCESSO;
                  RIGACHIAVI.SISTEMA_PROCESSO_INTERNO := CHIAVEUSAGELISTA(J).SISTEMAPROCESSOINTERNO;
                  --rigaChiavi.COD_SIS_PROC_INTERNO := PKG_UTILITY.transSistemaProcessoInterno(sistemaSorgente, chiaveUsageLista(j).sistemaProcessoInterno);
                  rigaChiavi.COD_SIS_PROC_INTERNO := COD_SISTEMA_PROCESSO;

                  -- chiaveAltroProcesso
                  rigaChiavi.ID_ALTRO_PROCESSO := chiaveUsageLista(j).idAltroProcesso;
                  rigaChiavi.ALTRO_PROCESSO_PRECEDENTE := chiaveUsageLista(j).altroProcessoPrecedente;
                  rigaChiavi.ID_TIPO_ALTRO_PROCESSO := chiaveUsageLista(j).idTipoAltroProcesso;

                  --rigaChiavi.COD_ALTRO_PROC := PKG_UTILITY.transTipoProcessoInterno(sistemaSorgente, chiaveUsageLista(j).idTipoAltroProcesso);
                  rigaChiavi.COD_ALTRO_PROC := COD_TIPO_ALTROP;
                  rigaChiavi.SISTEMA_ALTRO_PROCESSO := chiaveUsageLista(j).sistemaAltroProcesso;

                  --rigaChiavi.COD_SISTEMA := PKG_UTILITY.transSistemaProcessoInterno(sistemaSorgente, chiaveUsageLista(j).sistemaAltroProcesso);
                  rigaChiavi.COD_SISTEMA := COD_SISTEMA_ALTROP;
                  rigaChiavi.CANALE := chiaveUsageLista(j).canale;

                  /* DBMS_OUTPUT.PUT_LINE(rigaChiavi.ID || '-->'
                      || RIGACHIAVI.ID_USAGE  || '-->'
                      ||RIGACHIAVI.ID_PROCESSO_INTERNO|| '-->'
                      ||rigaChiavi.ID_TIPO_PROCESSO_INTERNO|| '-->'
                      ||rigaChiavi.COD_TIPO_PROC_INTERNO|| '-->'
                      ||RIGACHIAVI.SISTEMA_PROCESSO_INTERNO|| '-->'
                      ||RIGACHIAVI.COD_SIS_PROC_INTERNO|| '-->'
                      ||RIGACHIAVI.ID_ALTRO_PROCESSO|| '-->'
                      ||RIGACHIAVI.ALTRO_PROCESSO_PRECEDENTE|| '-->'
                      ||RIGACHIAVI.ID_TIPO_ALTRO_PROCESSO|| '-->'
                      ||RIGACHIAVI.COD_ALTRO_PROC|| '-->'
                      ||RIGACHIAVI.SISTEMA_ALTRO_PROCESSO|| '-->'
                      ||RIGACHIAVI.COD_SISTEMA
                      ); */

                  ADC_PKG_USAGE_UTILITY.INSERTCHIAVI(IS_DEBUG_ENABLED, RIGACHIAVI, TID);

                  IF ( rigaChiavi.ID_PROCESSO_INTERNO IS NOT NULL ) THEN
                      PKG_USAGE_CORRELAZIONE.ProcPerChiaveInterna(rigaChiavi);
                  END IF;

                  IF ( rigaChiavi.ID_ALTRO_PROCESSO IS NOT NULL ) THEN
                      PKG_USAGE_CORRELAZIONE.ProcPerChiaveAltroProcesso(rigaChiavi);
                  END IF;

                  j := chiaveUsageLista.NEXT(j);

              END LOOP;

              -- datiAggiuntiviUsage
              j := datiAggiuntiviUsage.FIRST;

              WHILE j IS NOT NULL LOOP

                  rigaDatiAggiuntiviUsage.ID := NULL;
                  rigaDatiAggiuntiviUsage.ID_USAGE := idUsage;
                  rigaDatiAggiuntiviUsage.CHIAVE := datiAggiuntiviUsage(j).chiave;
                  rigaDatiAggiuntiviUsage.VALORE := datiAggiuntiviUsage(j).valore;

                  ADC_PKG_USAGE_UTILITY.insertDatiAggiuntiviUsage(IS_DEBUG_ENABLED, rigaDatiAggiuntiviUsage, TID);

                  j := datiAggiuntiviUsage.NEXT(j);

              END LOOP;

              --raise_application_error (-20001,idRuolo);
              -- anagraficaUsage + Dati aggiuntivi
              j := anagraficaUsage.FIRST;

              COUNT_CORRELAZIONI_ANAGRAFICA := 0;

              WHILE j IS NOT NULL LOOP

                  IF( anagraficaUsage(j).tipoRuolo IS NULL ) THEN
                       raise_application_error (-20001,'ANAGRAFICA_NO_RUOLO');
                  END IF;

                  BEGIN
                      -- DBMS_OUTPUT.PUT_LINE('TOGLIERE -->' || anagraficaUsage(j).tipoRuolo);
                      select /* ADC_PKG_LOAD_USAGE_S41 */ ID INTO idRuolo from ADC_TIP_USAGE_RUOLI where ruolo = anagraficaUsage(j).tipoRuolo;

                  EXCEPTION
                      WHEN NO_DATA_FOUND THEN
                          --Dbms_Output.Put_Line('Ricerca cliente - NO DATA');
                          RAISE_APPLICATION_ERROR(-20001,'USAGE_RUOLO_NO_VALID');

                  END;

                 BEGIN

                  rigaAnagrafica.ID := NULL;
                  rigaAnagrafica.CODICE_FISCALE := UPPER(anagraficaUsage(j).cf);
                  rigaAnagrafica.CODICE_NAZIONE_FISCALE := anagraficaUsage(j).cnf;
                  rigaAnagrafica.PIVA := UPPER(anagraficaUsage(j).piva);
                  rigaAnagrafica.CODICE_NAZIONE_PIVA := anagraficaUsage(j).cnPiva;
                  rigaAnagrafica.SISTEMA_CODICE_NON_FISCALE := anagraficaUsage(j).sistemaCodiceNonFiscale;
                  rigaAnagrafica.CODICE_CLIENTE_NON_FISCALE := anagraficaUsage(j).codiceClienteNonFiscale;
                  rigaAnagrafica.NOME := anagraficaUsage(j).nome;
                  rigaAnagrafica.COGNOME := anagraficaUsage(j).cognome;
                  rigaAnagrafica.INDIR_PARTICELLA_TOPONOMASTICA := anagraficaUsage(j).particellaToponomastica;
                  rigaAnagrafica.INDIRIZZO := anagraficaUsage(j).indirizzo;
                  rigaAnagrafica.NUMERO_CIVICO := anagraficaUsage(j).numeroCivico;
                  rigaAnagrafica.CAP := anagraficaUsage(j).cap;
                  rigaAnagrafica.COMUNE := anagraficaUsage(j).comune;
                  rigaAnagrafica.PROVINCIA := anagraficaUsage(j).provincia;
                  rigaAnagrafica.STATO := anagraficaUsage(j).stato;
                  rigaAnagrafica.ID_ANAGRAFICA_BASE := NULL;
                  rigaAnagrafica.ID_RUOLO := idRuolo;
                  rigaAnagrafica.ID_USAGE := idUsage;
                  rigaAnagrafica.COD_NAZIONALE_FIS := anagraficaUsage(j).codiceNazionaleFis;
                  rigaAnagrafica.CN_PIVA := anagraficaUsage(j).codiceNazionalePiva;
                  /* Modifiche per dati Usage per rilascio 19/02 */
                  rigaAnagrafica.MAIL := anagraficaUsage(j).mail;
                  RIGAANAGRAFICA.TELEFONO := ANAGRAFICAUSAGE(J).TELEFONO;
                  rigaAnagrafica.USAGE_PROCESSED := 1;

                  IF(
                      (rigaAnagrafica.CODICE_FISCALE IS NULL AND rigaAnagrafica.CODICE_NAZIONE_FISCALE IS NULL AND rigaAnagrafica.PIVA IS NULL AND
                      RIGAANAGRAFICA.CODICE_NAZIONE_PIVA IS NULL AND rigaAnagrafica.SISTEMA_CODICE_NON_FISCALE IS NULL AND
                      RIGAANAGRAFICA.CODICE_CLIENTE_NON_FISCALE IS NULL AND rigaAnagrafica.NOME IS NULL AND rigaAnagrafica.COGNOME IS NULL AND
                      RIGAANAGRAFICA.INDIR_PARTICELLA_TOPONOMASTICA IS NULL AND rigaAnagrafica.INDIRIZZO IS NULL AND
                      RIGAANAGRAFICA.NUMERO_CIVICO IS NULL AND rigaAnagrafica.CAP IS NULL AND rigaAnagrafica.COMUNE IS NULL AND
                      RIGAANAGRAFICA.PROVINCIA  IS NULL AND RIGAANAGRAFICA.STATO IS NULL AND rigaAnagrafica.COD_NAZIONALE_FIS IS NULL AND
                      rigaAnagrafica.CN_PIVA IS NULL AND rigaAnagrafica.MAIL IS NULL AND rigaAnagrafica.TELEFONO IS NULL) OR
                      (rigaAnagrafica.CODICE_FISCALE IS NULL AND rigaAnagrafica.PIVA IS NULL AND RIGAANAGRAFICA.CODICE_CLIENTE_NON_FISCALE IS NULL AND
                       rigaAnagrafica.MAIL IS NULL AND rigaAnagrafica.TELEFONO IS NULL AND ((rigaAnagrafica.INDIRIZZO IS NULL) OR (rigaAnagrafica.INDIRIZZO IS NOT NULL AND (rigaAnagrafica.NOME IS NULL AND rigaAnagrafica.COGNOME IS NULL)))
                      )
                  )
                  THEN

                      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  inputIdUsage || ') - SKIP ANAGRAFICA '  , ADC_PKG_COMMON.DEBUG_LEVEL ,TID,IS_DEBUG_ENABLED);
                      -- RAISE_APPLICATION_ERROR(-20001,'SKIP ANAGRAFICA');

                  ELSE

                      IF(( RIGAANAGRAFICA.CODICE_CLIENTE_NON_FISCALE IS NOT NULL AND RIGAANAGRAFICA.SISTEMA_CODICE_NON_FISCALE IS NOT NULL) OR
                      (RIGAANAGRAFICA.CODICE_FISCALE IS NOT NULL OR RIGAANAGRAFICA.PIVA IS NOT NULL)) THEN

                          ADC_PKG_LOAD_USAGE.GETIDAGRAFICABASE(IS_DEBUG_ENABLED,RIGAANAGRAFICA, TID, rigaAnagrafica.ID_ANAGRAFICA_BASE, V_CF_CORRENTE, rigaAnagrafica.NOME, rigaAnagrafica.COGNOME);

                          IF(sistemaSorgente = 'NFEA' AND rigaAnagrafica.ID_ANAGRAFICA_BASE IS NOT NULL AND FASECICLODIVITA='ASS' AND SOTTOFASECICLODIVITA='ZTICE0001'
                                                AND TIPOLOGIA_ASSISTENZA='2') THEN

                            UPDATE /* ADC_PKG_LOAD_USAGE_U26 */ ADC_ANAGRAFICA_DB_ZONA SET VARIAZIONE = 1, DATA_ULTIMA_VARIAZIONE = SYSTIMESTAMP, DATA_ORA_EVENTO_USAGE = DATAORAEVENTO
                            WHERE ID_ANAGRAFICA_BASE = rigaAnagrafica.ID_ANAGRAFICA_BASE;

                            INSERT INTO ADC_DB_ZONA_ANAG_TO_EXPORT (ID_ANAGRAFICA_BASE, IN_LAVORAZIONE) VALUES (rigaAnagrafica.ID_ANAGRAFICA_BASE,0);

                            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  inputIdUsage || ') - SET VARIAZIONE ANAGRAFICA DBZONA DA NFEA'  , ADC_PKG_COMMON.DEBUG_LEVEL ,TID,IS_DEBUG_ENABLED);


                          END IF;

                      END IF;

                      IDANAGRAFICA := ADC_PKG_USAGE_UTILITY.INSERTANAGRAFICAUSAGE(IS_DEBUG_ENABLED,RIGAANAGRAFICA, TID);

                  END IF;

                 /*
                 QUESTO BLOCCO E' STATO SOSTITUITO CON LA PROCEDURA CHE INDIVIDUA L'ID_ANAGRAFICA_BASE PRIMA DELL'INSERT.
                 IN PARTICOLARE LA CORRELAZIONEANAGRAFICHE VA IN DEADLOCK PER INSERIMENTI PARALLELI

                 IF(( RIGAANAGRAFICA.CODICE_CLIENTE_NON_FISCALE IS NOT NULL AND RIGAANAGRAFICA.SISTEMA_CODICE_NON_FISCALE IS NOT NULL) OR
                    (rigaAnagrafica.CODICE_FISCALE IS NOT NULL OR rigaAnagrafica.PIVA IS NOT NULL)) THEN

                      Dbms_Output.Put_Line(CURRENT_TIMESTAMP || ' PRIMA PKG_USAGE_CORRELAZIONE.COUNT_CORRELAZIONI_ANAGRAFICA(idUsage);');
                      -- IF (COUNT_CORRELAZIONI_ANAGRAFICA > 0) THEN
                      ADC_PKG_LOAD_USAGE.CORRELAZIONEANAGRAFICHE(IDANAGRAFICA, RIGAANAGRAFICA, TID);
                      --END IF;
                      --COUNT_CORRELAZIONI_ANAGRAFICA :=  COUNT_CORRELAZIONI_ANAGRAFICA + 1;

                  END IF;*/
                  -- DBMS_OUTPUT.PUT_LINE(CURRENT_TIMESTAMP || ' DOPO PKG_USAGE_CORRELAZIONE.COUNT_CORRELAZIONI_ANAGRAFICA(idUsage);');

                  appAggiuntivi := anagraficaUsage(j).altro;

                  -- dati aggiuntivi anagrafica che nella componente Batch
                  i := appAggiuntivi.FIRST;

                  WHILE I IS NOT NULL LOOP

                      rigaDatiAggiuntiviAnagrafica.ID := NULL;
                      rigaDatiAggiuntiviAnagrafica.ID_ANAG_USAGE := idAnagrafica;
                      rigaDatiAggiuntiviAnagrafica.CHIAVE := appAggiuntivi(i).chiave;
                      rigaDatiAggiuntiviAnagrafica.VALORE := appAggiuntivi(i).valore;

                      ADC_PKG_USAGE_UTILITY.insertDatiAggiuntiviAnagrafica(IS_DEBUG_ENABLED, rigaDatiAggiuntiviAnagrafica, TID);

                      i := anagraficaUsage.NEXT(i);

                  END LOOP;

                  EXCEPTION WHEN OTHERS THEN
                      --DBMS_OUTPUT.PUT_LINE(SQLERRM);
                      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  inputIdUsage || ') ERROR: ' || SQLERRM , ADC_PKG_COMMON.ERROR_LEVEL,TID);
                  END;

                  j := anagraficaUsage.NEXT(j);

              END LOOP;

              IF (sistemaSorgente = 'TT' AND FASECICLODIVITA = 'CON' AND idTracciatura IS NOT NULL) THEN

                  add_SA := TRUE;

                  BEGIN

                      SELECT AUSA.NOME, AUSA.VALORE, AUSA.ID_COD_SA INTO NOME_SA_TO_ADD,VALORE_SA_TO_ADD, ID_COD_SA_TO_ADD
                      FROM ADC_WRK_USAGE AW, ADC_USAGE_SERVIZI_ACCESSORI AUSA
                      WHERE AW.ID = AUSA.ID_USAGE AND AW.SISTEMA_SORGENTE = sistemaSorgente AND  AW.ID_TRACCIATURA = UPPER(idTracciatura) AND
                            AW.FASE_CICLO_VITA = 'ACS' AND AUSA.NOME = 'P' AND ROWNUM=1;

                      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTO_FERMO_POSTA - IDUsage (' ||  INPUTIDUSAGE || ') - TROVATO SERVIZIO ACCESSORIO CON NOME=P DA ASSOCIARE ALLO USAGE IN INPUT ', ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);

                  EXCEPTION WHEN NO_DATA_FOUND THEN

                      add_SA:= FALSE;

                  END;

              END IF;

              IF add_SA = TRUE THEN

                  rigaUSAGE_SA_TO_ADD.ID := NULL;
                  rigaUSAGE_SA_TO_ADD.ID_USAGE := idUsage;
                  rigaUSAGE_SA_TO_ADD.NOME := NOME_SA_TO_ADD;
                  rigaUSAGE_SA_TO_ADD.VALORE := VALORE_SA_TO_ADD;
                  rigaUSAGE_SA_TO_ADD.ID_COD_SA := ID_COD_SA_TO_ADD;

                  ADC_PKG_USAGE_UTILITY.insertUsageSA(IS_DEBUG_ENABLED,rigaUSAGE_SA_TO_ADD, TID);

              END IF;

              k := ServiAccessori.FIRST;

              WHILE k IS NOT NULL LOOP

                -- reperisco ID_COD_SA dalla ADC_TRANS_COD_SA
                BEGIN
                    SELECT /* ADC_PKG_LOAD_USAGE_S14 */ ID_SA
                    INTO rigaUSAGE_SA.ID_COD_SA
                    FROM adc_trans_cod_sa
                    WHERE chiave = ServiAccessori(k).nome
                    and sistema_sorgente = sistemaSorgente;
                  EXCEPTION WHEN NO_DATA_FOUND THEN
                      rigaUSAGE_SA.ID_COD_SA := NULL;
                END;

                rigaUSAGE_SA.ID := NULL;
                rigaUSAGE_SA.ID_USAGE := idUsage;
                rigaUSAGE_SA.NOME := ServiAccessori(k).nome;
                rigaUSAGE_SA.VALORE := ServiAccessori(k).valore;

                ADC_PKG_USAGE_UTILITY.insertUsageSA(IS_DEBUG_ENABLED,rigaUSAGE_SA, TID);

                k := ServiAccessori.NEXT(k);

            END LOOP;

            DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00040' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
            /* VERSIONE AGGIORNATA  RANGE TRACCIATURE */
            IF idTracciatura IS NOT NULL AND COD_TIPO_TRACCIATURA IS NOT NULL THEN -- P.ADDED_TO='PROCTRACCIATURA'

              IF(RIGAUSAGE.COD_TIPO_PROD_TRACC IN (1,2,3,4)) THEN

                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  idUsage || ') - FUNZIONE RANGE - BEGIN - '  , ADC_PKG_COMMON.DEBUG_LEVEL,TID, IS_DEBUG_ENABLED);
                  DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00050' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
                      BEGIN
                          SELECT /* ADC_PKG_LOAD_USAGE_S15 */ * INTO ADC_RANGE_TRACCIATURE_ROW FROM ADC_RANGE_TRACCIATURE WHERE idTracciatura BETWEEN RANGE_DA AND RANGE_A AND ROWNUM=1;

                          /*INSERT INTO ADC_RANGE_USAGE  ---------------------------------------*/
                          ADC_RANGE_USAGE_ROW.ID                    := SEQ_ADC_RANGE_USAGE.NEXTVAL;
                          ADC_RANGE_USAGE_ROW.ID_USAGE              := IDUSAGE;
                          ADC_RANGE_USAGE_ROW.ID_RANGE_TRACCIATURA  := ADC_RANGE_TRACCIATURE_ROW.ID;
                          ADC_RANGE_USAGE_ROW.DATA_ORA              := CURRENT_TIMESTAMP;

                          INSERT /* ADC_PKG_LOAD_USAGE_I21 */ INTO ADC_RANGE_USAGE VALUES ADC_RANGE_USAGE_ROW;

                          RIGAANAGRAFICATRAC.ID:=NULL;
                          RIGAANAGRAFICATRAC.CODICE_FISCALE:=UPPER(ADC_RANGE_TRACCIATURE_ROW.CODICE_FISCALE_CLI);
                          RIGAANAGRAFICATRAC.CODICE_NAZIONE_FISCALE:=ADC_RANGE_TRACCIATURE_ROW.CODICE_NAZ_FISCALE_CLI;
                          RIGAANAGRAFICATRAC.PIVA:=	UPPER(ADC_RANGE_TRACCIATURE_ROW.PARTITA_IVA_CLI);
                          RIGAANAGRAFICATRAC.CODICE_NAZIONE_PIVA:=ADC_RANGE_TRACCIATURE_ROW.CODICE_NAZ_PIVA_CLI;
                          RIGAANAGRAFICATRAC.SISTEMA_CODICE_NON_FISCALE:= NULL;
                          RIGAANAGRAFICATRAC.CODICE_CLIENTE_NON_FISCALE:= NULL;
                          RIGAANAGRAFICATRAC.NOME:=	ADC_RANGE_TRACCIATURE_ROW.NOME_CLIENTE;
                          RIGAANAGRAFICATRAC.COGNOME:=NULL;
                          RIGAANAGRAFICATRAC.INDIR_PARTICELLA_TOPONOMASTICA:=NULL;
                          RIGAANAGRAFICATRAC.INDIRIZZO:=NULL;
                          RIGAANAGRAFICATRAC.NUMERO_CIVICO:=NULL;
                          RIGAANAGRAFICATRAC.CAP:=NULL;
                          RIGAANAGRAFICATRAC.COMUNE:=NULL;
                          RIGAANAGRAFICATRAC.PROVINCIA:=NULL;
                          RIGAANAGRAFICATRAC.STATO:=NULL;
                          RIGAANAGRAFICATRAC.ID_ANAGRAFICA_BASE:= ADC_RANGE_TRACCIATURE_ROW.ID_ANAG_CLIENTE;
                          RIGAANAGRAFICATRAC.ID_RUOLO:=	6;
                          RIGAANAGRAFICATRAC.ID_USAGE:=	IDUSAGE;
                          RIGAANAGRAFICATRAC.COD_NAZIONALE_FIS:= NULL;
                          RIGAANAGRAFICATRAC.CN_PIVA:= NULL;
                          RIGAANAGRAFICATRAC.USAGE_PROCESSED:=1;

                          IDANAGRAFICA := ADC_PKG_USAGE_UTILITY.INSERTANAGRAFICAUSAGE(IS_DEBUG_ENABLED,RIGAANAGRAFICATRAC, TID);

                          RIGAANAGRAFICATRAC.ID:=NULL;
                          RIGAANAGRAFICATRAC.CODICE_FISCALE:=UPPER(ADC_RANGE_TRACCIATURE_ROW.CODICE_FISCALE_SER);
                          RIGAANAGRAFICATRAC.CODICE_NAZIONE_FISCALE:=ADC_RANGE_TRACCIATURE_ROW.CODICE_NAZ_FISCALE_SER;
                          RIGAANAGRAFICATRAC.PIVA:=	UPPER(ADC_RANGE_TRACCIATURE_ROW.PARTITA_IVA_SER);
                          RIGAANAGRAFICATRAC.CODICE_NAZIONE_PIVA:=ADC_RANGE_TRACCIATURE_ROW.CODICE_NAZ_PIVA_SER;
                          RIGAANAGRAFICATRAC.SISTEMA_CODICE_NON_FISCALE:= NULL;
                          RIGAANAGRAFICATRAC.CODICE_CLIENTE_NON_FISCALE:= NULL;
                          RIGAANAGRAFICATRAC.NOME:=	ADC_RANGE_TRACCIATURE_ROW.NOME_SERVICE;
                          RIGAANAGRAFICATRAC.COGNOME:=NULL;
                          RIGAANAGRAFICATRAC.INDIR_PARTICELLA_TOPONOMASTICA:=NULL;
                          RIGAANAGRAFICATRAC.INDIRIZZO:=NULL;
                          RIGAANAGRAFICATRAC.NUMERO_CIVICO:=NULL;
                          RIGAANAGRAFICATRAC.CAP:=NULL;
                          RIGAANAGRAFICATRAC.COMUNE:=NULL;
                          RIGAANAGRAFICATRAC.PROVINCIA:=NULL;
                          RIGAANAGRAFICATRAC.STATO:=NULL;
                          RIGAANAGRAFICATRAC.ID_ANAGRAFICA_BASE:= ADC_RANGE_TRACCIATURE_ROW.ID_ANAG_SERVICE;
                          RIGAANAGRAFICATRAC.ID_RUOLO:=	7;
                          RIGAANAGRAFICATRAC.ID_USAGE:=	IDUSAGE;
                          RIGAANAGRAFICATRAC.COD_NAZIONALE_FIS:= NULL;
                          RIGAANAGRAFICATRAC.CN_PIVA:= NULL;
                          RIGAANAGRAFICATRAC.USAGE_PROCESSED:=1;

                          IDANAGRAFICA := ADC_PKG_USAGE_UTILITY.INSERTANAGRAFICAUSAGE(IS_DEBUG_ENABLED,RIGAANAGRAFICATRAC, TID);

                          /* DUE DI COPPE ================================================ */
                      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  IDUSAGE || ') - FUNZIONE RANGE - END - '  , ADC_PKG_COMMON.DEBUG_LEVEL,TID, IS_DEBUG_ENABLED);

                      EXCEPTION WHEN NO_DATA_FOUND THEN
                        V_ID_TRACCIATURA  := NULL;
                        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  idUsage || ') - FUNZIONE 2COMM - ANAGRAFICA NON TROVATA - '  , ADC_PKG_COMMON.DEBUG_LEVEL,TID, IS_DEBUG_ENABLED);
                      END;
                      DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00050' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

                  END IF;
                  IF(RIGAUSAGE.COD_TIPO_PROD_TRACC = 5) THEN
                      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  idUsage || ') - FUNZIONE 2COMM - START - '  , ADC_PKG_COMMON.DEBUG_LEVEL,TID, IS_DEBUG_ENABLED);
                      DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00060' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
                      BEGIN
                          V_RUOLO_ANAGRAFICA := CASE
                                              WHEN SUBSTR(idTracciatura,1,1) IN ('1','G','I')
                                                THEN 6 --CLIENTE
                                              WHEN SUBSTR(idTracciatura,1,1) IN ('V','R')
                                                THEN 7
                                              ELSE NULL
                                              END;

                          V_COD_SAP := trim(SUBSTR(idTracciatura,3,8));



                           SELECT /* ADC_PKG_LOAD_USAGE_S18 */ AB.CF_CORRENTE, CB.piva_corrente, cb.ragione_sociale, R.id_anagrafica_base INTO V_CF_CORRENTE_2COMM, V_PIVA_CORR_2COMM, V_RAG_SOC_2COMM, V_ID_ANAG_BASE_2COMM
                                  FROM ADC_VARIAZIONI_SISTEMA R join ADC_ANAGRAFICA_BASE AB ON (R.id_anagrafica_base = AB.id)
                                  right outer join ADC_CLIENTE_BUSINESS CB ON (AB.id = CB.id_anagrafica_base)
                                  WHERE R.ID_SISTEMA_SORGENTE = 'SAP' AND
                                        R.CODICE_CLIENTE_SORGENTE = V_COD_SAP AND
                                        ROWNUM = 1;


                            RIGAANAGRAFICA2.ID := NULL;
                            RIGAANAGRAFICA2.CODICE_CLIENTE_NON_FISCALE:= V_COD_SAP;
                            RIGAANAGRAFICA2.ID_RUOLO:= V_RUOLO_ANAGRAFICA;
                            RIGAANAGRAFICA2.ID_USAGE:= idUsage;
                            RIGAANAGRAFICA2.CODICE_FISCALE := V_CF_CORRENTE_2COMM;
                            RIGAANAGRAFICA2.ID_ANAGRAFICA_BASE:= V_ID_ANAG_BASE_2COMM;
                            RIGAANAGRAFICA2.PIVA:=	V_PIVA_CORR_2COMM;
                            RIGAANAGRAFICA2.NOME:=  V_RAG_SOC_2COMM;
                            RIGAANAGRAFICA2.USAGE_PROCESSED:=1;

                            IDANAGRAFICA := ADC_PKG_USAGE_UTILITY.INSERTANAGRAFICAUSAGE(IS_DEBUG_ENABLED,RIGAANAGRAFICA2, TID);
                            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  idUsage || ') - FUNZIONE 2COMM - END - '  , ADC_PKG_COMMON.DEBUG_LEVEL,TID, IS_DEBUG_ENABLED);
                      EXCEPTION WHEN NO_DATA_FOUND THEN
                          V_ID_TRACCIATURA  := NULL;
                          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  idUsage || ') - FUNZIONE 2COMM - ANAGRAFICA NON TROVATA - '  , ADC_PKG_COMMON.DEBUG_LEVEL,TID, IS_DEBUG_ENABLED);

                      END;

                      DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00060' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
              END IF;
            END IF;
            /* GESTIONE CICLO DI VITA
                NEL CASO LO USAGE NON SIA DUPLICATO
            */
            ADC_PKG_LIFECYCLE.LIFECYCLE_USAGE (
                TID                     => TID,
                INPUTIDUSAGE            => IDUSAGE,
                DATAORAEVENTO           => DATAORAEVENTO,
                ID_FLUSSO               => INPUT_ID_FLUSSO, -- CR CICLI VITA ONLINE
                SISTEMA_SORGENTE => sistemaSorgente,
                IS_DEBUG_ENABLED        => IS_DEBUG_ENABLED
            );
        END IF; -- IF USAGE DUPLICATO

        ESITOOPERAZIONE := 'OK';
        l_end := dbms_utility.get_time ;
        L_END := DBMS_UTILITY.GET_TIME ;  -- Start Time

        LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTOUSAGE - IDUsage (' ||  idUsage || ')  END - (elapsed:'|| (l_end - l_start)/100 ||' s)'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID, IS_DEBUG_ENABLED);
      END;

      -- procedura invocata da dequeue usage (batch)
      PROCEDURE INSERIMENTOARRICCHIMENTO_USAGE(
        IS_DIAGNOSTIC_ENABLED  BOOLEAN,
        IS_DEBUG_ENABLED  BOOLEAN,
        TID VARCHAR2,
        INPUT_ID_FLUSSO NUMBER,
        JOB_ID NUMBER,
        inputIdUsage NUMBER,
        dataOraEvento TIMESTAMP,
        faseCicloDiVita VARCHAR2,
        sottoFaseCicloDiVita VARCHAR2,
        canale VARCHAR2,
        sistemaSorgente VARCHAR2 ,
        codiceProdottoServizio CODICEPRODOTTOSERVIZIO_TABLE,
        costoProdottoServizio VARCHAR2,
        metodoPagamentoCliente VARCHAR2,
        esito VARCHAR2,
        chiaveUsageLista CHIAVEUSAGE_TABLE,
        idTracciatura VARCHAR2,
        sistemaTracciatura VARCHAR2,
        tipoProdottoTracciatura VARCHAR2,
        motivoContatto VARCHAR2,
        tipoClientePagamento VARCHAR2,
        datiAggiuntiviUsage DATIAGGIUNTIVI_TABLE,
        anagraficaUsage DATIANAGRAFICI_TABLE,
        ComuneLuogoEvento VARCHAR2,
        AltroIdTracciatura VARCHAR2,
        CodicePTL VARCHAR2,
        ZonaPTL VARCHAR2,
        FrazAccettazione VARCHAR2,
        FrazDestinatario VARCHAR2,
        ProvinciaLuogoEvento VARCHAR2,
        FilialeSDA VARCHAR2,
        SERVIACCESSORI SERVIZIACCESSORI_TABLE,

        ID_FASE NUMBER,
        ID_SOTTOFASE NUMBER,
        ID_METODO_PAGAMENTO_CLIENTE VARCHAR2,
        COD_TIPO_PROCESSO VARCHAR2,
        COD_SISTEMA_PROCESSO VARCHAR2,
        COD_TIPO_TRACCIATURA VARCHAR2,
        COD_SISTEMA_TRACCIATURA VARCHAR2,
        COD_SISTEMA_ALTROP VARCHAR2,
        COD_TIPO_ALTROP VARCHAR2,
        ID_PROD_SERVIZIO VARCHAR2,
        ID_CANALE NUMBER,
        ID_TIPO_CLIENTE_PAGAMENTO VARCHAR2,
        ID_PROCESSO VARCHAR2,
        VENDITA VARCHAR2,
        NFEA_DETTAGLIO_A_CHIAMATA VARCHAR2,
        NFEA_DETTAGLIO_B_CHIAMATA VARCHAR2,
        NFEA_SITO_CC VARCHAR2,
        NFEA_FORNITORE_CC VARCHAR2,
        NFEA_TEAM VARCHAR2,
        NFEA_LOGIN VARCHAR2,
        FRAZIONARIO_UP VARCHAR2,
        NOME_UP VARCHAR2,
        CITTA_LUOGO_EVENTO VARCHAR2,
        ALT VARCHAR2,
        RAM VARCHAR2,
        CD VARCHAR2,
        ZONA VARCHAR2,
        TIPOLOGIA_ASSISTENZA VARCHAR2,
        ID_TRACC_CORR VARCHAR2,
        TIPO_PROD_TRACC_CORR VARCHAR2,
        SIST_TRACC_CORR VARCHAR2,
        COD_TIPO_PROD_TRACC_CORR VARCHAR2,
        COD_SIST_TRACC_CORR VARCHAR2,


        esitoOperazione OUT VARCHAR2,
        idUsage OUT NUMBER,
        MSGTYPE VARCHAR2,
        NUMERO_TENTATIVI_CONS NUMBER,
        QUALIFICA  VARCHAR2,
        SOURCE_TIPOLOGIA_ASSISTENZA VARCHAR2

    ) IS

      J                     NUMBER;
      K                     NUMBER;
      LOGRESULT             NUMBER;
      L_START               NUMBER;
      L_END                 NUMBER;
      L_START_ARRICCHIMENTO NUMBER;
      arricchimento         boolean;
      ID_USAGE_ACCETTAZIONE VARCHAR2(255);
      idRuolo               NUMBER;
      RIGAANAGRAFICA        ADC_USAGE_ANAGRAFICA%ROWTYPE;
      idAnagrafica            NUMBER;

      --diagnostic variables
      DIAGNOSTIC_CODE VARCHAR2(512):='IAU4005';
      DIAGNOSTIC_LN VARCHAR2(512):=ADC_PKG_LOAD_USAGE.DIAGNOSTIC_LOGGER_NAME;
      DIAGNOSTIC_INFO_LEVEL VARCHAR2(512):=ADC_PKG_COMMON.INFO_LEVEL;
      DIAGNOSTIC_RESULT NUMBER;

      rigaUSAGE_SA            ADC_USAGE_SERVIZI_ACCESSORI%ROWTYPE;

BEGIN

      ADC_PKG_USAGE_UTILITY.LOGGER_NAME:='LOAD'; -- set logger_name per la sessione

      l_start := dbms_utility.get_time ;  -- Start Time
      ARRICCHIMENTO := FALSE;

      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTO_ARRICCHIMENTO_USAGE - IDUsage (' ||  INPUTIDUSAGE || ') BEGIN'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
      DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
      IF (SISTEMASORGENTE = 'TT' AND FASECICLODIVITA = 'ACS' AND SOTTOFASECICLODIVITA IN ('ARR','ARO')) THEN
        arricchimento := TRUE;

        BEGIN
            SELECT /* ADC_PKG_LOAD_USAGE_S16 */ ID into ID_USAGE_ACCETTAZIONE
            FROM (select ID from ADC_WRK_USAGE where SISTEMA_SORGENTE='TT' and FASE_CICLO_VITA='ACS' and SOTTO_FASE_CICLO_VITA='ALS' and ID_TRACCIATURA =UPPER(idTracciatura) order by DATA_ORA_EVENTO desc)
            WHERE ROWNUM=1;

            LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTO_ARRICCHIMENTO_USAGE - IDUsage (' ||  INPUTIDUSAGE || ') - TROVATO ID_USAGE DA ARRICCHIRE: ' || ID_USAGE_ACCETTAZIONE  , ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);

        EXCEPTION WHEN NO_DATA_FOUND THEN
            arricchimento:= FALSE;
        END;

      END IF;

      DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00010' || ']', DIAGNOSTIC_INFO_LEVEL,TID);

    BEGIN
        IF (ARRICCHIMENTO = FALSE) THEN
            DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00020' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
            INSERIMENTOUSAGE(
                IS_DEBUG_ENABLED => IS_DEBUG_ENABLED,
                TID => TID,
                INPUT_ID_FLUSSO => INPUT_ID_FLUSSO,
                JOB_ID => JOB_ID,
                INPUTIDUSAGE => inputIdUsage,
                DATAORAEVENTO => DATAORAEVENTO,
                FASECICLODIVITA => FASECICLODIVITA,
                SOTTOFASECICLODIVITA => SOTTOFASECICLODIVITA,
                CANALE => CANALE,
                SISTEMASORGENTE => SISTEMASORGENTE,
                CODICEPRODOTTOSERVIZIO => CODICEPRODOTTOSERVIZIO,
                COSTOPRODOTTOSERVIZIO => COSTOPRODOTTOSERVIZIO,
                METODOPAGAMENTOCLIENTE => METODOPAGAMENTOCLIENTE,
                ESITO => ESITO,
                CHIAVEUSAGELISTA => CHIAVEUSAGELISTA,
                IDTRACCIATURA => IDTRACCIATURA,
                SISTEMATRACCIATURA => SISTEMATRACCIATURA,
                TIPOPRODOTTOTRACCIATURA => TIPOPRODOTTOTRACCIATURA,
                MOTIVOCONTATTO => MOTIVOCONTATTO,
                TIPOCLIENTEPAGAMENTO => TIPOCLIENTEPAGAMENTO,
                DATIAGGIUNTIVIUSAGE => DATIAGGIUNTIVIUSAGE,
                ANAGRAFICAUSAGE => ANAGRAFICAUSAGE,
                COMUNELUOGOEVENTO => COMUNELUOGOEVENTO,
                ALTROIDTRACCIATURA => ALTROIDTRACCIATURA,
                CODICEPTL => CODICEPTL,
                ZONAPTL => ZONAPTL,
                FRAZACCETTAZIONE => FRAZACCETTAZIONE,
                FRAZDESTINATARIO => FRAZDESTINATARIO,
                PROVINCIALUOGOEVENTO => PROVINCIALUOGOEVENTO,
                FILIALESDA => FILIALESDA,
                SERVIACCESSORI => SERVIACCESSORI,
                ID_FASE => ID_FASE,
                ID_SOTTOFASE => ID_SOTTOFASE,
                ID_METODO_PAGAMENTO_CLIENTE => ID_METODO_PAGAMENTO_CLIENTE,
                COD_TIPO_PROCESSO => COD_TIPO_PROCESSO,
                COD_SISTEMA_PROCESSO => COD_SISTEMA_PROCESSO,
                COD_TIPO_TRACCIATURA => COD_TIPO_TRACCIATURA,
                COD_SISTEMA_TRACCIATURA => COD_SISTEMA_TRACCIATURA,
                COD_SISTEMA_ALTROP => COD_SISTEMA_ALTROP,
                COD_TIPO_ALTROP => COD_TIPO_ALTROP,
                ID_PROD_SERVIZIO => ID_PROD_SERVIZIO,
                ID_CANALE => ID_CANALE,
                ID_TIPO_CLIENTE_PAGAMENTO => ID_TIPO_CLIENTE_PAGAMENTO,
                ID_PROCESSO => ID_PROCESSO,
                VENDITA => VENDITA,
                NFEA_DETTAGLIO_A_CHIAMATA => NFEA_DETTAGLIO_A_CHIAMATA,
                NFEA_DETTAGLIO_B_CHIAMATA => NFEA_DETTAGLIO_B_CHIAMATA,
                NFEA_SITO_CC => NFEA_SITO_CC,
                NFEA_FORNITORE_CC => NFEA_FORNITORE_CC,
                NFEA_TEAM => NFEA_TEAM,
                NFEA_LOGIN => NFEA_LOGIN,
                FRAZIONARIO_UP => FRAZIONARIO_UP,
                NOME_UP => NOME_UP,
                CITTA_LUOGO_EVENTO => CITTA_LUOGO_EVENTO,
                ALT => ALT,
                RAM => RAM,
                CD => CD,
                ZONA => ZONA,
                TIPOLOGIA_ASSISTENZA => TIPOLOGIA_ASSISTENZA,
                ID_TRACC_CORR => ID_TRACC_CORR,
                TIPO_PROD_TRACC_CORR => TIPO_PROD_TRACC_CORR,
                SIST_TRACC_CORR => SIST_TRACC_CORR,
                COD_TIPO_PROD_TRACC_CORR => COD_TIPO_PROD_TRACC_CORR,
                COD_SIST_TRACC_CORR => COD_SIST_TRACC_CORR,
                ESITOOPERAZIONE => ESITOOPERAZIONE,
                IDUSAGE => IDUSAGE,
                MSGTYPE => MSGTYPE,
                NUMERO_TENTATIVI_CONS  => NUMERO_TENTATIVI_CONS,
                QUALIFICA              => QUALIFICA,
                SOURCE_TIPOLOGIA_ASSISTENZA => SOURCE_TIPOLOGIA_ASSISTENZA
              );

              DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00020' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
        ELSE

          DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-B-00030' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
          j := anagraficaUsage.FIRST;
          WHILE j IS NOT NULL LOOP

            BEGIN

                IF( ANAGRAFICAUSAGE(J).TIPORUOLO IS NULL ) THEN
                   raise_application_error (-20001,'ANAGRAFICA_NO_RUOLO');
                END IF;

                BEGIN
                  select /* ADC_PKG_LOAD_USAGE_S42 */ ID INTO idRuolo from ADC_TIP_USAGE_RUOLI where ruolo = anagraficaUsage(j).tipoRuolo;
                EXCEPTION
                  WHEN NO_DATA_FOUND THEN
                  raise_application_error(-20001,'USAGE_RUOLO_NO_VALID');
                END;

                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTO_ARRICCHIMENTO_USAGE - IDUsage (' ||  ID_USAGE_ACCETTAZIONE || ') - ARRICHIMENTO ANAGRAFICA RUOLO:' || ANAGRAFICAUSAGE(J).TIPORUOLO  , ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);

                L_START_ARRICCHIMENTO := DBMS_UTILITY.GET_TIME;  -- Start Time


                UPDATE /* ADC_PKG_LOAD_USAGE_U27 */ ADC_USAGE_ANAGRAFICA a SET
                  a.CODICE_FISCALE =	NVL(UPPER(anagraficaUsage(j).cf), a.CODICE_FISCALE),
                  a.CODICE_NAZIONE_FISCALE =	NVL(anagraficaUsage(j).cnf , a.CODICE_NAZIONE_FISCALE),
                  a.PIVA =	NVL(anagraficaUsage(j).piva, a.PIVA),
                  a.CODICE_NAZIONE_PIVA =	NVL(UPPER(anagraficaUsage(j).cnPiva), a.CODICE_NAZIONE_PIVA),
                  a.SISTEMA_CODICE_NON_FISCALE =	NVL(anagraficaUsage(j).sistemaCodiceNonFiscale, a.SISTEMA_CODICE_NON_FISCALE),
                  a.CODICE_CLIENTE_NON_FISCALE =	NVL(anagraficaUsage(j).codiceClienteNonFiscale, a.CODICE_CLIENTE_NON_FISCALE),
                  a.NOME = NVL(anagraficaUsage(j).nome, a.NOME),
                  a.COGNOME =	NVL(anagraficaUsage(j).cognome, a.COGNOME),
                  a.INDIR_PARTICELLA_TOPONOMASTICA = NVL(anagraficaUsage(j).particellaToponomastica, a.INDIR_PARTICELLA_TOPONOMASTICA),
                  a.INDIRIZZO =	NVL(anagraficaUsage(j).indirizzo, a.INDIRIZZO),
                  a.NUMERO_CIVICO =	NVL(anagraficaUsage(j).numeroCivico, a.NUMERO_CIVICO),
                  a.CAP =	NVL(anagraficaUsage(j).cap, a.CAP),
                  a.COMUNE =	NVL(anagraficaUsage(j).comune, a.COMUNE),
                  a.PROVINCIA =	NVL( anagraficaUsage(j).provincia, a.PROVINCIA),
                  a.STATO =	NVL(anagraficaUsage(j).stato, a.STATO),
                  a.MAIL =	NVL(anagraficaUsage(j).mail, a.MAIL),
                  a.TELEFONO =	NVL(anagraficaUsage(j).telefono, a.TELEFONO)

                  WHERE A.ID_USAGE = ID_USAGE_ACCETTAZIONE AND A.ID_RUOLO = IDRUOLO;

                  IF (SQL%ROWCOUNT=0) THEN

                      L_END := DBMS_UTILITY.GET_TIME;

                    rigaAnagrafica.ID := NULL;
                    rigaAnagrafica.CODICE_FISCALE := UPPER(anagraficaUsage(j).cf);
                    rigaAnagrafica.CODICE_NAZIONE_FISCALE := anagraficaUsage(j).cnf;
                    rigaAnagrafica.PIVA := UPPER(anagraficaUsage(j).piva);
                    rigaAnagrafica.CODICE_NAZIONE_PIVA := anagraficaUsage(j).cnPiva;
                    rigaAnagrafica.SISTEMA_CODICE_NON_FISCALE := anagraficaUsage(j).sistemaCodiceNonFiscale;
                    rigaAnagrafica.CODICE_CLIENTE_NON_FISCALE := anagraficaUsage(j).codiceClienteNonFiscale;
                    rigaAnagrafica.NOME := anagraficaUsage(j).nome;
                    rigaAnagrafica.COGNOME := anagraficaUsage(j).cognome;
                    rigaAnagrafica.INDIR_PARTICELLA_TOPONOMASTICA := anagraficaUsage(j).particellaToponomastica;
                    rigaAnagrafica.INDIRIZZO := anagraficaUsage(j).indirizzo;
                    rigaAnagrafica.NUMERO_CIVICO := anagraficaUsage(j).numeroCivico;
                    rigaAnagrafica.CAP := anagraficaUsage(j).cap;
                    rigaAnagrafica.COMUNE := anagraficaUsage(j).comune;
                    rigaAnagrafica.PROVINCIA := anagraficaUsage(j).provincia;
                    rigaAnagrafica.STATO := anagraficaUsage(j).stato;
                    rigaAnagrafica.ID_ANAGRAFICA_BASE := NULL;
                    rigaAnagrafica.ID_RUOLO := idRuolo;
                    rigaAnagrafica.ID_USAGE := ID_USAGE_ACCETTAZIONE;
                    rigaAnagrafica.COD_NAZIONALE_FIS := anagraficaUsage(j).codiceNazionaleFis;
                    rigaAnagrafica.CN_PIVA := anagraficaUsage(j).codiceNazionalePiva;
                    rigaAnagrafica.MAIL := anagraficaUsage(j).mail;
                    RIGAANAGRAFICA.TELEFONO := ANAGRAFICAUSAGE(J).TELEFONO;

                    IF(
                      rigaAnagrafica.CODICE_FISCALE IS NULL AND rigaAnagrafica.CODICE_NAZIONE_FISCALE IS NULL AND rigaAnagrafica.PIVA IS NULL AND
                      RIGAANAGRAFICA.CODICE_NAZIONE_PIVA IS NULL AND rigaAnagrafica.SISTEMA_CODICE_NON_FISCALE IS NULL AND
                      RIGAANAGRAFICA.CODICE_CLIENTE_NON_FISCALE IS NULL AND rigaAnagrafica.NOME IS NULL AND rigaAnagrafica.COGNOME IS NULL AND
                      RIGAANAGRAFICA.INDIR_PARTICELLA_TOPONOMASTICA IS NULL AND rigaAnagrafica.INDIRIZZO IS NULL AND
                      RIGAANAGRAFICA.NUMERO_CIVICO IS NULL AND rigaAnagrafica.CAP IS NULL AND rigaAnagrafica.COMUNE IS NULL AND
                      RIGAANAGRAFICA.PROVINCIA  IS NULL AND RIGAANAGRAFICA.STATO IS NULL AND rigaAnagrafica.COD_NAZIONALE_FIS IS NULL AND
                      rigaAnagrafica.CN_PIVA IS NULL AND rigaAnagrafica.MAIL IS NULL AND rigaAnagrafica.TELEFONO IS NULL
                    )
                    THEN

                      LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTO_ARRICCHIMENTO_USAGE - IDUsage (' ||  ID_USAGE_ACCETTAZIONE || ') - SKIP ANAGRAFICA '  , ADC_PKG_COMMON.DEBUG_LEVEL ,TID,IS_DEBUG_ENABLED);
                      -- RAISE_APPLICATION_ERROR(-20001,'SKIP ANAGRAFICA');

                     ELSE
                        idAnagrafica := ADC_PKG_USAGE_UTILITY.INSERTANAGRAFICAUSAGE(IS_DEBUG_ENABLED,RIGAANAGRAFICA, TID);
                     END IF;

                  END IF;

                  L_END := DBMS_UTILITY.GET_TIME;

              EXCEPTION WHEN OTHERS THEN
                  LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTO_ARRICCHIMENTO_USAGE - IDUsage (' ||  ID_USAGE_ACCETTAZIONE || ') - ERRORE ARRICCHIMENTO ANAGRAFICA:' || SQLERRM  , ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
              END;
            j := anagraficaUsage.NEXT(j);
          END LOOP;

          k := SERVIACCESSORI.FIRST;

          WHILE k IS NOT NULL LOOP
                    -- reperisco ID_COD_SA dalla ADC_TRANS_COD_SA
           BEGIN

              BEGIN
                SELECT /* ADC_PKG_LOAD_USAGE_S17 */ ID_SA
                INTO rigaUSAGE_SA.ID_COD_SA
                FROM adc_trans_cod_sa
                WHERE chiave = SERVIACCESSORI(k).nome
                      and sistema_sorgente = SISTEMASORGENTE;
              EXCEPTION WHEN NO_DATA_FOUND THEN
                      rigaUSAGE_SA.ID_COD_SA := NULL;
              END;

              rigaUSAGE_SA.ID := NULL;
              rigaUSAGE_SA.ID_USAGE := ID_USAGE_ACCETTAZIONE;
              rigaUSAGE_SA.NOME := SERVIACCESSORI(k).nome;
              rigaUSAGE_SA.VALORE := SERVIACCESSORI(k).valore;

              ADC_PKG_USAGE_UTILITY.insertUsageSA(IS_DEBUG_ENABLED,rigaUSAGE_SA, TID);

           EXCEPTION WHEN OTHERS THEN
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTO_ARRICCHIMENTO_USAGE - IDUsage (' ||  ID_USAGE_ACCETTAZIONE || ') - ERRORE ARRICCHIMENTO SERVIZI ACCESSORI:' || SQLERRM  , ADC_PKG_COMMON.DEBUG_LEVEL,TID,IS_DEBUG_ENABLED);
           END;

           k := SERVIACCESSORI.NEXT(k);

          END LOOP;

          ESITOOPERAZIONE := 'OK';
          idUsage := ID_USAGE_ACCETTAZIONE;

          /* GESTIONE CICLO DI VITA
           NEL CASO SIA STATO ARRICCHITO
          */
          ADC_PKG_LIFECYCLE.LIFECYCLE_USAGE (
              TID                     => TID,
              INPUTIDUSAGE            => idUsage,
              DATAORAEVENTO           => DATAORAEVENTO,
              ID_FLUSSO               => INPUT_ID_FLUSSO, -- CR CICLI VITA ONLINE
              SISTEMA_SORGENTE        => sistemaSorgente,
              IS_DEBUG_ENABLED        => IS_DEBUG_ENABLED
          );


          DIAGNOSTIC_RESULT := ADC_PKG_COMMON.LOGGER(DIAGNOSTIC_LN, '[' || DIAGNOSTIC_CODE || '-E-00030' || ']', DIAGNOSTIC_INFO_LEVEL,TID);
        END IF;

      END;
    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, '[' || JOB_ID || ']['|| INPUT_ID_FLUSSO ||'] INSERIMENTO_ARRICCHIMENTO_USAGE - IDUsage (' ||  IDUSAGE || ')  END - (elapsed:'|| (L_END - L_START)/100 ||' s)'  , ADC_PKG_COMMON.DEBUG_LEVEL,TID, IS_DEBUG_ENABLED);
    ADC_PKG_COMMON.FLUSH_LOGGER(DIAGNOSTIC_LN);
  END;

  /* UTILITY ******************************************************************** */

  PROCEDURE RECOVERY_ERROR_MESSAGES(V_VIRTUAL_QUEUE VARCHAR2) IS

    L_START                         NUMBER;
    L_END                           NUMBER;
    DEQUEUE_OPTIONS                 DBMS_AQ.DEQUEUE_OPTIONS_T;
    MESSAGE_PROPERTIES              DBMS_AQ.MESSAGE_PROPERTIES_T;
    V_MESSAGE_HANDLE                RAW(16);
    MSGID                           RAW(16);
    DEQUEUED_MESSAGE                NUMBER;

    TYPE QUEUES_TABLE IS TABLE OF VARCHAR2(100) INDEX BY PLS_INTEGER;
    QUEUE_INDEX                     NUMBER;
    QUEUE_NUMBER                    NUMBER;
    QUEUES                          QUEUES_TABLE;

    V_QUEUE                         VARCHAR2(100);
    ERROR_QUEUE                     VARCHAR2(100);
    QUEUE_SUFFIX                    VARCHAR2(10);
    V_DEQUEUE_OPTIONS               DBMS_AQ.DEQUEUE_OPTIONS_T;
    V_MESSAGE_PROPERTIES            DBMS_AQ.MESSAGE_PROPERTIES_T;
    V_ERR_ENQUEUE_OPTIONS           DBMS_AQ.ENQUEUE_OPTIONS_T;
    V_ERR_MESSAGE_PROPERTIES        DBMS_AQ.MESSAGE_PROPERTIES_T;
    MESSAGE_TYPE                    VARCHAR2(100);

    M_TT_LOAD_USAGE                LOAD_USAGE_MESSAGE_TYPE;
    M_SAP_LOAD_USAGE               LOAD_USAGE_MESSAGE_SAPEM_TYPE;
    M_LIFECYCLE                    LIFECYCLE_USAGE_MESSAGE_TYPE;

    LOGRESULT                      NUMBER;
    QUEUE_COUNT                    NUMBER;
    NO_MESSAGES                    EXCEPTION;

    PRAGMA EXCEPTION_INIT (NO_MESSAGES, -25228);
  BEGIN
      DEQUEUED_MESSAGE :=0;
      L_START := DBMS_UTILITY.GET_TIME ;  -- Start Time
      /*MESSAGE_TYPE*/
      BEGIN
        SELECT PARAMETER_VALUE INTO QUEUE_NUMBER FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='QUEUE_NUMBER' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
        SELECT PARAMETER_VALUE INTO QUEUE_NUMBER FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='QUEUE_NUMBER' AND ROWNUM = 1;
        END;

      BEGIN
        SELECT PARAMETER_VALUE INTO MESSAGE_TYPE FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = V_VIRTUAL_QUEUE AND AQC.PARAMETER_TYPE='MESSAGE_TYPE' AND ROWNUM = 1;
      EXCEPTION WHEN NO_DATA_FOUND THEN
        SELECT PARAMETER_VALUE INTO QUEUE_NUMBER FROM ADC_QUEUES_CONFIG AQC WHERE AQC.VIRTUAL_QUEUE = 'DEFAULT' AND AQC.PARAMETER_TYPE='MESSAGE_TYPE' AND ROWNUM = 1;
      END;


      ERROR_QUEUE := 'Q_ERROR_' ||V_VIRTUAL_QUEUE;
      V_DEQUEUE_OPTIONS.WAIT          := DBMS_AQ.NO_WAIT;
      V_DEQUEUE_OPTIONS.visibility    := dbms_aq.on_commit;
      BEGIN

        IF(V_VIRTUAL_QUEUE = 'TT_LOAD_USAGE') THEN

            BEGIN
                QUEUE_COUNT :=0;
                LOOP
                   QUEUE_COUNT := QUEUE_COUNT + 1;
                   QUEUE_SUFFIX := '0'||QUEUE_COUNT;

                      DBMS_OUTPUT.PUT_LINE(V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1 ));
                    V_QUEUE       :=  'Q_'  || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);
                    --V_QUEUE_TABLE :=  'QT_' || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);


                    DBMS_AQ.DEQUEUE(
                             QUEUE_NAME           => ERROR_QUEUE,
                             DEQUEUE_OPTIONS      => V_DEQUEUE_OPTIONS,
                             MESSAGE_PROPERTIES   => v_ERR_message_properties,
                             PAYLOAD              => M_TT_LOAD_USAGE,
                             MSGID                => MSGID);
                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - MESSAGGIO SPOSTATO DA ' || ERROR_QUEUE || ' A ' || V_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
                    IF(V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY IS NULL) THEN
                      V_MESSAGE_PROPERTIES.USER_PROPERTY := SYS.ANYDATA.CONVERTNUMBER(M_TT_LOAD_USAGE.ID_FLUSSO);
                    ELSE
                      V_MESSAGE_PROPERTIES.USER_PROPERTY := V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY;
                    END IF;

                    DBMS_AQ.ENQUEUE(
                          QUEUE_NAME              => V_QUEUE,
                          ENQUEUE_OPTIONS         => V_ERR_ENQUEUE_OPTIONS,
                          message_properties      => V_MESSAGE_PROPERTIES,
                          PAYLOAD                 => M_TT_LOAD_USAGE,
                          MSGID                   => V_MESSAGE_HANDLE
                    );

                    DEQUEUED_MESSAGE := DEQUEUED_MESSAGE + 1;

                    IF(QUEUE_COUNT = QUEUE_NUMBER) THEN
                      QUEUE_COUNT := 0;
                    END IF;

                END LOOP;
            EXCEPTION WHEN NO_MESSAGES THEN
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - NO MORE MESSAGES IN ' || ERROR_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
            END;

          ELSIF (V_VIRTUAL_QUEUE = 'SAP_LOAD_USAGE') THEN

            QUEUE_COUNT := 0;
            BEGIN
                FOR I IN 1..QUEUE_NUMBER LOOP
                    QUEUE_COUNT := QUEUE_COUNT + 1;
                    QUEUE_SUFFIX := '0'||QUEUE_COUNT;
                    V_QUEUE       :=  'Q_'  || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);

                    DBMS_AQ.DEQUEUE(
                             QUEUE_NAME           => ERROR_QUEUE,
                             dequeue_options      => V_DEQUEUE_OPTIONS,
                             MESSAGE_PROPERTIES   => V_ERR_MESSAGE_PROPERTIES,
                             PAYLOAD              => M_SAP_LOAD_USAGE,
                             MSGID                => MSGID);

                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - MESSAGGIO SPOSTATO DA ' || ERROR_QUEUE || ' A ' || V_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');

                    IF(V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY IS NULL) THEN
                      V_MESSAGE_PROPERTIES.USER_PROPERTY := SYS.ANYDATA.CONVERTNUMBER(M_SAP_LOAD_USAGE.ID_FLUSSO);
                    ELSE
                      V_MESSAGE_PROPERTIES.USER_PROPERTY := V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY;
                    END IF;

                    DBMS_AQ.ENQUEUE(
                          QUEUE_NAME              => V_QUEUE,
                          ENQUEUE_OPTIONS         => V_ERR_ENQUEUE_OPTIONS,
                          MESSAGE_PROPERTIES      => V_MESSAGE_PROPERTIES,
                          PAYLOAD                 => M_SAP_LOAD_USAGE,
                          MSGID                   => V_MESSAGE_HANDLE
                    );

                    DEQUEUED_MESSAGE := DEQUEUED_MESSAGE + 1;
                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - MESSAGGIO ' || MSGID || ' SPOSTATO DA ' || ERROR_QUEUE || ' IN ' || V_QUEUE || ':' || V_MESSAGE_HANDLE, ADC_PKG_COMMON.INFO_LEVEL,'');
                     IF(QUEUE_COUNT = QUEUE_NUMBER) THEN
                      QUEUE_COUNT := 0;
                    END IF;
                END LOOP;
            EXCEPTION WHEN NO_MESSAGES THEN
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - NO MORE MESSAGES IN ' || ERROR_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
            END;

          ELSIF (V_VIRTUAL_QUEUE = 'LIFECYCLE' OR V_VIRTUAL_QUEUE = 'SEQ_LIFECYCLE') THEN

            BEGIN

                LOOP

                    QUEUE_COUNT := 1;
                    QUEUE_SUFFIX := '0'||QUEUE_COUNT;
                    V_QUEUE       :=  'Q_'  || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);

                    DBMS_AQ.DEQUEUE(
                             QUEUE_NAME           => ERROR_QUEUE,
                             dequeue_options      => V_DEQUEUE_OPTIONS,
                             MESSAGE_PROPERTIES   => V_ERR_MESSAGE_PROPERTIES,
                             PAYLOAD              => M_LIFECYCLE,
                             MSGID                => MSGID);

                     IF(V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY IS NULL) THEN
                       V_MESSAGE_PROPERTIES.USER_PROPERTY := SYS.ANYDATA.CONVERTNUMBER(M_LIFECYCLE.ID);
                     ELSE
                       V_MESSAGE_PROPERTIES.USER_PROPERTY := V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY;
                     END IF;

                    DBMS_AQ.ENQUEUE(
                          QUEUE_NAME              => V_QUEUE,
                          ENQUEUE_OPTIONS         => V_ERR_ENQUEUE_OPTIONS,
                          MESSAGE_PROPERTIES      => V_MESSAGE_PROPERTIES,
                          PAYLOAD                 => M_LIFECYCLE,
                          MSGID                   => V_MESSAGE_HANDLE
                    );

                    DEQUEUED_MESSAGE := DEQUEUED_MESSAGE + 1;
                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - MESSAGGIO ' || MSGID || ' SPOSTATO DA ' || ERROR_QUEUE || ' IN ' || V_QUEUE || ':' || V_MESSAGE_HANDLE, ADC_PKG_COMMON.INFO_LEVEL,'');
                    /* IF(QUEUE_COUNT = QUEUE_NUMBER) THEN
                      QUEUE_COUNT := 0;
                    END IF; */
                END LOOP;
            EXCEPTION WHEN NO_MESSAGES THEN
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - NO MORE MESSAGES IN ' || ERROR_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
            END;

          ELSIF (V_VIRTUAL_QUEUE = 'OL_LIFECYCLE') THEN

            BEGIN

                LOOP

                    QUEUE_COUNT := 1;
                    QUEUE_SUFFIX := '0'||QUEUE_COUNT;
                    V_QUEUE       :=  'Q_'  || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);

                    DBMS_AQ.DEQUEUE(
                             QUEUE_NAME           => ERROR_QUEUE,
                             dequeue_options      => V_DEQUEUE_OPTIONS,
                             MESSAGE_PROPERTIES   => V_ERR_MESSAGE_PROPERTIES,
                             PAYLOAD              => M_LIFECYCLE,
                             MSGID                => MSGID);

                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - MESSAGGIO SPOSTATO DA ' || ERROR_QUEUE || ' A ' || V_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');

                    IF(V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY IS NULL) THEN
                      V_MESSAGE_PROPERTIES.USER_PROPERTY := SYS.ANYDATA.CONVERTNUMBER(M_LIFECYCLE.ID);
                    ELSE
                      V_MESSAGE_PROPERTIES.USER_PROPERTY := V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY;
                    END IF;

                    DBMS_AQ.ENQUEUE(
                          QUEUE_NAME              => V_QUEUE,
                          ENQUEUE_OPTIONS         => V_ERR_ENQUEUE_OPTIONS,
                          MESSAGE_PROPERTIES      => V_MESSAGE_PROPERTIES,
                          PAYLOAD                 => M_LIFECYCLE,
                          MSGID                   => V_MESSAGE_HANDLE
                    );

                    DEQUEUED_MESSAGE := DEQUEUED_MESSAGE + 1;
                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - MESSAGGIO ' || MSGID || ' SPOSTATO DA ' || ERROR_QUEUE || ' IN ' || V_QUEUE || ':' || V_MESSAGE_HANDLE, ADC_PKG_COMMON.INFO_LEVEL,'');


                END LOOP;
            EXCEPTION WHEN NO_MESSAGES THEN
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - NO MORE MESSAGES IN ' || ERROR_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
            END;

          ELSIF (V_VIRTUAL_QUEUE = 'BL_LIFECYCLE') THEN

            BEGIN

                LOOP

                    QUEUE_COUNT := 1;
                    QUEUE_SUFFIX := '0'||QUEUE_COUNT;
                    V_QUEUE       :=  'Q_'  || V_VIRTUAL_QUEUE || '_' || SUBSTR(QUEUE_SUFFIX, LENGTH(QUEUE_SUFFIX) -1);

                    DBMS_AQ.DEQUEUE(
                             QUEUE_NAME           => ERROR_QUEUE,
                             dequeue_options      => V_DEQUEUE_OPTIONS,
                             MESSAGE_PROPERTIES   => V_ERR_MESSAGE_PROPERTIES,
                             PAYLOAD              => M_LIFECYCLE,
                             MSGID                => MSGID);

                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - MESSAGGIO SPOSTATO DA ' || ERROR_QUEUE || ' A ' || V_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');

                    IF(V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY IS NULL) THEN
                      V_MESSAGE_PROPERTIES.USER_PROPERTY := SYS.ANYDATA.CONVERTNUMBER(M_LIFECYCLE.ID);
                    ELSE
                      V_MESSAGE_PROPERTIES.USER_PROPERTY := V_ERR_MESSAGE_PROPERTIES.USER_PROPERTY;
                    END IF;

                    DBMS_AQ.ENQUEUE(
                          QUEUE_NAME              => V_QUEUE,
                          ENQUEUE_OPTIONS         => V_ERR_ENQUEUE_OPTIONS,
                          MESSAGE_PROPERTIES      => V_MESSAGE_PROPERTIES,
                          PAYLOAD                 => M_LIFECYCLE,
                          MSGID                   => V_MESSAGE_HANDLE
                    );

                    DEQUEUED_MESSAGE := DEQUEUED_MESSAGE + 1;
                    LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - MESSAGGIO ' || MSGID || ' SPOSTATO DA ' || ERROR_QUEUE || ' IN ' || V_QUEUE || ':' || V_MESSAGE_HANDLE, ADC_PKG_COMMON.INFO_LEVEL,'');

                END LOOP;
            EXCEPTION WHEN NO_MESSAGES THEN
                LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - NO MORE MESSAGES IN ' || ERROR_QUEUE, ADC_PKG_COMMON.INFO_LEVEL,'');
            END;

          END IF;

          LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'RECOVERY_ERROR_MESSAGES - RIPRISTINATI ' || DEQUEUED_MESSAGE || ' MESSAGGI', ADC_PKG_COMMON.INFO_LEVEL,'');
          COMMIT;

          EXCEPTION WHEN OTHERS THEN
              LOGRESULT := ADC_PKG_COMMON.LOGGER(LOGGER_NAME, 'ERRORE NELLO SPOSTAMENTO', ADC_PKG_COMMON.ERROR_LEVEL,'');
              ROLLBACK;
          END;

  END RECOVERY_ERROR_MESSAGES;

END ADC_PKG_LOAD_USAGE;
/
